fn native_atomic_by_key(key: &str) -> Option<NativeAtomicCapability> {
    native_atomic_capabilities()
        .iter()
        .copied()
        .find(|capability| capability.key == key)
}

fn native_atomic_capability_entries() -> Vec<CapabilityEntry> {
    native_atomic_capabilities()
        .iter()
        .map(|capability| CapabilityEntry {
            key: capability.key.to_string(),
            desc: capability.description.to_string(),
            text: format!(
                "{} {} {} {}",
                capability.key, capability.tool_name, capability.description, capability.route_text
            ),
            schema: Some((capability.schema)()),
            is_skill: false,
            source: CapabilitySource::NativeAtomic,
        })
        .collect()
}

fn workflow_execution_plan(
    definition: &WorkflowDefinition,
    arguments: serde_json::Value,
) -> ExecutionPlan {
    ExecutionPlan {
        route: OrchestratorRoute::MixedWorkflow,
        direct_answer: None,
        plan_propose: None,
        steps: definition
            .steps
            .iter()
            .map(|step| PlanStep {
                step_id: step.id.to_string(),
                kind: PlanStepKind::DirectAnswer,
                depends_on: step
                    .depends_on
                    .iter()
                    .map(|value| value.to_string())
                    .collect(),
                provider_id: None,
                tool_name: Some(definition.tool_name.to_string()),
                arguments: serde_json::json!({
                    "workflow_id": definition.id,
                    "step_title": step.title,
                    "input": arguments,
                }),
                execution_policy: StepExecutionPolicy::Immediate,
                risk_level: "low".to_string(),
                expected_duration_seconds: 0,
                agent_id: None,
                goal: Some(step.title.to_string()),
                contract: Some(definition.contract.to_string()),
                allowed_actions: vec![],
                requires_user_approval: None,
                timeout_seconds: None,
                max_tokens: None,
            })
            .collect(),
        needs_more_tools: None,
    }
}

fn run_static_workflow_plan_through_brain(
    goal: &str,
    plan: ExecutionPlan,
) -> Result<ExecutionPlan, String> {
    let router = build_browser_inference_router();
    let mut brain = OrchestratorBrain::new(
        router,
        GatewayBrainMemory(None),
        CapabilityFacade::new(CapabilityPolicy, InMemoryCapabilityAudit::default()),
        TaskStore::open_in_memory().map_err(|error| error.to_string())?,
    );
    let user = gateway_capability_user_id();
    let workspace = gateway_capability_workspace_id();
    let request = OrchestratorRequest {
        request_id: format!("static_workflow_{}", uuid::Uuid::new_v4().simple()),
        policy_context: PolicyContext {
            user_id: user,
            workspace_id: workspace,
            enabled_providers: Vec::new(),
            privacy_domains: vec!["work".to_string()],
            allowed_actions: vec![ActionClass::Read, ActionClass::Draft],
            max_autonomy_level: 0,
            allow_managed_cloud: false,
        },
        user_message: goal.to_string(),
        conversation_summary: None,
        attachments: Vec::new(),
        budgets: brain_budgets_for_context_window(None),
        language: effective_user_language(),
    };
    let outcome = brain
        .run_plan(request, plan)
        .map_err(|error| error.to_string())?;
    Ok(outcome.plan)
}

async fn run_static_workflow_plan_through_brain_async(
    goal: String,
    plan: ExecutionPlan,
) -> Result<ExecutionPlan, String> {
    tokio::task::spawn_blocking(move || run_static_workflow_plan_through_brain(&goal, plan))
        .await
        .map_err(|error| format!("static workflow validation join error: {error}"))?
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum WorkflowRouteDecision {
    Workflow {
        workflow_id: &'static str,
        tool_name: &'static str,
        scaffolding_tier: &'static str,
    },
    AgentLoop,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum CapabilityRouteDecision {
    Workflow {
        workflow_id: &'static str,
        tool_name: &'static str,
        scaffolding_tier: &'static str,
        reason: String,
        alternatives: Vec<String>,
    },
    AtomicTool {
        capability_key: &'static str,
        reason: String,
    },
    AgentLoop {
        reason: String,
    },
}

fn workflow_route_from_capability(decision: &CapabilityRouteDecision) -> WorkflowRouteDecision {
    match decision {
        CapabilityRouteDecision::Workflow {
            workflow_id,
            tool_name,
            scaffolding_tier,
            ..
        } => WorkflowRouteDecision::Workflow {
            workflow_id,
            tool_name,
            scaffolding_tier,
        },
        CapabilityRouteDecision::AtomicTool { .. } | CapabilityRouteDecision::AgentLoop { .. } => {
            WorkflowRouteDecision::AgentLoop
        }
    }
}

fn route_capability_from_semantic(
    semantic: Option<&semantic_decision::ValidatedSemanticDecision>,
) -> CapabilityRouteDecision {
    let Some(semantic) = semantic else {
        return CapabilityRouteDecision::AgentLoop {
            reason: "No validated semantic decision; safe agent-loop fallback.".to_string(),
        };
    };
    match semantic.decision.execution_shape {
        semantic_decision::ExecutionShape::AgentLoop => CapabilityRouteDecision::AgentLoop {
            reason: semantic.decision.rationale.clone(),
        },
        semantic_decision::ExecutionShape::Workflow => {
            let Some(tool_name) = semantic.decision.selected_capability.as_deref() else {
                return CapabilityRouteDecision::AgentLoop {
                    reason: "Validated workflow decision omitted its capability; safe fallback."
                        .to_string(),
                };
            };
            let Some(capability) = native_workflow_by_tool_name(tool_name) else {
                return CapabilityRouteDecision::AgentLoop {
                    reason: "Validated workflow capability is unavailable; safe fallback."
                        .to_string(),
                };
            };
            CapabilityRouteDecision::Workflow {
                workflow_id: capability.workflow_id,
                tool_name: capability.tool_name,
                scaffolding_tier: capability.scaffolding_tier,
                reason: format!(
                    "Selected by semantic decision schema v{}: {}",
                    semantic.provenance.schema_version, semantic.decision.rationale
                ),
                alternatives: Vec::new(),
            }
        }
        semantic_decision::ExecutionShape::AtomicCapability => {
            if let Some(capability_key) = semantic
                .decision
                .selected_capability
                .as_deref()
                .and_then(native_atomic_by_key)
                .map(|capability| capability.key)
            {
                CapabilityRouteDecision::AtomicTool {
                    capability_key,
                    reason: semantic.decision.rationale.clone(),
                }
            } else {
                CapabilityRouteDecision::AgentLoop {
                    reason: "Validated atomic capability is unavailable; safe fallback."
                        .to_string(),
                }
            }
        }
    }
}

/// S2 (plugin-owned deterministic routing): an active `RoutingBinding` — thread-scoped,
/// set once when the user picks a template/route (e.g. "Use template"; see
/// `RoutingBinding` in lib.rs, `ChatStore::thread_routing_binding`) — decides the route
/// DIRECTLY when it resolves to a registered `WorkflowRouting`. This is not natural-language
/// inference: the binding records an exact route the user already selected.
///
/// `enabled: &|_| true` — not a plugin-enablement gate — because the persisted binding
/// itself IS the enablement signal: the user already chose this route this thread.
///
/// Without a valid explicit binding, routing consumes the validated model-owned semantic
/// decision. It never derives a route from prompt keywords or retrieval rank.
fn route_capability_with_binding(
    semantic: Option<&semantic_decision::ValidatedSemanticDecision>,
    binding: Option<&RoutingBinding>,
) -> CapabilityRouteDecision {
    if let Some(binding) = binding {
        let registry = WorkflowRoutingRegistry::system();
        let forced = registry
            .routings(&|_| true)
            .into_iter()
            .find(|routing| routing.deterministic && routing.route_id == binding.route_id)
            .and_then(|routing| {
                native_workflow_by_tool_name(&routing.tool_name)
                    .map(|capability| (routing, capability))
            });
        if let Some((routing, capability)) = forced {
            return CapabilityRouteDecision::Workflow {
                workflow_id: capability.workflow_id,
                tool_name: capability.tool_name,
                scaffolding_tier: capability.scaffolding_tier,
                reason: format!("deterministic plugin routing: {}", routing.route_id),
                alternatives: vec![],
            };
        }
    }
    route_capability_from_semantic(semantic)
}

/// S2 T4: read the thread's active deterministic `RoutingBinding`, if any. Single fail-open
/// helper (no thread_id / no store lock / no persisted binding / malformed JSON → `None`,
/// ordinary unbound behaviour) shared by the router seam and the `make_deck`/`make_document`
/// dispatch arms, which both need the SAME binding read (previously only the router read it —
/// duplicating the lock-and-parse there and in the two tool-exec arms was the alternative).
fn active_routing_binding(state: &AppState, thread_id: Option<&str>) -> Option<RoutingBinding> {
    thread_id
        .and_then(|tid| {
            lock_store(state)
                .ok()
                .and_then(|store| store.thread_routing_binding(tid).ok().flatten())
        })
        .and_then(|json| serde_json::from_str::<RoutingBinding>(&json).ok())
}

/// S2 T4: resolve an active binding back to its registered `WorkflowRouting` (for
/// `deny_tools`/`tool_name`). Mirrors the lookup inside `route_capability_with_binding`, which
/// only needs to know THAT a match exists to force the route; the hard-prune call site needs
/// the full routing (its `deny_tools`), hence the separate accessor.
fn resolve_workflow_routing(
    binding: &RoutingBinding,
) -> Option<local_first_capabilities::WorkflowRouting> {
    WorkflowRoutingRegistry::system()
        .routings(&|_| true)
        .into_iter()
        .find(|routing| routing.deterministic && routing.route_id == binding.route_id)
        .cloned()
}

/// S2 T5: the forced-`tool_choice` decision for THIS turn, pure and independent of the store —
/// given the turn's resolved routing (if any) and how many user messages the thread already
/// carries. `Specific` forcing pins the model to `tool_name`, but only once the intake exchange
/// is past its first round (see the call site for the exact turn-index rationale); every other
/// combination (no routing, non-`Specific` forcing, still on turn 1) stays `None` = "auto".
fn forced_tool_for_turn(
    routing: Option<&local_first_capabilities::WorkflowRouting>,
    user_message_count: usize,
) -> Option<String> {
    let routing = routing?;
    if routing.forcing != local_first_capabilities::Forcing::Specific {
        return None;
    }
    if user_message_count < 2 {
        return None;
    }
    Some(routing.tool_name.clone())
}

/// S2 T5: how many USER messages a thread has, from an already-loaded snapshot. Pure (no store),
/// so the turn-index heuristic is trivially testable independent of `ChatStore`/`AppState`.
fn thread_user_message_count(snapshot: &ChatMessagesSnapshot) -> usize {
    snapshot
        .messages
        .iter()
        .filter(|message| message.role == "user")
        .count()
}

/// S2 T5: fail-open wrapper reading the thread's message count off the real store. No thread_id /
/// no store lock / no rows → 0 — the safe default, since `forced_tool_for_turn` treats a count
/// below 2 as "still the first turn" and keeps `tool_choice` on "auto". Mirrors the fail-open
/// shape of `active_routing_binding` just above.
fn thread_user_message_count_fail_open(state: &AppState, thread_id: Option<&str>) -> usize {
    thread_id
        .and_then(|tid| {
            lock_store(state)
                .ok()
                .and_then(|store| store.messages(tid).ok())
        })
        .map(|snapshot| thread_user_message_count(&snapshot))
        .unwrap_or(0)
}

fn capability_router_instruction_for_decision(
    decision: &CapabilityRouteDecision,
) -> Option<String> {
    match decision {
        CapabilityRouteDecision::Workflow {
            workflow_id,
            tool_name,
            scaffolding_tier,
            reason,
            ..
        } => Some(format!(
            "CAPABILITY ROUTER: this request is routed by the harness to workflow `{workflow_id}` \
with `{scaffolding_tier}` scaffolding. Reason: {reason} Call `{tool_name}` exactly once with the user's brief; \
do not create a separate plan, do not decompose it into lower-level tools, and do not use shell/file tools for this workflow."
        )),
        CapabilityRouteDecision::AtomicTool {
            capability_key,
            reason,
        } => Some(format!(
            "CAPABILITY ROUTER: this request is classified as atomic capability `{capability_key}`. \
Reason: {reason} Do not call end-to-end deliverable workflows such as `make_document` for this request. \
Use the most specific atomic/tool capability available, or call `find_capability` if it is not already loaded."
        )),
        CapabilityRouteDecision::AgentLoop { .. } => None,
    }
}

fn capability_route_trace_line(decision: &CapabilityRouteDecision) -> Option<String> {
    match decision {
        CapabilityRouteDecision::Workflow {
            workflow_id,
            tool_name,
            reason,
            alternatives,
            ..
        } => Some(format!(
            "capability route: workflow {workflow_id}/{tool_name}; reason={reason}; alternatives={}",
            if alternatives.is_empty() {
                "none".to_string()
            } else {
                alternatives.join(",")
            }
        )),
        CapabilityRouteDecision::AtomicTool {
            capability_key,
            reason,
        } => Some(format!(
            "capability route: atomic {capability_key}; reason={reason}"
        )),
        CapabilityRouteDecision::AgentLoop { .. } => None,
    }
}

fn prune_tools_for_workflow_route(
    tools: &mut Vec<serde_json::Value>,
    route: &WorkflowRouteDecision,
) {
    if let WorkflowRouteDecision::Workflow { tool_name, .. } = route {
        tools.retain(|schema| {
            schema
                .pointer("/function/name")
                .and_then(|value| value.as_str())
                == Some(*tool_name)
        });
    }
}

/// S2 T4: hard prune for a deterministic plugin routing — retains ONLY `route_tool` and
/// explicitly denies anything matching the resolved `WorkflowRouting`'s `deny_tools`
/// (`local_first_capabilities::tool_matches_deny`: `skill:*`, `run_command`, `shell`, the
/// sibling `make_*`). The deny check is evaluated first so a hard-denied name can never slip
/// through even if it happened to equal `route_tool` — belt-and-suspenders against a
/// misconfigured registry entry. Functionally this retains the same single tool
/// `prune_tools_for_workflow_route` does today (kept unchanged as the plain wrapper for the
/// non-plugin-routed case); this variant exists so the registry's `deny_tools` — not ad hoc
/// gateway logic — is what a plugin route can rely on to starve every other tool, including
/// ones a later stage of tool assembly (MCP/Composio) might reintroduce by name.
fn prune_tools_for_route_and_deny(
    tools: &mut Vec<serde_json::Value>,
    route_tool: &str,
    deny: &[String],
) {
    tools.retain(|schema| {
        let name = schema
            .pointer("/function/name")
            .and_then(|value| value.as_str())
            .unwrap_or("");
        !local_first_capabilities::tool_matches_deny(deny, name) && name == route_tool
    });
}

/// S2 T4: single call-site dispatcher for the two prune call sites in the tool-assembly
/// pipeline — plain retain-only-route-tool (`deny_tools` empty, i.e. no deterministic
/// binding survived plan-precedence) or the hard deny-aware prune (binding active).
fn prune_tools_for_route(
    tools: &mut Vec<serde_json::Value>,
    route: &WorkflowRouteDecision,
    deny_tools: &[String],
) {
    if deny_tools.is_empty() {
        prune_tools_for_workflow_route(tools, route);
        return;
    }
    if let WorkflowRouteDecision::Workflow { tool_name, .. } = route {
        prune_tools_for_route_and_deny(tools, tool_name, deny_tools);
    }
}

fn workflow_route_blocked_tool_message(
    route: &CapabilityRouteDecision,
    tool_name: &str,
) -> Option<String> {
    match route {
        CapabilityRouteDecision::Workflow {
            workflow_id,
            tool_name: workflow_tool,
            ..
        } if tool_name != *workflow_tool => Some(format!(
            "WORKFLOW_ROUTE_BLOCKED_TOOL: this turn is routed to workflow `{workflow_id}`. \
Tool `{tool_name}` is not allowed here. Do not create files manually, do not use shell/filesystem \
fallbacks, and do not decompose the workflow. Use `{workflow_tool}` exactly once; if `{workflow_tool}` \
already failed because the provider is unavailable, stop and tell the user to choose a reachable \
provider or start the required local service."
        )),
        _ => None,
    }
}

fn runtime_plan_memory_matches(memory: &MemoryRecord, thread_key: &str) -> bool {
    memory.memory_type == "open_loop"
        && !matches!(
            memory.status,
            MemoryStatus::Deleted | MemoryStatus::Rejected | MemoryStatus::Stale
        )
        && memory.metadata.get("source").and_then(|v| v.as_str()) == Some("runtime_plan")
        && memory.metadata.get("thread_id").and_then(|v| v.as_str()) == Some(thread_key)
}

/// Load the thread's CANONICAL plan steps from the durable runtime-plan store (the same
/// per-thread runtime-plan memory represents). This is the authoritative
/// cross-turn state: it's upserted on EVERY `update_plan`/`step_advance` (synchronously,
/// before a turn ends), so a CONTINUATION turn can inherit `{done,doing,…}` even before the
/// prior turn's ‹‹PLAN›› message has been persisted/streamed into the next turn's context.
/// Returns the steps (with verified statuses) or empty if the thread has no open plan.
#[cfg(test)]
fn load_runtime_plan_from_state(
    state: &AppState,
    thread_id: Option<&str>,
) -> Vec<serde_json::Value> {
    runtime_plan_record_from_state(state, thread_id)
        .map(|(_, steps)| steps)
        .unwrap_or_default()
}

/// Shared reader of the thread's open runtime plan: the steps + the optional goal. Tolerates BOTH
/// persistence shapes — the current `{"goal", "steps"}` object and the LEGACY bare step array —
/// so plans written before the goal upgrade keep loading unchanged.
fn runtime_plan_record_from_state(
    state: &AppState,
    thread_id: Option<&str>,
) -> Option<(Option<String>, Vec<serde_json::Value>)> {
    let (user_id, workspace_id, thread_id) = runtime_plan_control_scope(state, thread_id)?;
    let plan = state
        .task_store
        .lock()
        .ok()
        .and_then(|store| {
            store
                .load_runtime_plan(&user_id, &workspace_id, &thread_id)
                .ok()
                .flatten()
        })
        .filter(|plan| plan.status == "open")?;
    let goal = local_first_engine::plan::plan_value_goal(&plan.plan_json);
    let steps = local_first_engine::plan::plan_value_steps(&plan.plan_json);
    Some((goal, steps))
}

fn runtime_plan_step_outcome_matches(
    memory: &MemoryRecord,
    thread_key: &str,
    step_id: &str,
) -> bool {
    memory.memory_type == "fact"
        && !matches!(
            memory.status,
            MemoryStatus::Deleted | MemoryStatus::Rejected | MemoryStatus::Stale
        )
        && memory.metadata.get("source").and_then(|v| v.as_str()) == Some("runtime_plan_step")
        && memory.metadata.get("thread_id").and_then(|v| v.as_str()) == Some(thread_key)
        && memory.metadata.get("step_id").and_then(|v| v.as_str()) == Some(step_id)
}

fn record_runtime_plan_step_outcome(
    facade: &MemoryFacade,
    user: &MemoryUserId,
    workspace: &MemoryWorkspaceId,
    lifecycle: &MemoryLifecycleRequest,
    thread_id: Option<&str>,
    step: &serde_json::Value,
    evidence: &[String],
) -> Result<MemoryRef, String> {
    let thread_key = runtime_plan_thread_key(thread_id);
    let title = plan_step_title(step).trim();
    if title.is_empty() {
        return Err("runtime plan step outcome requires a title".to_string());
    }
    let step_id = plan_step_id(step).unwrap_or(title);
    let done_criterion = step
        .get("done_criterion")
        .and_then(|value| value.as_str())
        .unwrap_or("")
        .trim();
    let text = if done_criterion.is_empty() {
        format!("Runtime plan step completed: {title}.")
    } else {
        format!("Runtime plan step completed: {title}. Done criterion: {done_criterion}.")
    };
    let metadata = serde_json::json!({
        "source": "runtime_plan_step",
        "thread_id": thread_key,
        "execution_plan_ref": format!("runtime_plan:{thread_key}"),
        "step_id": step_id,
        "title": title,
        "status": "done",
        "done_criterion": done_criterion,
        "detail": step.get("detail").cloned().unwrap_or(serde_json::Value::Null),
        "evidence": evidence,
    });

    let existing = facade
        .list_memories_for_ui(user, workspace)
        .unwrap_or_default()
        .into_iter()
        .find(|memory| runtime_plan_step_outcome_matches(memory, &thread_key, step_id));

    let record = if let Some(existing) = existing {
        facade
            .update_memory(
                lifecycle,
                &existing.reference,
                MemoryUpdatePatch {
                    text: Some(text),
                    aliases: None,
                    language_hints: None,
                    confidence: Some(1.0),
                    privacy_domain: Some(PrivacyDomain::new("work")),
                    sensitivity: Some(MemoryDataSensitivity::Internal),
                    metadata: Some(metadata),
                    last_seen_at: None,
                },
            )
            .map_err(|error| error.to_string())?
    } else {
        facade
            .create_memory_candidate(MemoryCreateRequest {
                request: lifecycle.clone(),
                memory_type: "fact".to_string(),
                text,
                aliases: Vec::new(),
                language_hints: Vec::new(),
                confidence: 1.0,
                privacy_domain: PrivacyDomain::new("work"),
                sensitivity: MemoryDataSensitivity::Internal,
                evidence_refs: Vec::new(),
                metadata,
            })
            .map_err(|error| error.to_string())?
    };
    facade
        .confirm_memory(lifecycle, &record.reference, "runtime plan step verified")
        .map_err(|error| error.to_string())?;
    Ok(record.reference)
}

fn record_runtime_plan_step_outcome_from_state(
    state: &AppState,
    thread_id: Option<&str>,
    step: &serde_json::Value,
    evidence: &[String],
) {
    let facade = memory_facade(state);
    let user = gateway_memory_user_id();
    let workspace = gateway_memory_workspace_id();
    let lifecycle = MemoryLifecycleRequest {
        actor_id: "runtime-plan".to_string(),
        user_id: user.clone(),
        workspace_id: workspace.clone(),
        purpose: "runtime_plan_step_verified".to_string(),
    };
    if record_runtime_plan_step_outcome(
        facade, &user, &workspace, &lifecycle, thread_id, step, evidence,
    )
    .is_ok()
    {
        rebuild_status_wiki(facade, &user, &workspace);
    }
}

fn record_subagent_task_step_outcome_memory(
    facade: &MemoryFacade,
    user: &MemoryUserId,
    workspace: &MemoryWorkspaceId,
    lifecycle: &MemoryLifecycleRequest,
    thread_id: Option<&str>,
    task: &TaskRecord,
    outcome: &TaskExecutionPresentation,
) -> Result<Option<MemoryRef>, String> {
    if !task.kind.starts_with("subagent.") {
        return Ok(None);
    }
    let title = task
        .input_json
        .get("goal")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .unwrap_or(task.kind.as_str());
    let done_criterion = task
        .input_json
        .get("contract")
        .and_then(Value::as_str)
        .unwrap_or("sub-agent task completed");
    let step = serde_json::json!({
        "id": task.task_id.as_str(),
        "title": title,
        "status": "done",
        "detail": {
            "task_kind": task.kind.as_str(),
            "summary": outcome.summary,
        },
        "done_criterion": done_criterion,
    });
    let evidence = vec![
        serde_json::json!({
            "source": "subagent_task",
            "task_id": task.task_id.as_str(),
            "kind": task.kind.as_str(),
            "checkpoint": outcome.checkpoint_redacted,
        })
        .to_string(),
    ];
    record_runtime_plan_step_outcome(
        facade, user, workspace, lifecycle, thread_id, &step, &evidence,
    )
    .map(Some)
}

fn record_subagent_task_step_outcome(
    state: &AppState,
    task: &TaskRecord,
    outcome: &TaskExecutionPresentation,
) {
    let thread_id = lock_store(state)
        .ok()
        .and_then(|store| {
            store
                .thread_by_task_id(task.task_id.as_str())
                .ok()
                .flatten()
        })
        .map(|thread| thread.thread_id);
    let facade = memory_facade(state);
    let user = gateway_memory_user_id();
    let workspace = gateway_memory_workspace_id();
    let lifecycle = MemoryLifecycleRequest {
        actor_id: "runtime-plan".to_string(),
        user_id: user.clone(),
        workspace_id: workspace.clone(),
        purpose: "subagent_plan_step_verified".to_string(),
    };
    if record_subagent_task_step_outcome_memory(
        facade,
        &user,
        &workspace,
        &lifecycle,
        thread_id.as_deref(),
        task,
        outcome,
    )
    .is_ok()
    {
        rebuild_status_wiki(facade, &user, &workspace);
    }
}

fn upsert_runtime_plan_graph(
    facade: &MemoryFacade,
    user: &MemoryUserId,
    workspace: &MemoryWorkspaceId,
    privacy_domain: &str,
    memory_ref: &MemoryRef,
    thread_key: &str,
    plan: &[serde_json::Value],
) -> Result<(), String> {
    let plan_key = format!("runtime_plan:{thread_key}");
    let plan_ref = MemoryRef::new(
        MemoryRefKind::Entity,
        user.clone(),
        workspace.clone(),
        plan_key.clone(),
    );
    facade
        .upsert_entity(&MemoryEntity {
            reference: plan_ref.clone(),
            user_id: user.clone(),
            workspace_id: workspace.clone(),
            entity_type: "document".to_string(),
            name: format!("Runtime plan {thread_key}"),
            canonical_key: plan_key,
            aliases: vec![thread_key.to_string()],
            privacy_domain: PrivacyDomain::new(privacy_domain),
            sensitivity: MemoryDataSensitivity::Internal,
            metadata: serde_json::json!({
                "source": "runtime_plan",
                "kind": "runtime_plan",
                "thread_id": thread_key,
                "status": if plan_is_complete(plan) { "complete" } else { "open" },
                "done_count": plan_done_count(plan),
                "total_count": plan.len(),
                "next_step": plan_next_open(plan),
                "execution_plan": runtime_execution_plan(plan),
            }),
        })
        .map_err(|error| error.to_string())?;
    upsert_memory_relation(
        facade,
        user,
        workspace,
        privacy_domain,
        format!(
            "runtime_plan_described_by:{}",
            provenance_key_fragment(thread_key)
        ),
        memory_ref.clone(),
        "describes",
        plan_ref.clone(),
        vec![memory_ref.clone()],
        serde_json::json!({
            "source": "runtime_plan",
            "thread_id": thread_key,
        }),
    )?;

    let step_refs: std::collections::HashMap<String, MemoryRef> = plan
        .iter()
        .filter_map(|step| {
            let id = plan_step_id(step)?;
            Some((
                id.to_string(),
                MemoryRef::new(
                    MemoryRefKind::Entity,
                    user.clone(),
                    workspace.clone(),
                    format!("runtime_plan:{thread_key}:step:{id}"),
                ),
            ))
        })
        .collect();

    for (index, step) in plan.iter().enumerate() {
        let Some(step_id) = plan_step_id(step) else {
            continue;
        };
        let step_ref = step_refs
            .get(step_id)
            .cloned()
            .expect("step ref built from same step id");
        let title = plan_step_title(step);
        facade
            .upsert_entity(&MemoryEntity {
                reference: step_ref.clone(),
                user_id: user.clone(),
                workspace_id: workspace.clone(),
                entity_type: "asset".to_string(),
                name: if title.is_empty() {
                    step_id.to_string()
                } else {
                    title.to_string()
                },
                canonical_key: format!("runtime_plan:{thread_key}:step:{step_id}"),
                aliases: vec![step_id.to_string()],
                privacy_domain: PrivacyDomain::new(privacy_domain),
                sensitivity: MemoryDataSensitivity::Internal,
                metadata: serde_json::json!({
                    "source": "runtime_plan",
                    "kind": "runtime_plan_step",
                    "thread_id": thread_key,
                    "step_id": step_id,
                    "index": index,
                    "title": title,
                    "status": plan_step_status(step),
                    "detail": step.get("detail").cloned().unwrap_or(serde_json::Value::Null),
                    "done_criterion": step.get("done_criterion").cloned().unwrap_or(serde_json::Value::Null),
                }),
            })
            .map_err(|error| error.to_string())?;
        upsert_memory_relation(
            facade,
            user,
            workspace,
            privacy_domain,
            format!(
                "runtime_plan_step:{}:{}",
                provenance_key_fragment(thread_key),
                provenance_key_fragment(step_id)
            ),
            plan_ref.clone(),
            "relates_to",
            step_ref.clone(),
            vec![memory_ref.clone()],
            serde_json::json!({
                "source": "runtime_plan",
                "kind": "has_step",
                "thread_id": thread_key,
                "step_id": step_id,
                "index": index,
            }),
        )?;

        let dependencies = plan_step_depends_on(step);
        for dependency_id in dependencies {
            let Some(dependency_ref) = step_refs.get(&dependency_id) else {
                continue;
            };
            upsert_memory_relation(
                facade,
                user,
                workspace,
                privacy_domain,
                format!(
                    "runtime_plan_step_depends:{}:{}:{}",
                    provenance_key_fragment(thread_key),
                    provenance_key_fragment(step_id),
                    provenance_key_fragment(&dependency_id)
                ),
                step_ref.clone(),
                "depends_on",
                dependency_ref.clone(),
                vec![memory_ref.clone()],
                serde_json::json!({
                    "source": "runtime_plan",
                    "thread_id": thread_key,
                    "step_id": step_id,
                    "depends_on": dependency_id,
                }),
            )?;
        }
    }
    Ok(())
}

fn upsert_runtime_plan_memory(
    facade: &MemoryFacade,
    user: &MemoryUserId,
    workspace: &MemoryWorkspaceId,
    lifecycle: &MemoryLifecycleRequest,
    thread_id: Option<&str>,
    plan: &[serde_json::Value],
) -> Result<Option<MemoryRef>, String> {
    let Some(text) = runtime_plan_memory_text(plan) else {
        return Ok(None);
    };
    let thread_key = runtime_plan_thread_key(thread_id);
    // Terminate (stop auto-resuming) when the plan is SETTLED — every step done OR blocked —
    // not only when fully complete. A blocked step is terminal: keeping such a plan "active"
    // is exactly the F4 infinite-resume loop. settled == complete when no step is blocked, so
    // this is behaviour-preserving for ordinary plans.
    let settled = plan_is_settled(plan);
    let mut metadata = runtime_plan_memory_metadata(thread_id, plan);
    let existing = facade
        .list_memories_for_ui(user, workspace)
        .unwrap_or_default()
        .into_iter()
        .find(|memory| runtime_plan_memory_matches(memory, &thread_key));

    match existing {
        Some(existing) => {
            // Carry the F4 cross-turn stall bookkeeping forward: it lives on the plan memory
            // but `runtime_plan_memory_metadata` rebuilds metadata from the steps alone, so a
            // mid-turn upsert would otherwise wipe the counter the turn-start guard wrote.
            if let Some(obj) = metadata.as_object_mut() {
                for key in ["stall_turns", "last_resume_done"] {
                    if let Some(value) = existing.metadata.get(key) {
                        obj.insert(key.to_string(), value.clone());
                    }
                }
            }
            let record = facade
                .update_memory(
                    lifecycle,
                    &existing.reference,
                    MemoryUpdatePatch {
                        text: Some(text),
                        aliases: None,
                        language_hints: None,
                        confidence: Some(1.0),
                        privacy_domain: Some(PrivacyDomain::new("work")),
                        sensitivity: Some(MemoryDataSensitivity::Internal),
                        metadata: Some(metadata),
                        last_seen_at: None,
                    },
                )
                .map_err(|error| error.to_string())?;
            if settled {
                facade
                    .mark_memory_stale(lifecycle, &record.reference, "runtime plan settled")
                    .map_err(|error| error.to_string())?;
            } else {
                facade
                    .confirm_memory(lifecycle, &record.reference, "runtime plan updated")
                    .map_err(|error| error.to_string())?;
            }
            upsert_runtime_plan_graph(
                facade,
                user,
                workspace,
                "work",
                &record.reference,
                &thread_key,
                plan,
            )?;
            Ok(Some(record.reference))
        }
        None if settled => Ok(None),
        None => {
            let record = facade
                .create_memory_candidate(MemoryCreateRequest {
                    request: lifecycle.clone(),
                    memory_type: "open_loop".to_string(),
                    text,
                    aliases: Vec::new(),
                    language_hints: Vec::new(),
                    confidence: 1.0,
                    privacy_domain: PrivacyDomain::new("work"),
                    sensitivity: MemoryDataSensitivity::Internal,
                    evidence_refs: Vec::new(),
                    metadata,
                })
                .map_err(|error| error.to_string())?;
            facade
                .confirm_memory(lifecycle, &record.reference, "runtime plan opened")
                .map_err(|error| error.to_string())?;
            upsert_runtime_plan_graph(
                facade,
                user,
                workspace,
                "work",
                &record.reference,
                &thread_key,
                plan,
            )?;
            Ok(Some(record.reference))
        }
    }
}

fn upsert_runtime_plan_memory_from_state(
    state: &AppState,
    thread_id: Option<&str>,
    goal: Option<&str>,
    plan: &[serde_json::Value],
) {
    let Some((user_id, workspace_id, thread_key)) = runtime_plan_control_scope(state, thread_id)
    else {
        eprintln!("runtime plan skipped: thread scope could not be resolved");
        return;
    };
    let status = if plan_is_settled(plan) {
        "settled"
    } else {
        "open"
    };
    // Canonical persistence shape: `{"goal": <string|null>, "steps": [...]}` (readers tolerate the
    // legacy bare-array form).
    let plan_json = serde_json::json!({ "goal": goal, "steps": plan });
    let canonical_write_ok = state
        .task_store
        .lock()
        .ok()
        .and_then(|store| {
            let objective_revision = store
                .load_objective_contract(&user_id, &workspace_id, &thread_key)
                .ok()
                .flatten()
                .map(|objective| objective.revision)
                .unwrap_or(0);
            store
                .upsert_runtime_plan(
                    &user_id,
                    &workspace_id,
                    &thread_key,
                    objective_revision,
                    &plan_json,
                    status,
                )
                .ok()
        })
        .is_some();
    if !canonical_write_ok {
        eprintln!("runtime plan canonical write failed for thread {thread_key}");
        return;
    }

    // Semantic memory remains a best-effort projection for recall and graph navigation.
    // It is no longer consulted for control flow, resumption or stall bookkeeping.
    let facade = memory_facade(state);
    let user = gateway_memory_user_id();
    let workspace = gateway_memory_workspace_id();
    let lifecycle = MemoryLifecycleRequest {
        actor_id: "runtime-plan".to_string(),
        user_id: user.clone(),
        workspace_id: workspace.clone(),
        purpose: "sync_runtime_plan".to_string(),
    };
    if upsert_runtime_plan_memory(facade, &user, &workspace, &lifecycle, thread_id, plan).is_ok() {
        rebuild_status_wiki(facade, &user, &workspace);
    }
}

/// Merge the model's sent steps into the CANONICAL plan (never replace). Match an
/// existing step by title (case-insensitive): a canonical `done` is STICKY — re-sending
/// it as todo/doing can't reopen it (this is what stops the regenerate loop); a NEW
/// `done` claim is held as `doing` and its index returned (pending F2 verification); a
/// new title is appended with a stable id. Returns the canonical indices newly claimed.
fn merge_plan(plan: &mut Vec<serde_json::Value>, sent: &[serde_json::Value]) -> Vec<usize> {
    let tkey = |t: &str| t.trim().to_lowercase();
    let mut claims: Vec<usize> = Vec::new();
    for s in sent {
        let title = s.get("title").and_then(|v| v.as_str()).unwrap_or("").trim();
        // Identity: prefer the stable `id` the model echoes (shown as (`id`) in the
        // ‹‹PLAN›› marker); fall back to title. Id-first stops ballooning from
        // paraphrased titles, AND lets `step_advance` update a step by id ALONE (no
        // title) — the model reports progress without re-sending the whole plan. (WS1-F2.)
        let sent_id = s
            .get("id")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|x| !x.is_empty());
        if title.is_empty() && sent_id.is_none() {
            continue;
        }
        let new_status = s.get("status").and_then(|v| v.as_str()).unwrap_or("todo");
        let detail = s.get("detail").and_then(|v| v.as_str()).unwrap_or("");
        let pos = sent_id
            .and_then(|id| {
                plan.iter()
                    .position(|p| p.get("id").and_then(|v| v.as_str()) == Some(id))
            })
            .or_else(|| {
                if title.is_empty() {
                    None
                } else {
                    plan.iter()
                        .position(|p| tkey(plan_step_title(p)) == tkey(title))
                }
            });
        match pos {
            Some(i) => {
                let current_status = plan_step_status(&plan[i]);
                let harness_blocked = plan[i]
                    .get("detail")
                    .and_then(|v| v.as_str())
                    .map(str::trim)
                    .is_some_and(|detail| detail.starts_with("paused by the harness:"));
                if current_status == "done" {
                    // Sticky: a `done` step never re-opens, which stops regenerate loops.
                } else if current_status == "blocked" {
                    if new_status == "done" && !harness_blocked {
                        plan[i]["status"] = serde_json::json!("doing");
                        claims.push(i);
                    }
                } else if new_status == "done" {
                    plan[i]["status"] = serde_json::json!("doing");
                    claims.push(i);
                } else {
                    plan[i]["status"] = serde_json::json!(new_status);
                }
                if !detail.is_empty() {
                    plan[i]["detail"] = serde_json::json!(detail);
                }
                let depends_on = plan_step_depends_on(s);
                if !depends_on.is_empty() {
                    plan[i]["depends_on"] = serde_json::json!(depends_on);
                }
            }
            None => {
                if title.is_empty() {
                    // id-only update (step_advance) for a step that doesn't exist →
                    // ignore; we never create a titleless step.
                    continue;
                }
                let id = format!("s{}", plan.len() + 1);
                let status = if new_status == "done" {
                    "doing"
                } else {
                    new_status
                };
                plan.push(serde_json::json!({
                    "id": id, "title": title, "status": status, "detail": detail,
                    "done_criterion": s.get("done_criterion").and_then(|v| v.as_str()).unwrap_or(""),
                    "depends_on": plan_step_depends_on(s),
                }));
                if new_status == "done" {
                    claims.push(plan.len() - 1);
                }
            }
        }
    }
    claims
}

fn plan_tool_sent(
    name: &str,
    args_raw: &str,
) -> Result<(Option<String>, Vec<serde_json::Value>), String> {
    let args: serde_json::Value = serde_json::from_str(args_raw)
        .map_err(|_| format!("{name} requires valid JSON arguments"))?;
    if name == "step_advance" {
        let id = ["id", "step_id", "step"]
            .into_iter()
            .find_map(|key| args.get(key).and_then(serde_json::Value::as_str))
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| {
                "Invalid step_advance: provide the stable step `id` from the current Plan card. The plan was not changed."
                    .to_string()
            })?;
        let status = match args
            .get("status")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("doing")
        {
            "complete" | "completed" => "done",
            "in_progress" | "in-progress" => "doing",
            "pending" => "todo",
            status => status,
        };
        return Ok((
            None,
            vec![serde_json::json!({
                "id": id,
                "status": status,
                "detail": args.get("detail").and_then(serde_json::Value::as_str).unwrap_or(""),
            })],
        ));
    }
    // The optional top-level `goal` (the user's objective in one sentence, set when the plan is
    // created). null/empty/whitespace → None → the canonical plan KEEPS its stored goal.
    let goal = args
        .get("goal")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|goal| {
            let normalized = goal.to_ascii_lowercase();
            !goal.is_empty() && !matches!(normalized.as_str(), "null" | "none" | "n/a")
        })
        .map(str::to_string);
    Ok((
        goal,
        args.get("steps")
            .and_then(serde_json::Value::as_array)
            .cloned()
            .unwrap_or_default(),
    ))
}

/// Searches the user's long-term memory (personal + active project) for the query
/// and returns a compact, readable result for the model. Includes confirmed AND
/// candidate items and all sensitivities: the model asked explicitly, and it is
/// the user's own data answered back to the user.
/// Renders a recalled memory for the model. For a DECISION it surfaces the STRUCTURED
/// "why" — the rationale and the rejected alternatives from `metadata.decision` — not
/// just the summary text (the strong reader). Other kinds return the summary as-is.
fn format_recall_entry(summary: &str, metadata: &serde_json::Value) -> String {
    let Some(decision) = metadata.get("decision") else {
        return summary.to_string();
    };
    let mut out = summary.to_string();
    if let Some(rationale) = decision.get("rationale").and_then(|r| r.as_str())
        && !rationale.is_empty()
        && !summary.contains(rationale)
    {
        out.push_str(&format!(" — why: {rationale}"));
    }
    if let Some(alternatives) = decision.get("alternatives").and_then(|a| a.as_array()) {
        let rejected: Vec<String> = alternatives
            .iter()
            .filter_map(|alt| {
                let option = alt.get("option").and_then(|o| o.as_str())?;
                if option.is_empty() {
                    return None;
                }
                let why = alt
                    .get("rejected_because")
                    .and_then(|w| w.as_str())
                    .unwrap_or("");
                Some(if why.is_empty() {
                    option.to_string()
                } else {
                    format!("{option} (rejected: {why})")
                })
            })
            .collect();
        if !rejected.is_empty() {
            out.push_str(&format!(
                " [rejected alternatives: {}]",
                rejected.join("; ")
            ));
        }
    }
    out
}

fn artifact_quality_summary(metadata: &serde_json::Value) -> Option<String> {
    let status = metadata
        .get("quality_status")
        .and_then(|value| value.as_str())?;
    let mut parts = vec![format!("quality: {status}")];
    if let Some(slide_count) = metadata
        .get("quality_slide_count")
        .and_then(|value| value.as_u64())
    {
        parts.push(format!("slides: {slide_count}"));
    }
    let issues = metadata
        .get("quality_issues")
        .and_then(|value| value.as_array())
        .map(|values| {
            values
                .iter()
                .filter_map(|issue| {
                    let code = issue.get("code").and_then(|value| value.as_str())?;
                    let message = issue
                        .get("message")
                        .and_then(|value| value.as_str())
                        .unwrap_or("");
                    if message.is_empty() {
                        Some(code.to_string())
                    } else {
                        Some(format!("{code}: {message}"))
                    }
                })
                .take(3)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    if !issues.is_empty() {
        parts.push(format!("issues: {}", issues.join("; ")));
    }
    Some(parts.join("; "))
}

fn artifact_provenance_context_for_query(
    facade: &MemoryFacade,
    user: &MemoryUserId,
    workspace: &MemoryWorkspaceId,
    query: &str,
) -> Option<String> {
    let query_lc = query.to_ascii_lowercase();
    let provenance_query = [
        "artifact",
        "artef",
        "deliverable",
        "provenance",
        "provenienza",
        "decision",
        "decisione",
        "deriv",
        "why",
        "perché",
        "perche",
        "dove",
        "where",
        "salvat",
        "saved",
        "lavoro",
        "workflow",
    ]
    .iter()
    .any(|needle| query_lc.contains(needle));
    if !provenance_query {
        return None;
    }

    let memories = facade
        .list_memories_for_ui(user, workspace)
        .unwrap_or_default();
    let memory_by_ref: std::collections::HashMap<String, MemoryRecord> = memories
        .iter()
        .cloned()
        .map(|memory| (memory.reference.to_string(), memory))
        .collect();
    let artifact_memories: Vec<&MemoryRecord> = memories
        .iter()
        .filter(|memory| {
            memory.memory_type == "artifact"
                && matches!(
                    memory.status,
                    MemoryStatus::Confirmed | MemoryStatus::Candidate
                )
        })
        .collect();
    if artifact_memories.is_empty() {
        return None;
    }

    let entities = facade
        .list_entities_for_ui(user, workspace)
        .unwrap_or_default();
    let entity_by_ref: std::collections::HashMap<String, MemoryEntity> = entities
        .iter()
        .cloned()
        .map(|entity| (entity.reference.to_string(), entity))
        .collect();
    let relations = facade
        .list_relations_for_ui(user, workspace)
        .unwrap_or_default();
    let artifact_entity_for_memory = |artifact: &MemoryRecord| -> Option<MemoryRef> {
        relations
            .iter()
            .find(|relation| {
                relation.relation_type == "describes"
                    && relation.source_ref == artifact.reference
                    && entity_by_ref
                        .get(&relation.target_ref.to_string())
                        .is_some_and(|entity| entity.entity_type == "artifact")
            })
            .map(|relation| relation.target_ref.clone())
            .or_else(|| {
                let thread_slug = artifact
                    .metadata
                    .get("thread_slug")
                    .and_then(|value| value.as_str())?;
                let name = artifact
                    .metadata
                    .get("name")
                    .and_then(|value| value.as_str())?;
                Some(MemoryRef::new(
                    MemoryRefKind::Entity,
                    user.clone(),
                    workspace.clone(),
                    format!("artifact:{thread_slug}:{name}"),
                ))
            })
    };

    let mut lines = Vec::new();
    for artifact in artifact_memories {
        let labels = artifact_provenance_labels(
            artifact
                .metadata
                .get("name")
                .and_then(|value| value.as_str())
                .unwrap_or(&artifact.text),
            &artifact.metadata,
        );
        let query_hits_artifact = labels.iter().any(|label| {
            query_lc.contains(label)
                || std::path::Path::new(label)
                    .file_name()
                    .and_then(|value| value.to_str())
                    .is_some_and(|file_name| query_lc.contains(&file_name.to_ascii_lowercase()))
        });
        if !query_hits_artifact
            && ![
                "artifact",
                "artef",
                "deliverable",
                "provenance",
                "provenienza",
                "workflow",
            ]
            .iter()
            .any(|needle| query_lc.contains(needle))
        {
            continue;
        }

        let Some(artifact_ref) = artifact_entity_for_memory(artifact) else {
            continue;
        };
        let artifact_name = artifact
            .metadata
            .get("title")
            .and_then(|value| value.as_str())
            .or_else(|| {
                artifact
                    .metadata
                    .get("name")
                    .and_then(|value| value.as_str())
            })
            .unwrap_or_else(|| artifact.text.lines().next().unwrap_or("artifact"));
        let mut detail = format!("- {artifact_name}");
        if let Some(kind) = artifact
            .metadata
            .get("artifact_type")
            .and_then(|value| value.as_str())
        {
            detail.push_str(&format!(" ({kind})"));
        }
        let mut path_bits = Vec::new();
        if let Some(path) = artifact
            .metadata
            .get("project_relative_path")
            .and_then(|value| value.as_str())
        {
            path_bits.push(format!("project path: {path}"));
        }
        if let Some(path) = artifact
            .metadata
            .get("path_ref")
            .and_then(|value| value.as_str())
            && !path_bits.iter().any(|bit| bit.contains(path))
        {
            path_bits.push(format!("ref: {path}"));
        }
        if let Some(path) = artifact
            .metadata
            .get("managed_path")
            .and_then(|value| value.as_str())
            && !path_bits.iter().any(|bit| bit.contains(path))
        {
            path_bits.push(format!("local managed path: {path}"));
        }
        if !path_bits.is_empty() {
            detail.push_str(&format!(" [{}]", path_bits.join("; ")));
        }
        if let Some(quality) = artifact_quality_summary(&artifact.metadata) {
            detail.push_str(&format!("; {quality}"));
        }

        let mut producers: Vec<String> = artifact
            .metadata
            .get("producer")
            .and_then(|value| value.as_str())
            .map(|value| vec![value.to_string()])
            .unwrap_or_default();
        let mut source_refs = std::collections::BTreeSet::new();
        for relation in &relations {
            if relation.target_ref == artifact_ref
                && relation.relation_type == "produced"
                && let Some(entity) = entity_by_ref.get(&relation.source_ref.to_string())
            {
                producers.push(entity.name.clone());
            }
            if relation.target_ref == artifact_ref && relation.relation_type == "affects" {
                source_refs.insert(relation.source_ref.to_string());
            }
            if relation.source_ref == artifact_ref && relation.relation_type == "derived_from" {
                source_refs.insert(relation.target_ref.to_string());
            }
        }
        producers.sort();
        producers.dedup();
        if !producers.is_empty() {
            detail.push_str(&format!("; produced by {}", producers.join(", ")));
            for producer in &producers {
                if let Some(workflow) = producer_workflow_contract(producer) {
                    detail.push_str(&format!("; derives from workflow {producer} / {workflow}"));
                    break;
                }
            }
        }

        let mut source_lines = Vec::new();
        for source_ref in source_refs {
            if let Some(memory) = memory_by_ref.get(&source_ref) {
                let label = if memory.memory_type == "decision" {
                    "decision"
                } else {
                    memory.memory_type.as_str()
                };
                source_lines.push(format!(
                    "{label}: {}",
                    format_recall_entry(&memory.text, &memory.metadata)
                ));
            } else if let Some(entity) = entity_by_ref.get(&source_ref) {
                source_lines.push(format!("{}: {}", entity.entity_type, entity.name));
            } else {
                source_lines.push(format!("source ref: {source_ref}"));
            }
        }
        if !source_lines.is_empty() {
            detail.push_str(&format!("; derived from {}", source_lines.join(" | ")));
        }
        lines.push(detail);
    }
    if lines.is_empty() {
        return None;
    }
    lines.sort();
    lines.dedup();
    Some(format!(
        "ARTIFACT PROVENANCE FROM CANONICAL MEMORY GRAPH:\n{}",
        lines.into_iter().take(8).collect::<Vec<_>>().join("\n")
    ))
}

fn producer_workflow_contract(producer: &str) -> Option<&'static str> {
    match producer {
        "make_deck" => Some("DeckWorkflow"),
        "make_document" => Some("DocumentWorkflow"),
        _ => None,
    }
}

fn workflow_status_context_for_query(
    facade: &MemoryFacade,
    user: &MemoryUserId,
    workspace: &MemoryWorkspaceId,
    query: &str,
) -> Option<String> {
    let query_lc = query.to_ascii_lowercase();
    let status_query = [
        "workflow",
        "stato",
        "punto",
        "perché",
        "perche",
        "why",
        "next",
        "prossimo",
        "aperto",
        "open loop",
        "blocc",
        "manca",
        "resta",
    ]
    .iter()
    .any(|needle| query_lc.contains(needle));
    if !status_query {
        return None;
    }

    let memories = facade
        .list_memories_for_ui(user, workspace)
        .unwrap_or_default();
    let live = |memory: &&MemoryRecord| {
        matches!(
            memory.status,
            MemoryStatus::Confirmed | MemoryStatus::Candidate
        ) && memory.superseded_by.is_none()
            && !memory.text.trim().is_empty()
    };
    let mut goals: Vec<&MemoryRecord> = memories
        .iter()
        .filter(live)
        .filter(|memory| memory.memory_type == "goal")
        .collect();
    let mut open_loops: Vec<&MemoryRecord> = memories
        .iter()
        .filter(|memory| active_open_loop_record(memory))
        .collect();
    let mut decisions: Vec<&MemoryRecord> = memories
        .iter()
        .filter(live)
        .filter(|memory| memory.memory_type == "decision")
        .collect();
    let mut outcomes: Vec<&MemoryRecord> = memories
        .iter()
        .filter(live)
        .filter(|memory| {
            memory.memory_type == "fact"
                && (memory
                    .metadata
                    .get("certainty")
                    .and_then(|value| value.as_str())
                    .is_some_and(|value| matches!(value, "committed" | "completed" | "verified"))
                    || memory
                        .metadata
                        .get("source")
                        .and_then(|value| value.as_str())
                        == Some("runtime_plan_step"))
        })
        .collect();
    goals.sort_by_key(|memory| std::cmp::Reverse(memory.text.chars().count()));
    open_loops.sort_by_key(|memory| std::cmp::Reverse(memory.text.chars().count()));
    decisions.sort_by_key(|memory| std::cmp::Reverse(memory.text.chars().count()));
    outcomes.sort_by_key(|memory| std::cmp::Reverse(memory.text.chars().count()));

    if goals.is_empty() && open_loops.is_empty() && decisions.is_empty() && outcomes.is_empty() {
        return None;
    }

    let mut sections = Vec::new();
    if !goals.is_empty() {
        let mut lines = vec!["Objectives:".to_string()];
        for goal in goals.into_iter().take(4) {
            lines.push(format!("- {}", goal.text.trim()));
        }
        sections.push(lines.join("\n"));
    }
    if !open_loops.is_empty() {
        let mut lines = vec!["Open loops / next work:".to_string()];
        for open_loop in open_loops.into_iter().take(6) {
            lines.push(format!(
                "- {} (ref: {})",
                open_loop.text.trim(),
                open_loop.reference
            ));
        }
        sections.push(lines.join("\n"));
    }
    if !outcomes.is_empty() {
        let mut lines = vec!["Verified outcomes / current state:".to_string()];
        for outcome in outcomes.into_iter().take(4) {
            lines.push(format!(
                "- {}",
                format_recall_entry(&outcome.text, &outcome.metadata)
            ));
        }
        sections.push(lines.join("\n"));
    }
    if !decisions.is_empty() {
        let mut lines = vec!["Recent decisions / why:".to_string()];
        for decision in decisions.into_iter().take(6) {
            lines.push(format!(
                "- {}",
                format_recall_entry(&decision.text, &decision.metadata)
            ));
        }
        sections.push(lines.join("\n"));
    }
    if let Some(provenance) = artifact_provenance_context_for_query(facade, user, workspace, query)
    {
        sections.push(format!("Evidence artifacts:\n{provenance}"));
    }

    Some(format!(
        "WORKFLOW STATUS FROM CANONICAL MEMORY:\n{}",
        sections.join("\n\n")
    ))
}

/// Decisions in memory that AFFECT a given file (matched by basename via FTS — the
/// touched objects are stored as aliases). Returns a note to append to a file read so
/// the agent recalls WHY a file is the way it is, instead of re-deriving it from the
/// code. `None` when nothing relevant.
fn decisions_for_path(state: &AppState, path: &str) -> Option<String> {
    let base = std::path::Path::new(path)
        .file_name()
        .map(|name| name.to_string_lossy().to_string())
        .filter(|name| !name.is_empty())?;
    let facade = memory_facade(state);
    let access = MemoryAccessRequest {
        actor_id: "recall_file".to_string(),
        user_id: gateway_memory_user_id(),
        workspace_id: gateway_memory_workspace_id(),
        purpose: "recall".to_string(),
        allowed_domains: vec![
            PrivacyDomain::new("personal"),
            PrivacyDomain::new("work"),
            PrivacyDomain::new("general"),
        ],
        max_sensitivity: MemoryDataSensitivity::Private,
        allow_raw_payload: true,
        allow_export: true,
        broad_query: true,
    };
    let page = facade
        .search_memories(MemorySearchRequest {
            access,
            query: base.clone(),
            statuses: vec![MemoryStatus::Confirmed, MemoryStatus::Candidate],
            memory_types: vec!["decision".to_string()],
            limit: 5,
            offset: 0,
        })
        .ok()?;
    if page.items.is_empty() {
        return None;
    }
    let mut lines = vec![format!(
        "📌 Past decisions about «{base}» (from memory — keep them in mind, don't re-derive them):"
    )];
    for item in page.items {
        lines.push(format!(
            "- {}",
            format_recall_entry(&item.summary, &item.metadata)
        ));
    }
    Some(lines.join("\n"))
}

/// Retrieval-augmented context: memory RELEVANT to this turn's prompt (decisions,
/// facts, preferences in the active project + personal scope), injected into the
/// Anti-rewrite anchor (push): code-graph entities whose NAME matches the request's
/// terms, injected so the model SEES "this already exists, extend it" before it
/// re-implements something. This is the strongest no-regression signal we have, and the
/// model can't be trusted to query for what it doesn't know exists — so it's pushed, not
/// pulled. Cheap: one capped SQL LIKE over the active project's code entities.
fn relevant_code_components_for_prompt(state: &AppState, prompt: &str) -> Option<String> {
    // Distinctive terms from the request: length >= 4, deduped, capped. Lowercased.
    let mut seen = std::collections::HashSet::new();
    let terms: Vec<String> = prompt
        .split(|c: char| !c.is_alphanumeric() && c != '_')
        .filter(|t| t.chars().count() >= 4)
        .map(|t| t.to_lowercase())
        .filter(|t| seen.insert(t.clone()))
        .take(12)
        .collect();
    if terms.is_empty() {
        return None;
    }
    let facade = memory_facade(state);
    let user = gateway_memory_user_id();
    let ws = gateway_memory_workspace_id();
    let hits = facade.search_code_entities(&user, &ws, &terms, 15).ok()?;
    if hits.is_empty() {
        return None;
    }
    let kind = |t: &str| match t {
        "code_symbol" => "function/method",
        "code_file" => "file",
        "code_doc" => "document",
        _ => "element",
    };
    let mut block = String::from(
        "ALREADY EXISTING COMPONENTS relevant to the request (from the code map — \
do NOT recreate them, EXTEND/reuse the right ones; use query_code_graph for details):",
    );
    for (name, etype, src) in hits.iter().take(15) {
        let loc = if src.is_empty() {
            String::new()
        } else {
            format!(" — {src}")
        };
        block.push_str(&format!("\n- {name} ({}){loc}", kind(etype)));
    }
    Some(block)
}

/// system prompt so the model answers "why did we…" from memory WITHOUT having to call
/// recall_memory itself — and doesn't claim "I have nothing in memory" when it does.
/// A memory candidate for hybrid ranking: its rank in the lexical (FTS) and/or
/// semantic (dense) passes, plus importance (0..1) and age. Either rank may be absent
/// (matched by only one pass).
#[cfg(test)]
struct MemoryCandidate {
    fts_rank: Option<usize>,
    dense_rank: Option<usize>,
    importance: f32,
    age_days: f32,
}

#[derive(Debug, Clone, Serialize, Default)]
struct MemoryRecallTiming {
    lock_wait_ms: u64,
    profile_ms: u64,
    open_loops_ms: u64,
    fts_ms: u64,
    query_embedding_ms: Option<u64>,
    query_embedding_cache_hit: bool,
    query_embedding_timed_out: bool,
    vector_scan_ms: Option<u64>,
    graph_context_ms: u64,
    total_ms: u64,
    vector_candidates: usize,
    fts_candidates: usize,
    degraded: bool,
}

fn elapsed_ms(start: std::time::Instant) -> u64 {
    start.elapsed().as_millis().min(u128::from(u64::MAX)) as u64
}

#[cfg(test)]
fn memory_recall_timing_trace_line(timing: &MemoryRecallTiming) -> String {
    format!(
        "memory recall: total_ms={} lock_wait_ms={} profile_ms={} open_loops_ms={} \
fts_ms={} query_embedding_ms={} query_embedding_cache_hit={} query_embedding_timed_out={} \
vector_scan_ms={} graph_context_ms={} \
fts_candidates={} vector_candidates={} degraded={}",
        timing.total_ms,
        timing.lock_wait_ms,
        timing.profile_ms,
        timing.open_loops_ms,
        timing.fts_ms,
        timing
            .query_embedding_ms
            .map(|value| value.to_string())
            .unwrap_or_else(|| "none".to_string()),
        timing.query_embedding_cache_hit,
        timing.query_embedding_timed_out,
        timing
            .vector_scan_ms
            .map(|value| value.to_string())
            .unwrap_or_else(|| "none".to_string()),
        timing.graph_context_ms,
        timing.fts_candidates,
        timing.vector_candidates,
        timing.degraded
    )
}

async fn embed_query_for_memory_recall(
    http: &reqwest::Client,
    query: &str,
    workspace: &MemoryWorkspaceId,
    timing: &mut MemoryRecallTiming,
) -> Option<Vec<f32>> {
    let key = memory_query_embedding_cache_key(query, workspace);
    if let Ok(mut cache) = memory_query_embedding_cache().lock()
        && let Some(vector) = cache.get(&key, memory_query_embedding_cache_ttl())
    {
        timing.query_embedding_cache_hit = true;
        timing.query_embedding_ms = Some(0);
        return Some(vector);
    }

    let embedding_start = std::time::Instant::now();
    let mut usage = local_first_inference_usage::UsageContext::new(
        uuid::Uuid::new_v4().to_string(),
        local_first_inference_usage::InferencePurpose::MemoryRecall,
        gateway_user_id().as_str(),
    );
    usage.purpose_detail = Some("query_embedding".to_string());
    usage.workspace_id = Some(workspace.as_str().to_string());
    let result = match tokio::time::timeout(
        memory_query_embedding_timeout(),
        embed_text(http, query, &usage),
    )
    .await
    {
        Ok(vector) => vector,
        Err(_) => {
            timing.query_embedding_timed_out = true;
            timing.query_embedding_ms = Some(elapsed_ms(embedding_start));
            return None;
        }
    };
    timing.query_embedding_ms = Some(elapsed_ms(embedding_start));
    if let Some(vector) = result.as_ref()
        && let Ok(mut cache) = memory_query_embedding_cache().lock()
    {
        cache.insert(
            key,
            vector.clone(),
            memory_query_embedding_cache_max_entries(),
        );
    }
    result
}

/// Combined relevance score: RRF-fuse the two retrieval ranks (a memory strong in BOTH
/// lexical AND semantic is rewarded, unlike a plain concat), then add MILD boosts for
/// importance and recency so relevance still leads but a crucial/fresh memory edges out
/// an equally-relevant trivial/stale one. Weights are tuned so importance/recency act as
/// refinements (~one RRF position), not overrides.
#[cfg(test)]
fn hybrid_memory_score(c: &MemoryCandidate) -> f32 {
    const K: f32 = 60.0;
    let rrf = c.fts_rank.map(|r| 1.0 / (K + r as f32)).unwrap_or(0.0)
        + c.dense_rank.map(|r| 1.0 / (K + r as f32)).unwrap_or(0.0);
    let importance_boost = 0.012 * c.importance.clamp(0.0, 1.0);
    let recency_boost = 0.008 * (-(c.age_days.max(0.0) / 30.0)).exp();
    rrf + importance_boost + recency_boost
}

/// Age of a memory in days from its `created_at` (`unix:<secs>` or `<secs>`).
#[cfg(test)]
fn memory_age_days(created_at: &str, now_secs: i64) -> f32 {
    let s = created_at.strip_prefix("unix:").unwrap_or(created_at);
    let secs: i64 = s
        .split('.')
        .next()
        .and_then(|p| p.parse().ok())
        .unwrap_or(now_secs);
    ((now_secs - secs).max(0) as f32) / 86_400.0
}

/// Esito di `recall_memory`: la risposta testuale per il modello e il payload
/// UI costruito dagli stessi hit autorizzati. ADR 0022 (Piano UI A2/A3).
struct RecallOutcome {
    /// Risposta formattata per il modello (stringa tool result).
    response: String,
    /// Provenienza completa: non ricostruire mai gli hit nel trasporto del tool.
    payload: local_first_subagents::RecallStreamPayload,
}

fn recall_stream_payload_from_outcome(
    outcome: &RecallOutcome,
    query: &str,
) -> local_first_subagents::RecallStreamPayload {
    let mut payload = outcome.payload.clone();
    payload.query = if query.is_empty() {
        "(query)".to_string()
    } else {
        query.to_string()
    };
    payload
}

fn recall_memory(state: &AppState, query: &str, vault_value_requested: bool) -> RecallOutcome {
    let query = query.trim();
    let empty = |msg: &str| -> RecallOutcome {
        RecallOutcome {
            response: msg.to_string(),
            payload: local_first_subagents::RecallStreamPayload {
                query: query.to_string(),
                hits: Vec::new(),
                scope: "personal".to_string(),
                status: "empty".to_string(),
            },
        }
    };
    if query.is_empty() {
        return empty("No query provided.");
    }
    let facade = memory_facade(state);
    if facade.memory_health().is_err() {
        return RecallOutcome {
            response: "Memory is unavailable; the search was not completed.".to_string(),
            payload: local_first_subagents::RecallStreamPayload {
                query: query.to_string(),
                hits: Vec::new(),
                scope: "personal".to_string(),
                status: "unavailable".to_string(),
            },
        };
    }
    let user = gateway_memory_user_id();
    let active = gateway_memory_workspace_id();
    let search = |workspace: MemoryWorkspaceId| -> Vec<local_first_subagents::RecallStreamHit> {
        let access = MemoryAccessRequest {
            actor_id: "recall".to_string(),
            user_id: user.clone(),
            workspace_id: workspace.clone(),
            purpose: "recall".to_string(),
            allowed_domains: vec![
                PrivacyDomain::new("personal"),
                PrivacyDomain::new("work"),
                PrivacyDomain::new("general"),
            ],
            max_sensitivity: MemoryDataSensitivity::Secret,
            allow_raw_payload: true,
            allow_export: true,
            broad_query: true,
        };
        facade
            .search_memories(MemorySearchRequest {
                access,
                query: query.to_string(),
                statuses: vec![MemoryStatus::Confirmed, MemoryStatus::Candidate],
                memory_types: Vec::new(),
                limit: 8,
                offset: 0,
            })
            .map(|page| {
                page.items
                    .into_iter()
                    .map(|item| {
                        let collection = [
                            MemoryCollectionKey::Preferences,
                            MemoryCollectionKey::Profile,
                            MemoryCollectionKey::Knowledge,
                            MemoryCollectionKey::Decisions,
                            MemoryCollectionKey::Goals,
                            MemoryCollectionKey::Artifacts,
                            MemoryCollectionKey::Episodes,
                        ]
                        .into_iter()
                        .find(|collection| {
                            collection.matches_candidate(&item.memory_type, &item.metadata)
                        })
                        .unwrap_or(MemoryCollectionKey::Knowledge);
                        local_first_subagents::RecallStreamHit {
                            r#ref: item.reference.to_string(),
                            text: format_recall_entry(&item.summary, &item.metadata),
                            score: 1.0 / item.rank.max(1) as f32,
                            kind: item.memory_type,
                            source_workspace_id: workspace.as_str().to_string(),
                            source_label: recall_source_label(workspace.as_str()),
                            collection: recall_collection_token(collection).to_string(),
                            grant_id: None,
                            policy_version: None,
                            source_revision: None,
                            conflict: false,
                            graph_path: Vec::new(),
                        }
                    })
                    .collect()
            })
            .unwrap_or_default()
    };
    let in_project = active.as_str() != PERSONAL_WORKSPACE;
    let mut lines = Vec::new();
    // Keep the full structured hit alongside the text given to the model.
    let mut ui_hits: Vec<local_first_subagents::RecallStreamHit> = Vec::new();
    if memory_sources_enabled() && in_project {
        let pack = recall_pack_on_facade(facade, &user, &active, query, &[], None);
        let payload = recall_stream_payload_from_pack(&pack);
        for hit in pack.hits {
            lines.push(format!("- [{}] {}", hit.kind, hit.text));
        }
        ui_hits.extend(payload.hits);
    } else {
        for hit in search(active.clone()) {
            lines.push(format!("- [{}] {}", hit.kind, hit.text));
            ui_hits.push(hit);
        }
    }
    if let Some(workflow) = workflow_status_context_for_query(facade, &user, &active, query) {
        lines.push(workflow);
    } else if let Some(provenance) =
        artifact_provenance_context_for_query(facade, &user, &active, query)
    {
        lines.push(provenance);
    }
    let personal = MemoryWorkspaceId::new(PERSONAL_WORKSPACE);
    if !in_project
        && let Ok(relations) = facade.list_relations_for_ui(&user, &personal)
        && !relations.is_empty()
    {
        let names: std::collections::HashMap<String, String> = facade
            .list_entities_for_ui(&user, &personal)
            .unwrap_or_default()
            .into_iter()
            .map(|entity| (entity.reference.to_string(), entity.name))
            .collect();
        for relation in relations.iter().take(12) {
            if let (Some(source), Some(target)) = (
                names.get(&relation.source_ref.to_string()),
                names.get(&relation.target_ref.to_string()),
            ) {
                lines.push(format!("- {source} —{}→ {target}", relation.relation_type));
            }
        }
    }
    let scope = if in_project { "project" } else { "personal" }.to_string();
    let has_hits = !lines.is_empty();
    let response = match lock_vault_store(state) {
        Ok(vault_store) => recall_memory_response_with_vault_fallback(
            &vault_store,
            query,
            lines,
            in_project,
            vault_value_requested,
        ),
        Err(_) if lines.is_empty() => format!("No memories relevant to «{query}»."),
        Err(_) if in_project => format!("Memories relevant to THIS project:\n{}", lines.join("\n")),
        Err(_) => format!("Relevant memories from memory:\n{}", lines.join("\n")),
    };
    RecallOutcome {
        response,
        payload: local_first_subagents::RecallStreamPayload {
            query: query.to_string(),
            hits: ui_hits,
            scope,
            status: if has_hits {
                "ready".to_string()
            } else {
                "empty".to_string()
            },
        },
    }
}

fn recall_memory_response_with_vault_fallback(
    vault_store: &SQLiteVaultStore,
    query: &str,
    lines: Vec<String>,
    in_project: bool,
    vault_value_requested: bool,
) -> String {
    let memory_block = if lines.is_empty() {
        format!("No memories relevant to «{query}».")
    } else if in_project {
        format!("Memories relevant to THIS project:\n{}", lines.join("\n"))
    } else {
        format!("Relevant memories from memory:\n{}", lines.join("\n"))
    };
    let should_check_vault = lines.is_empty()
        || vault_value_requested
        || (query_has_sensitive_vault_term(query) && memory_lines_mention_vault(&lines));
    if !should_check_vault {
        return memory_block;
    }
    let vault_matches = match search_vault_records(vault_store, query, 5) {
        Ok(records) => records,
        Err(_) => return memory_block,
    };
    if vault_matches.is_empty() {
        return memory_block;
    }
    let vault_lines = vault_matches
        .into_iter()
        .map(|record| {
            let metadata = format!(
                "- [{}] {} — {} ({})",
                record.category, record.label, record.redacted_preview, record.id
            );
            if vault_value_requested {
                format!(
                    "{metadata}\n  reveal_card: {}",
                    vault_reveal_marker(&record)
                )
            } else {
                metadata
            }
        })
        .collect::<Vec<_>>()
        .join("\n");
    format!(
        "{memory_block}\n\nVault records matching the request (redacted metadata only; do NOT reveal or guess the secret value). If the user asked to see the value, you MUST copy the reveal_card marker exactly on its own line in your final answer so the UI can ask for the local PIN and reveal it locally:\n{vault_lines}"
    )
}

fn query_has_sensitive_vault_term(query: &str) -> bool {
    vault_metadata_terms(query)
        .iter()
        .any(|term| vault_term_is_sensitive(term))
}

fn vault_term_is_sensitive(term: &str) -> bool {
    matches!(
        term,
        "codice"
            | "fiscale"
            | "fiscal"
            | "identity"
            | "targa"
            | "plate"
            | "license"
            | "vehicles"
            | "passaporto"
            | "passport"
            | "documento"
            | "carta"
            | "card"
            | "password"
            | "token"
            | "salute"
            | "health"
    )
}

fn memory_lines_mention_vault(lines: &[String]) -> bool {
    lines
        .iter()
        .any(|line| line.to_ascii_lowercase().contains("vault"))
}

fn vault_reveal_marker(record: &VaultRecordSummary) -> String {
    let payload = serde_json::json!({
        "record_id": record.id,
        "category": record.category,
        "label": record.label,
        "redacted_preview": record.redacted_preview,
    });
    format!("{VAULT_REVEAL_OPEN}{payload}{VAULT_REVEAL_CLOSE}")
}

// `extract_vault_reveal_marker`, `append_vault_reveal_marker_if_missing`, and the
// `VAULT_REVEAL_OPEN/CLOSE` consts moved to `engine::markers` (ADR 0024 inc 5e.3); imported below.

#[derive(Debug, Deserialize)]
struct ImprovePromptRequest {
    prompt: String,
}

#[derive(Debug, Serialize)]
struct ImprovePromptResponse {
    improved: String,
}

/// Rewrites a draft prompt into a clearer, more complete instruction (the ✨
/// "improve prompt" composer action). A single non-streaming LLM call: returns
/// ONLY the rewritten prompt, same language, no preamble. The provider config is
/// the same one chat uses.
async fn improve_prompt(
    State(state): State<AppState>,
    Json(request): Json<ImprovePromptRequest>,
) -> Result<Json<ImprovePromptResponse>, GatewayError> {
    let draft = request.prompt.trim();
    if draft.is_empty() {
        return Ok(Json(ImprovePromptResponse {
            improved: String::new(),
        }));
    }
    let (base_url, model, api_key) = chat_openai_stream_config().ok_or_else(|| GatewayError {
        status: StatusCode::SERVICE_UNAVAILABLE,
        code: "no_inference_provider",
        message: "No provider configured.".to_string(),
    })?;
    let system = "You are an assistant that REWRITES prompts to make them clearer, more specific \
and complete, WITHOUT executing them and without answering the request. Keep the SAME language \
and the user's intent; make criteria, constraints and expected format explicit only if implicit. \
Return ONLY the rewritten prompt, as plain text, without preamble, quotes or explanations.";
    // Generous ceiling for REASONING models: they spend tokens on a hidden
    // `reasoning` field before emitting `content`, so a tight cap (fine for an
    // instruct model) can be burned mid-thought, leaving `content` empty and
    // silently degrading to the unchanged draft. A high ceiling costs nothing for
    // instruct models (they stop at the rewrite, finish_reason=stop). 4000 also
    // covers a genuinely long rewrite. See the note on `generate_thread_title`.
    let payload = serde_json::json!({
        "model": model,
        "temperature": 0.3,
        "max_tokens": 4000,
        "messages": [
            { "role": "system", "content": system },
            { "role": "user", "content": format!("Rewrite this prompt:\n\n{draft}") },
        ],
    });
    let mut usage = local_first_inference_usage::UsageContext::new(
        uuid::Uuid::new_v4().to_string(),
        local_first_inference_usage::InferencePurpose::Other,
        gateway_user_id().as_str(),
    );
    usage.purpose_detail = Some("prompt_improvement".to_string());
    let response = inference_transport::send_openai_json(
        &state.http,
        state.usage_recorder.clone(),
        &usage,
        &inference_provider_id(&base_url),
        &model,
        inference_locality(&base_url),
        &base_url,
        api_key.as_deref(),
        &payload,
        Some(std::time::Duration::from_secs(30)),
        system.chars().count().saturating_add(draft.chars().count()),
    )
    .await
    .map_err(|error| {
        tracing::warn!(
            target: "chat::improve_prompt",
            %error, model = %model, %base_url,
            "improve-prompt LLM request errored"
        );
        GatewayError {
            status: StatusCode::BAD_GATEWAY,
            code: "improve_prompt_failed",
            message: format!("Provider unreachable: {error}"),
        }
    })?;
    if !(200..300).contains(&response.status) {
        let status = response.status;
        let body: String = response.body.to_string().chars().take(300).collect();
        tracing::warn!(
            target: "chat::improve_prompt",
            %status, model = %model, %base_url, body = %body,
            "improve-prompt LLM call failed"
        );
        return Err(GatewayError {
            status: StatusCode::BAD_GATEWAY,
            code: "improve_prompt_failed",
            message: format!("Provider responded {status}"),
        });
    }
    let body = response.body;
    let improved = body
        .get("choices")
        .and_then(|c| c.get(0))
        .and_then(|c| c.get("message"))
        .and_then(|m| m.get("content"))
        .and_then(|c| c.as_str())
        .unwrap_or("")
        .trim()
        .trim_matches('"')
        .to_string();
    let improved = if improved.is_empty() {
        // 2xx but no usable content — the reasoning-budget trap. Log it instead of
        // silently returning the unchanged draft as if the rewrite were a no-op.
        let snippet: String = body.to_string().chars().take(300).collect();
        tracing::warn!(
            target: "chat::improve_prompt",
            model = %model, %base_url, body = %snippet,
            "improve-prompt LLM returned 2xx but no content — keeping the original draft"
        );
        draft.to_string()
    } else {
        improved
    };
    Ok(Json(ImprovePromptResponse { improved }))
}

#[derive(Debug, Deserialize)]
struct SuggestionsRequest {
    prompt: String,
    answer: String,
}

#[derive(Debug, Serialize)]
struct SuggestionsResponse {
    suggestions: Vec<String>,
}

fn chat_suggestions_payload(
    base_url: &str,
    model: &str,
    system: &str,
    user: &str,
) -> serde_json::Value {
    let mut payload = serde_json::json!({
        "model": model,
        "temperature": 0.5,
        "max_tokens": 2000,
        "messages": [
            { "role": "system", "content": system },
            { "role": "user", "content": user },
        ],
    });
    if is_ollama_base(base_url) {
        payload["reasoning_effort"] = serde_json::Value::String("none".to_string());
    }
    payload
}

/// Proposes a few short follow-up prompts the user might ask next, given the last
/// exchange (the ✦ dynamic suggestions under the latest answer). One cheap
/// non-streaming LLM call; best-effort (empty list on any failure).
async fn chat_suggestions(
    State(state): State<AppState>,
    Json(request): Json<SuggestionsRequest>,
) -> Json<SuggestionsResponse> {
    let empty = Json(SuggestionsResponse {
        suggestions: Vec::new(),
    });
    let Some((base_url, model, api_key)) = chat_openai_stream_config() else {
        return empty;
    };
    if request.answer.trim().is_empty() {
        return empty;
    }
    let system = "Propose 3 SHORT follow-up questions the user might ask AFTER this answer. Rules: \
one per line, max ~7 words, in the SAME language as the user, phrased as if written by the user, \
without numbering, dashes or quotes. Return ONLY the 3 lines.";
    let user = format!(
        "User request:\n{}\n\nAssistant answer:\n{}",
        request.prompt.chars().take(2000).collect::<String>(),
        request.answer.chars().take(4000).collect::<String>()
    );
    // Ollama reasoning models can spend the entire output budget before emitting
    // these three utility lines. Disable reasoning through its supported
    // OpenAI-compatible field; leave other compatible providers unchanged.
    let payload = chat_suggestions_payload(&base_url, &model, system, &user);
    let mut usage = local_first_inference_usage::UsageContext::new(
        uuid::Uuid::new_v4().to_string(),
        local_first_inference_usage::InferencePurpose::Other,
        gateway_user_id().as_str(),
    );
    usage.purpose_detail = Some("follow_up_suggestions".to_string());
    let response = match inference_transport::send_openai_json(
        &state.http,
        state.usage_recorder.clone(),
        &usage,
        &inference_provider_id(&base_url),
        &model,
        inference_locality(&base_url),
        &base_url,
        api_key.as_deref(),
        &payload,
        Some(std::time::Duration::from_secs(25)),
        system.chars().count().saturating_add(user.chars().count()),
    )
    .await
    {
        Ok(response) => response,
        Err(error) => {
            tracing::warn!(
                target: "chat::suggestions",
                %error, model = %model, %base_url,
                "suggestions LLM request errored — showing no suggestions"
            );
            return empty;
        }
    };
    if !(200..300).contains(&response.status) {
        let status = response.status;
        let body: String = response.body.to_string().chars().take(300).collect();
        tracing::warn!(
            target: "chat::suggestions",
            %status, model = %model, %base_url, body = %body,
            "suggestions LLM call failed — showing no suggestions"
        );
        return empty;
    }
    let body = response.body;
    let content = body
        .get("choices")
        .and_then(|c| c.get(0))
        .and_then(|c| c.get("message"))
        .and_then(|m| m.get("content"))
        .and_then(|c| c.as_str())
        .unwrap_or("");
    if content.trim().is_empty() {
        // 2xx but no usable content (e.g. reasoning-budget starvation) — surface it
        // rather than silently rendering an empty suggestions strip.
        let snippet: String = body.to_string().chars().take(300).collect();
        tracing::warn!(
            target: "chat::suggestions",
            model = %model, %base_url, body = %snippet,
            "suggestions LLM returned 2xx but no content — showing no suggestions"
        );
    }
    let suggestions = content
        .lines()
        .map(|line| {
            line.trim()
                .trim_start_matches(|c: char| {
                    c == '-' || c == '*' || c == '•' || c.is_ascii_digit() || c == '.' || c == ')'
                })
                .trim()
                .trim_matches('"')
                .trim()
                .to_string()
        })
        .filter(|line| !line.is_empty())
        .take(3)
        .collect();
    Json(SuggestionsResponse { suggestions })
}

#[derive(Debug, Deserialize)]
struct AutoTitleRequest {
    prompt: String,
    #[serde(default)]
    answer: String,
}

/// Generates a concise thread title from the first exchange (LLM), with a plain
/// fallback. Returns a short single line.
/// Build the (prompt, answer) pair fed to the title model, with the app-only
/// display markers stripped. WHY: the assistant text carries ‹‹PLAN››/‹‹ACT››/‹‹REASONING››
/// blocks that the UI renders but the model must never read as content (caposaldo #5,
/// same stripping as the context renderer / channel mirror). Without it, an agentic turn
/// whose ‹‹PLAN›› card dominated the final message made the title model latch onto a
/// mid-turn plan step ("Step 2 in corso – LangGraph (pro e contro)") instead of the topic.
fn title_model_inputs(prompt: &str, answer: &str) -> (String, String) {
    (
        strip_display_markers(prompt).trim().to_string(),
        strip_display_markers(answer).trim().to_string(),
    )
}

async fn generate_thread_title(state: &AppState, prompt: &str, answer: &str) -> String {
    let (prompt, answer) = title_model_inputs(prompt, answer);
    let (prompt, answer) = (prompt.as_str(), answer.as_str());
    let fallback = || {
        let base = prompt.trim();
        if base.is_empty() {
            "Nuova chat".to_string()
        } else {
            base.chars().take(48).collect::<String>()
        }
    };
    let Some((base_url, model, api_key)) = chat_openai_stream_config() else {
        tracing::warn!(
            target: "chat::autotitle",
            "no chat model configured (orchestrator role unresolved) — falling back to prompt truncation"
        );
        return fallback();
    };
    let system = "Generate a very short TITLE (max 5 words) for this conversation, in the same \
language as the user. Only the title, without quotes, final punctuation or prefixes.";
    let user = format!(
        "First message:\n{}\n\nAnswer:\n{}",
        prompt.chars().take(1500).collect::<String>(),
        answer.chars().take(1500).collect::<String>()
    );
    // max_tokens must budget for REASONING models: they spend tokens on a hidden
    // `reasoning` field before emitting `content`. A tiny 24-token cap (fine for an
    // instruct model) let a reasoning model like deepseek-v4-pro burn the whole
    // budget mid-thought and return an EMPTY title, silently degrading to raw
    // prompt truncation. A generous ceiling costs nothing for instruct models
    // (they stop at the short title, finish_reason=stop) while giving reasoning
    // models room to think and then produce the title.
    let payload = serde_json::json!({
        "model": model,
        "temperature": 0.3,
        "max_tokens": 2000,
        "messages": [
            { "role": "system", "content": system },
            { "role": "user", "content": user },
        ],
    });
    let mut usage = local_first_inference_usage::UsageContext::new(
        uuid::Uuid::new_v4().to_string(),
        local_first_inference_usage::InferencePurpose::TitleGeneration,
        gateway_user_id().as_str(),
    );
    usage.purpose_detail = Some("thread_title".to_string());
    // Errors here were previously swallowed into an empty string, silently degrading
    // to the raw-truncation fallback (a title cut mid-word). Log the actual reason —
    // status + body on an HTTP error, the transport error otherwise — so a broken
    // title model (e.g. an unsigned `:cloud` Ollama model returning 401) is visible.
    let title = match inference_transport::send_openai_json(
        &state.http,
        state.usage_recorder.clone(),
        &usage,
        &inference_provider_id(&base_url),
        &model,
        inference_locality(&base_url),
        &base_url,
        api_key.as_deref(),
        &payload,
        Some(std::time::Duration::from_secs(30)),
        system.chars().count().saturating_add(user.chars().count()),
    )
    .await
    {
        Ok(response) if (200..300).contains(&response.status) => {
            let body = response.body;
            let extracted = Some(&body)
                .and_then(|b| {
                    b.get("choices")
                        .and_then(|c| c.get(0))
                        .and_then(|c| c.get("message"))
                        .and_then(|m| m.get("content"))
                        .and_then(|c| c.as_str())
                        .map(|s| {
                            s.trim()
                                .trim_matches('"')
                                .lines()
                                .next()
                                .unwrap_or("")
                                .trim()
                                .to_string()
                        })
                })
                .unwrap_or_default();
            if extracted.trim().is_empty() {
                let snippet: String = body.to_string().chars().take(300).collect();
                tracing::warn!(
                    target: "chat::autotitle",
                    model = %model, %base_url, body = %snippet,
                    "title LLM returned 2xx but no usable content — falling back to prompt truncation"
                );
            }
            extracted
        }
        Ok(response) => {
            let status = response.status;
            let body: String = response.body.to_string().chars().take(300).collect();
            tracing::warn!(
                target: "chat::autotitle",
                %status, model = %model, %base_url, body = %body,
                "title LLM call failed — falling back to prompt truncation"
            );
            String::new()
        }
        Err(err) => {
            tracing::warn!(
                target: "chat::autotitle",
                error = %err, model = %model, %base_url,
                "title LLM request errored — falling back to prompt truncation"
            );
            String::new()
        }
    };
    if title.is_empty() {
        fallback()
    } else {
        title.chars().take(60).collect()
    }
}

/// Auto-titles a thread from its first exchange (LLM), persisting the result.
async fn autotitle_chat_thread(
    State(state): State<AppState>,
    Path(thread_id): Path<String>,
    Json(request): Json<AutoTitleRequest>,
) -> Result<Json<ChatThreadSnapshot>, GatewayError> {
    {
        let store = lock_store(&state)?;
        if let Some(thread) = store.thread(&thread_id).map_err(GatewayError::store)? {
            // Two-phase titling: the turn broker now sets a PROVISIONAL title
            // (`compact_thread_title(prompt)`) at turn start so the sidebar updates
            // immediately. Here we upgrade that provisional to a polished LLM title.
            // So we refine when the stored title is either the "New task" placeholder
            // OR still exactly the auto-derived provisional (the user hasn't renamed
            // it). If it differs from both, the user set it deliberately — leave it.
            let is_provisional = thread.title == compact_thread_title(&request.prompt);
            if !is_placeholder_chat_title(&thread.title) && !is_provisional {
                return Ok(Json(
                    store
                        .select_thread(&thread_id)
                        .map_err(GatewayError::store)?,
                ));
            }
        }
    }
    let title = generate_thread_title(&state, &request.prompt, &request.answer).await;
    Ok(Json(
        lock_store(&state)?
            .rename_thread(&thread_id, &title)
            .map_err(GatewayError::store)?,
    ))
}

fn is_placeholder_chat_title(title: &str) -> bool {
    matches!(
        title.trim().to_ascii_lowercase().as_str(),
        "new task" | "nuovo compito"
    )
}

#[derive(Debug, Deserialize)]
struct SeedAssistantRequest {
    text: String,
    #[serde(default)]
    event_parts: Vec<serde_json::Value>,
}

/// Append a literal assistant message to a thread. Used to open a proactivity-card
/// chat with Homun's question already posted (so the conversation starts with the
/// assistant asking, instead of seeding the composer with the user's draft).
async fn seed_assistant_message(
    State(state): State<AppState>,
    Path(thread_id): Path<String>,
    Json(request): Json<SeedAssistantRequest>,
) -> Result<Json<ChatMessagesSnapshot>, GatewayError> {
    let text = request.text.trim();
    if text.is_empty() {
        return Err(GatewayError {
            status: StatusCode::BAD_REQUEST,
            code: "empty_message",
            message: "Empty message.".to_string(),
        });
    }
    let mut message = channel_chat_message("assistant", text);
    message.event_parts = request.event_parts;
    let snapshot = lock_store(&state)?
        .append_assistant_message(&thread_id, &message)
        .map_err(GatewayError::store)?;
    publish_app_event(serde_json::json!({
        "type": "thread.updated",
        "thread_id": thread_id,
    }));
    Ok(Json(snapshot))
}

#[derive(Debug, Deserialize)]
struct ProactiveAnswerRequest {
    /// The option the user picked (e.g. "Sviluppatore").
    answer: String,
    /// The question that was asked (the card's message text), kept for the captured fact.
    #[serde(default)]
    question: String,
    /// A short, ALREADY-LOCALIZED acknowledgment to post back. The frontend supplies it so
    /// the reply respects the UI language WITHOUT the gateway ever calling the model.
    #[serde(default)]
    ack: String,
}

/// Answer to a proactivity question (e.g. day-1 onboarding "what's your role?") WITHOUT
/// running the agent loop. A supervisor question is info-gathering, not a task request:
/// the old path submitted the pick as a normal chat turn, and a weak model treated a
/// one-word answer ("Sviluppatore") as licence to plan and execute unrelated work. Here we
/// only: (1) echo the pick as a user message, (2) capture it as a durable Personal-scope
/// memory so future reviews are grounded on it, (3) post a canned acknowledgment. No tools.
async fn proactive_answer(
    State(state): State<AppState>,
    Path(thread_id): Path<String>,
    Json(request): Json<ProactiveAnswerRequest>,
) -> Result<Json<ChatMessagesSnapshot>, GatewayError> {
    let answer = request.answer.trim();
    if answer.is_empty() {
        return Err(GatewayError {
            status: StatusCode::BAD_REQUEST,
            code: "empty_answer",
            message: "Empty answer.".to_string(),
        });
    }
    // 1) Echo the pick as a user message (thread reads: question → answer → ack).
    //    append_assistant_message inserts the message with ITS role, so it serves a
    //    "user" message too.
    {
        let user_message = channel_chat_message("user", answer);
        lock_store(&state)?
            .append_assistant_message(&thread_id, &user_message)
            .map_err(GatewayError::store)?;
    }
    // 2) Durable capture — out of the store lock (the MemoryFacade is a separate service).
    capture_proactive_answer_memory(&state, &thread_id, request.question.trim(), answer);
    // 3) Canned acknowledgment — NO agent loop, NO tools.
    let ack = {
        let trimmed = request.ack.trim();
        if trimmed.is_empty() {
            "Perfect — noted. Thanks!".to_string()
        } else {
            trimmed.to_string()
        }
    };
    let ack_message = channel_chat_message("assistant", &ack);
    let snapshot = lock_store(&state)?
        .append_assistant_message(&thread_id, &ack_message)
        .map_err(GatewayError::store)?;
    publish_app_event(serde_json::json!({
        "type": "thread.updated",
        "thread_id": thread_id,
    }));
    Ok(Json(snapshot))
}

/// Build the memory-write request for a captured proactivity answer. Pure (no I/O) so it
/// is unit-testable. memory_type is `preference` on purpose: `gather_scope_memory` only
/// recalls fact|preference|decision|goal, so this guarantees the answer feeds future reviews.
fn proactive_answer_memory_request(
    question: &str,
    answer: &str,
    thread_id: &str,
    lifecycle: MemoryLifecycleRequest,
) -> MemoryCreateRequest {
    let text = if question.is_empty() {
        format!("Onboarding answer: {answer}")
    } else {
        format!("{question}\n\u{2192} {answer}")
    };
    MemoryCreateRequest {
        request: lifecycle,
        memory_type: "preference".to_string(),
        text: redact_sensitive_text(&text),
        aliases: Vec::new(),
        language_hints: Vec::new(),
        confidence: 1.0,
        privacy_domain: PrivacyDomain::new("personal"),
        sensitivity: MemoryDataSensitivity::Internal,
        evidence_refs: Vec::new(),
        metadata: serde_json::json!({
            "source": "proactive_answer",
            "thread_id": thread_id,
        }),
    }
}

/// Persist a proactivity answer as a Personal-scope preference. Out-of-path: a failure is
/// swallowed (the echo + acknowledgment already landed; a lost fact just means the next
/// review is a little less grounded, never a broken chat).
fn capture_proactive_answer_memory(
    state: &AppState,
    thread_id: &str,
    question: &str,
    answer: &str,
) {
    let lifecycle = MemoryLifecycleRequest {
        actor_id: "proactivity".to_string(),
        user_id: gateway_memory_user_id(),
        workspace_id: MemoryWorkspaceId::new(PERSONAL_WORKSPACE),
        purpose: "proactive_answer_capture".to_string(),
    };
    let request = proactive_answer_memory_request(question, answer, thread_id, lifecycle.clone());
    let facade = memory_facade(state);
    if let Ok(record) = facade.create_memory_candidate(request) {
        let _ = facade.confirm_memory(&lifecycle, &record.reference, "proactive answer capture");
    }
}

// MAX_PLAN_NUDGES moved into `engine::agent_loop` (5.D2 — the loop that used it lives there now).
// Round budget once a browser tool is in play. Driving a browser one micro-action
// at a time (navigate -> snapshot -> act -> re-snapshot) needs many more
// model/tool round-trips than a normal chat turn. Env-overridable via
// `HOMUN_CHAT_BROWSER_MAX_ROUNDS`.

/// `"Riepilogo Spese Q1"` → `"riepilogo-spese-q1"`. Lowercase, alnum runs joined
/// by single hyphens, trimmed, capped — a stable directory id for a new skill.
fn slugify_skill_name(name: &str) -> String {
    let mut out = String::new();
    let mut last_hyphen = true; // suppress leading hyphen
    for ch in name.to_lowercase().chars() {
        if ch.is_ascii_alphanumeric() {
            out.push(ch);
            last_hyphen = false;
        } else if !last_hyphen {
            out.push('-');
            last_hyphen = true;
        }
    }
    out.trim_matches('-').chars().take(48).collect()
}

/// Creates a user-authored skill from a prompt: writes `skills_root/<slug>/SKILL.md`
/// (frontmatter + instructions), marks its origin "authored", and the scanner makes
/// it available (enabled). Called by the `create_skill` tool when the user asks to
/// create one. A skill is just instructions the agent follows; for skills that run
/// commands, the instructions reference `run_in_sandbox`.
fn create_skill(name: &str, description: &str, instructions: &str) -> String {
    let name = name.trim();
    let description = description.trim();
    let instructions = instructions.trim();
    if name.is_empty() || description.is_empty() || instructions.is_empty() {
        return "Creating a skill requires: name, description (WHEN to use it) and instructions (what to do).".to_string();
    }
    let Ok(data_dir) = gateway_data_dir() else {
        return "Data folder unavailable.".to_string();
    };
    let dir = skills::skills_root(&data_dir);
    let slug = slugify_skill_name(name);
    if slug.is_empty() {
        return "The name doesn't produce a valid id: use letters or numbers.".to_string();
    }
    let skill_dir = dir.join(&slug);
    if skill_dir.exists() {
        return format!("A skill with id '{slug}' already exists. Choose another name.");
    }
    if let Err(error) = fs::create_dir_all(&skill_dir) {
        return format!("Could not create the skill folder: {error}");
    }
    let desc_yaml =
        serde_json::to_string(description).unwrap_or_else(|_| format!("\"{description}\""));
    let content = format!(
        "---\nname: {name}\nslug: {slug}\nversion: 1.0.0\ndescription: {desc_yaml}\n---\n\n{instructions}\n"
    );
    if let Err(error) = fs::write(skill_dir.join("SKILL.md"), &content) {
        let _ = fs::remove_dir_all(&skill_dir);
        return format!("Could not write the skill: {error}");
    }
    let mut origins = load_skills_origins();
    origins.insert(slug.clone(), "authored".to_string());
    let _ = save_skills_origins(&origins);
    format!(
        "✅ Skill «{name}» created (id={slug}) and active. Try it: tell me \"use the skill {name}\" \
or ask me something that triggers it."
    )
}

/// Enabled installed skills as (id, name, description) for prompt discovery (L1).
fn enabled_skills_summary() -> Vec<(String, String, String)> {
    let Ok(dir) = skills_dir() else {
        return Vec::new();
    };
    let disabled = load_skills_disabled();
    let origins = load_skills_origins();
    skills::scan_skills(&dir, &disabled, &origins)
        .into_iter()
        .filter(|s| s.enabled)
        .map(|s| (s.id, s.name, s.description))
        .collect()
}

/// The HomunCoder methodology skill ids (from the sync manifest). Used to
/// scope the methodology to PROJECT chats (HomunCoder mode) instead of flooding every
/// chat, and to group them in Settings.
fn homuncoder_skill_ids() -> std::collections::HashSet<String> {
    skills_dir()
        .ok()
        .map(|dir| dir.join("homuncoder-skills.txt"))
        .and_then(|path| std::fs::read_to_string(path).ok())
        .map(|content| {
            content
                .lines()
                .map(str::trim)
                .filter(|l| !l.is_empty())
                .map(str::to_string)
                .collect()
        })
        .unwrap_or_default()
}

/// Loads an installed skill's SKILL.md body (instructions) by id.
#[allow(dead_code)]
fn load_skill_body(id: &str) -> Option<String> {
    load_skill_body_and_sensitive(id).map(|(body, _)| body)
}

/// Loads a skill's adapted body PLUS its declared sensitive categories in one pass
/// (ADR 0023 Step 5 / Fase 0.3). `use_skill` uses the body to show instructions and
/// the categories to arm the turn's force-confirm (`ctx.active_sensitive`).
fn load_skill_body_and_sensitive(id: &str) -> Option<(String, Vec<skills::SensitiveCategory>)> {
    let dir = skills_dir().ok()?;
    let disabled = load_skills_disabled();
    let origins = load_skills_origins();
    skills::load_detail(&dir, id, &disabled, &origins)
        .ok()
        .flatten()
        .map(|detail| (adapt_skill_body(&detail.body, id), detail.summary.sensitive))
}

/// Extracts a skill id from a sandbox command that references the container skill
/// path `/home/agent/skills/<id>/…`, so we can sync that skill's files even when
/// the model omitted the `skill_id` argument.
fn skill_id_from_command(command: &str) -> Option<String> {
    let marker = "/home/agent/skills/";
    let start = command.find(marker)? + marker.len();
    let rest = &command[start..];
    let id: String = rest
        .chars()
        .take_while(|c| *c != '/' && *c != ' ' && *c != '"' && *c != '\'')
        .collect();
    if id.is_empty() { None } else { Some(id) }
}

/// Adapts a skill's SKILL.md for execution in the contained computer: substitutes
/// the `{baseDir}` template variable (and common aliases) with the skill's real
/// path inside the container, so commands like `python3 {baseDir}/scripts/x.py`
/// resolve. This is the runtime "skill adaptation" step.
fn adapt_skill_body(body: &str, id: &str) -> String {
    let base = sandbox::container_skill_dir(id);
    body.replace("{baseDir}", &base)
        .replace("${baseDir}", &base)
        .replace("{base_dir}", &base)
        .replace("{BASE_DIR}", &base)
        .replace("$BASEDIR", &base)
}

/// The skill-activation tool: loads a skill's full SKILL.md instructions on demand
/// (progressive disclosure L2).
fn use_skill_tool_schema() -> serde_json::Value {
    serde_json::json!({
        "type": "function",
        "function": {
            "name": "use_skill",
            "description": "Load the full instructions (SKILL.md) of an installed skill, given its id. Call it when the request matches a skill listed in INSTALLED SKILLS, then follow the received instructions.",
            "parameters": {
                "type": "object",
                "properties": {
                    "id": { "type": "string", "description": "id of the skill, e.g. 'weather'" }
                },
                "required": ["id"]
            }
        }
    })
}

/// The skill-execution tool: runs a shell command from a skill's instructions
/// inside the contained-computer sandbox.
fn run_in_sandbox_tool_schema() -> serde_json::Value {
    serde_json::json!({
        "type": "function",
        "function": {
            "name": "run_in_sandbox",
            "description": "Run a shell command in the contained computer (isolated sandbox: bash, curl, python, git, compilers). Use it to: run commands/scripts, process data (incl. fetching STRUCTURED data — RSS/JSON APIs — with curl), and ABOVE ALL to VERIFY BY EXECUTING — run build/test/lint or execute the code and read the REAL output instead of assuming code or calculations are correct. Returns stdout/stderr. Iterate on failures until the verification passes. For browsing or SEARCHING rendered websites prefer the `browse` tool over scraping HTML with curl, and NEVER use this tool to continue a task started in a browser (a search, a form, a booking, a checkout): the site's interactive session lives in the browser session, so only another `browse` call can carry it. (A skill/automation's own instructions win — follow what its SKILL.md / steps say.)",
            "parameters": {
                "type": "object",
                "properties": {
                    "command": { "type": "string", "description": "Shell command to run, e.g. \"curl -s https://example.com/feed.rss\" or \"pytest -q\"" },
                    "skill_id": { "type": "string", "description": "id of the context skill (optional; sets the working dir)" }
                },
                "required": ["command"]
            }
        }
    })
}

/// Capable (OpenAI-compatible) chat path with NATIVE TOOL-CALLING. The model is
/// given real tools and decides when to use them (no keyword routing). Tool
/// rounds run non-streamed; the final assistant answer is emitted as Delta+Done
/// to match the existing UI stream protocol.
/// Max chars of attachment text re-injected per turn (across all stored files).
const ATTACHMENT_TEXT_BUDGET_CHARS: usize = 120_000;
/// Max attachment page-images re-injected per turn (bounds vision token cost);
/// most-recent files win.
const ATTACHMENT_CONTEXT_IMAGES: usize = 12;

/// Appends the durable attachment working set to the user prompt and returns the
/// bounded image payload. Extraction failures are diagnostics, not document text:
/// keeping the two sections separate prevents the model from treating an error
/// string as if it had read the file.
fn append_thread_attachment_context(
    model_text: &mut String,
    working: &[chat_store::StoredAttachment],
) -> Vec<String> {
    if working.is_empty() {
        return Vec::new();
    }

    let manifest = working
        .iter()
        .map(|attachment| {
            let kind = if !attachment.images.is_empty() {
                "images/scan"
            } else if attachment
                .text
                .as_deref()
                .is_some_and(attachment_text_is_ready)
            {
                "text"
            } else {
                "unavailable"
            };
            format!("- {} ({kind})", attachment.display_name)
        })
        .collect::<Vec<_>>()
        .join("\n");
    model_text.push_str(&format!(
        "\n\n[Files attached to this conversation]\n{manifest}\n\
Ready attachment content follows. Entries marked unavailable were received but could not be \
extracted; do not claim to have analyzed them. If the user cites a file NOT in this list, ask \
them to attach it (don't look for it in the sandbox or folders).\n\
--- Attachment content ---"
    ));

    let mut text_budget = ATTACHMENT_TEXT_BUDGET_CHARS;
    for attachment in working {
        let Some(text) = attachment
            .text
            .as_deref()
            .map(str::trim)
            .filter(|text| attachment_text_is_ready(text))
        else {
            continue;
        };
        let slice: String = text.chars().take(text_budget).collect();
        text_budget = text_budget.saturating_sub(slice.chars().count());
        model_text.push_str(&format!("\n[{}]\n{}", attachment.display_name, slice));
        if text_budget == 0 {
            break;
        }
    }

    let issues = working
        .iter()
        .filter(|attachment| attachment.images.is_empty())
        .filter_map(|attachment| {
            let text = attachment.text.as_deref().map(str::trim).unwrap_or("");
            if text.starts_with("⚠️") {
                Some(format!("[{}]\n{text}", attachment.display_name))
            } else if text.is_empty() {
                Some(format!(
                    "[{}]\n⚠️ No extractable attachment content was produced.",
                    attachment.display_name
                ))
            } else {
                None
            }
        })
        .collect::<Vec<_>>();
    if !issues.is_empty() {
        model_text.push_str("\n\n[Attachment extraction issues]\n");
        model_text.push_str(&issues.join("\n"));
    }

    let mut images = Vec::new();
    'outer: for attachment in working.iter().rev() {
        for url in &attachment.images {
            if images.len() >= ATTACHMENT_CONTEXT_IMAGES {
                break 'outer;
            }
            images.push(url.clone());
        }
    }
    images
}

fn attachment_text_is_ready(text: &str) -> bool {
    let text = text.trim();
    !text.is_empty() && !text.starts_with("⚠️")
}

async fn stream_chat_via_openai(
    state: &AppState,
    request: ChatGenerateStreamRequest,
    base_url: String,
    model: String,
    api_key: Option<String>,
) -> Result<Response, GatewayError> {
    let applies_new_input = local_first_desktop_gateway::checkpoint_request_applies_new_input(
        request.agent_checkpoint.as_ref(),
        request.checkpoint_input.as_ref(),
    );
    let recovery_checkpoint = request
        .agent_checkpoint
        .clone()
        .map(serde_json::from_value::<local_first_engine::LoopCheckpoint>)
        .transpose()
        .map_err(|error| GatewayError {
            status: StatusCode::BAD_REQUEST,
            code: "agent_checkpoint_invalid",
            message: format!("Agent checkpoint schema is invalid: {error}"),
        })?;
    if let Some(checkpoint) = recovery_checkpoint.as_ref() {
        checkpoint.validate_schema().map_err(|error| GatewayError {
            status: StatusCode::BAD_REQUEST,
            code: "agent_checkpoint_invalid",
            message: format!("Agent checkpoint schema is invalid: {error}"),
        })?;
    }
    // Turn trace (readable per-turn observability): handle created HERE, at the absolute entry, so a
    // hang in SETUP (memory recall, prompt-build, browser-session) is visible — see engine::turn_trace.
    // The `turn_received` event is the FIRST thing recorded; if no `turn_start` follows, the turn
    // stalled before generation (a setup-hang would otherwise be invisible). Cheap Arc/None handle;
    // no-op when disabled. It's a pure sink — it records what the turn does, never steers it.
    let turn_trace = if turn_trace_enabled() {
        match gateway_logs_dir() {
            Ok(dir) => local_first_engine::turn_trace::TurnTrace::new(
                request.request_id.clone(),
                dir,
                turn_trace_max_bytes(),
            ),
            Err(_) => local_first_engine::turn_trace::TurnTrace::disabled(),
        }
    } else {
        local_first_engine::turn_trace::TurnTrace::disabled()
    };
    turn_trace.record(local_first_engine::turn_trace::TurnEvent::TurnReceived {
        prompt_head: request.prompt.chars().take(200).collect(),
        prompt_len: request.prompt.chars().count(),
        mode: request.mode.as_deref().unwrap_or("agent").to_string(),
        model: model.clone(),
    });
    // Scope MEMORY to THIS conversation's project (profile injection, recall, per-file
    // recall, extractor). Uses a dedicated memory scope — NOT the global active
    // workspace — so Composio's entity and the user's selected workspace are untouched.
    if let Some(tid) = request.thread_id.as_deref() {
        if let Ok(store) = lock_store(state)
            && let Ok(ws) = store.workspace_for_thread(tid)
        {
            set_memory_workspace(&ws);
        }
    } else {
        set_memory_workspace("");
    }
    // Channel turns are bound to a curated contact: persona/tone + isolation
    // perimeter (what memory/tools/info this reply may use). `channel_owner` = the
    // sender is the user themselves (is_self card) → channel gates that protect the
    // user from OTHERS (e.g. the browser click block) don't apply. Lock taken and
    // released inside; never held across the generation.
    let (contact_ctx, channel_owner) = contact_turn_context(state, request.thread_id.as_deref());
    if verbose_debug()
        && request
            .thread_id
            .as_deref()
            .is_some_and(|t| t.starts_with("channel_"))
    {
        eprintln!(
            "channel-turn: thread={} owner={} contact={}",
            request.thread_id.as_deref().unwrap_or("-"),
            channel_owner,
            contact_ctx.as_ref().map(|c| c.name.as_str()).unwrap_or("-"),
        );
    }
    // Real-idle signal (H3): only genuine user work counts — in-app turns and the
    // OWNER writing via a channel. An inbound contact message or Homun's own
    // headless check-in must NOT reset the idle clock.
    {
        let tid = request.thread_id.as_deref();
        let is_channel = tid.is_some_and(|t| t.starts_with("channel_"));
        let is_homun = tid == Some("homun");
        if !is_homun && (!is_channel || channel_owner) {
            note_user_activity();
        }
    }
    // Budget the prompt against the model's REAL context window (catalog `context_window`,
    // auto-filled from `/api/show`, F0.3d) instead of a flat 32k default — so a 128k model
    // keeps its long history and a small local model is clamped to what it can actually read.
    let model_context_window = registry_model_capabilities(&base_url, &model)
        .and_then(|caps| caps.context_length)
        .map(|tokens| usize::try_from(tokens).unwrap_or(usize::MAX));
    let effective_context = match request.thread_id.as_deref() {
        Some(thread_id) => {
            thread_context_for_model(state, thread_id, &[], Some(request.prompt.as_str()))
                .unwrap_or_default()
        }
        None => request.context.clone(),
    };
    let prompt = request
        .checkpoint_input
        .as_ref()
        .map(local_first_desktop_gateway::render_checkpoint_input)
        .unwrap_or_else(|| {
            build_chat_runtime_prompt(&BuildPromptRequest {
                prompt: request.prompt.clone(),
                context: effective_context.clone(),
                max_context_chars: Some(chat_context_budget_chars(model_context_window)),
            })
            .runtime_prompt
        });
    let browser_discovery = browser_open_research_discovery_instruction();
    let booking_choices = booking_assumption_choice_instruction();
    // ResumeBinding: consume the per-turn stash set by semantic short-circuit (not
    // prompt-heuristic on ‹‹CHOICES›› in prior assistant text).
    let hitl_choice_resume = take_hitl_resume_turn_context(state, request.thread_id.as_deref());
    let choice_resume_slot = hitl_choice_resume.as_ref().map(|ctx| {
        let browser_still_live = request
            .thread_id
            .as_deref()
            .is_some_and(|tid| thread_has_live_browser_session(state, tid));
        hitl_resume::hitl_resume_harness_slot(&ctx.wait, &ctx.resolution, browser_still_live)
    });

    let system = format!(
        "You are the local assistant acting as ORCHESTRATOR. Right now {now}: ALWAYS \
use this date/time to resolve temporal requests — do NOT rely on your internal \
knowledge of the date (it is almost always wrong). \"tomorrow\" = the day AFTER this \
date; \"June 10\" = June 10 of the correct year relative to this date; ALWAYS pick a \
time in the FUTURE. For any time slot (dates/times), call the resolve_datetime tool \
FIRST: it returns the correct absolute date to use (e.g. to fill in a form). Do not \
compute dates by hand. You have access to a real browser that YOU drive via granular \
tools (browser_navigate / browser_snapshot / browser_act / browser_rehydrate / browser_screenshot).\n\
\n\
METHOD (applies to any request, not just travel):\n\
1. UNDERSTAND: what the user wants and what the concrete EXPECTED RESULT is.\n\
2. SUCCESS CRITERIA: define explicitly what \"done\" means (which data/fields and how \
many options are needed) and keep it in mind while you work.\n\
3. CLARIFICATIONS: if a truly blocking and ambiguous parameter is missing, ask ONE \
concise question BEFORE searching; otherwise proceed with sensible defaults and \
STATE them (do not block the user over minor details).\n\
4. EXECUTE: when real-time web data or browser actions are needed, you MUST use the \
browser (do not say you have no internet access). Open the source with \
browser_navigate, read the snapshot and proceed ONE micro-action at a time. Keep \
2-3 candidate SOURCES in order of preference and try them in turn: if one is \
blocked/has no data, move to the next. Do not repeat the same search. For FACTUAL or \
statistical data (sports standings/results/schedules, reference figures, public \
timetables) PREFER a login-free, text-rich source (e.g. Wikipedia, an official \
schedule page) over login-walled, store, or marketing pages that return no data. \
{browser_discovery} \
EXTRACT AS YOU GO: the moment a page shows the data you need, COPY the concrete values \
(the actual table rows, names, numbers, dates) into your message text — do NOT defer \
extraction to \"later\" or across another tool call, because the page content is NOT \
retained once you navigate away or advance the plan. Your browsing budget is LIMITED: \
do NOT keep hopping across many sites for the same point. If ONE good static source \
already gives the data, take it and move on; do NOT chase JavaScript-heavy live-score \
or aggregator SPAs (they frequently fail to read) when an encyclopedic/text source \
already answers. Aim to settle each sub-question in 1-2 sources, not 5+.\n\
5. SYNTHESIZE: as soon as you have enough data, STOP using the browser and write the \
final answer to the user. Report the REAL status of each source: call a source \
\"blocked/unreachable\" ONLY if it failed to open or shows an explicit CAPTCHA. If \
you REACHED it but did not complete the search, do NOT say it is blocked or \
unreachable: say you got there but did not finish, show any partial data collected \
and offer to retry. REACHING a page and reading its data IS your verification: if you \
successfully read the data, you MUST report it — NEVER refuse with \"I can't state \
real-time facts without a verified source\" or \"the check was interrupted\" when you \
in fact read the page. Refuse ONLY if you never obtained the data at all. Always \
deliver the concrete data you DID gather rather than a meta-explanation of why you \
can't. CALIBRATED GROUNDING (critical): report as FACT only what you actually READ from \
a source. Anything you INFER, project, or that is NOT YET DETERMINED (results of matches \
not yet played, standings/brackets that depend on pending results) must be clearly \
LABELLED as projected/uncertain or OMITTED — never presented as established fact. It is \
contradictory to write \"live results not verifiable\" and then present a full \
results/bracket table as if confirmed: if you could not verify it, do not assert it. \
Prefer an accurate partial (\"decided so far: …; still open: …\") over a complete-looking \
but fabricated picture. Before sending, sanity-check internal consistency (counts match \
their labels; nothing is both \"already decided\" and \"played later today\").\n\
\n\
TOOLS AND ROUTING: when a request can be satisfied by a tool, USE it at once — do \
NOT reply with empty phrases (\"I'm ready, write to me\", \"what do you want me to \
do?\") nor ask to repeat what was already asked. A targeted clarification question \
(as in step 3 of METHOD) is fine; a non-answer is not.\n\
USER'S COMPUTER FILES AND FOLDERS: if the user wants to see/list/read files or \
folders on their computer — EVEN if they name the folder WITHOUT a path (e.g. \
\"the folders in Project\", \"the files in Documents\") — use `list_directory` / \
`read_text_file` on the most likely path INSIDE the user's home — the home is \
{home} (e.g. {home}/Projects, {home}/Documents) — or write `~/…` which I resolve. \
Do NOT invent a username (e.g. /Users/<random-name>/…): use {home} or `~/`. \
`list_files` / `read_file` are ONLY for code INSIDE the linked project folder \
(relative paths), NOT for the user's filesystem. \
`run_in_sandbox` is a throwaway container that does NOT see the user's computer: \
NEVER use it to inspect files/folders on the Mac. If you have no path hint, ask ONE \
targeted question; if the user is NOT talking about files/folders, do not use \
list_directory.\n\
ATTACHMENTS: files attached in chat arrive ALREADY as ready content (extracted text \
and/or images of the pages) under the \"[Files attached to this conversation]\" \
section. Analyze them from there directly. If the user says \"this file/pdf/\
attachment\" but there is NOTHING in that list, kindly ask to (re)attach it: do NOT \
use list_directory, run_in_sandbox or download links to find or decode it.\n\
AUTOMATIONS: for RECURRING or REACTIVE requests use `create_automation` (it creates \
a rule visible in the Automations section), do not just reply. \"every Friday / every \
morning / every Monday …\" → trigger_type=schedule with the recurrence. \"when X \
writes to me / when a message arrives from Y …\" → trigger_type=event (this is NOT a \
channel access request: it is a rule that fires on that message). \"when a \
mail/event arrives from a CONNECTED SERVICE (Gmail, Calendar, …)\" → \
trigger_type=event with event_tool (discover it via find_capability: the service's \
read tool), event_args (the query) and event_key_field (the id field, e.g. \
messageId): a poller checks it and fires on new items.\n\
TOOLS: you have a SMALL base set. For capabilities you do NOT see among your tools \
(browsing the web, searching GitHub, reading/listing the user's files and folders, \
running commands in a sandbox, creating artifacts, scheduling recurring tasks, …) \
call `find_capability` FIRST describing what you want to do: it activates the right \
tool, callable right after. The browser is NOT in the base set and is activated via \
`find_capability`: use it as a LAST resort, only if no more direct tool (e.g. \
`github_search` for GitHub) covers the request.\n\
EXTERNAL SERVICES (email, calendar, GitHub, …): call `find_capability` to discover \
the right tool (also search among connected services) and use it; if it finds \
nothing, call `suggest_capabilities` to propose what to connect. Never leave the \
user with a non-answer.\n\
\n\
Travel and follow-up: always carry with you ALL the parameters already resolved in \
the conversation (route/place, date with year, constraints). Even on a short \
follow-up (\"also search on easyJet\", \"and by train?\") resume the full objective, \
e.g. flights from Milan to Naples on June 10 2026, one-way, with times, duration, \
stops, price.\n\
\n\
Travel: if the user does NOT explicitly ask for a return, search ONE-WAY only. One \
passenger unless stated otherwise.\n\
When reporting results (flights, trains, hotels, …), be EXHAUSTIVE and SPECIFIC PER \
ROW: each option is its own row, NEVER merge different options into a generic row. \
For flights each row MUST indicate: airline, specific departure airport (e.g. \
Malpensa/Linate/Bergamo, not just \"Milan\") and arrival airport, departure and \
arrival times, duration, stops/changes and price. If the options are from different \
airlines or airports, the Airline and Airport columns are MANDATORY (do not leave \
ambiguous which price belongs to whom/where). Use a table and list several options, \
not just one.\n\
\n\
RESPONSE FORMATTING (markdown, always): write readable, airy answers, never a wall \
of text. ALWAYS use markdown: each item in a list goes on its OWN LINE with `- ` \
(dash) — do not paste multiple entries on the same line. For day/item lists with \
labels use `**Label**: value` with a blank line between entries, or a table if there \
are ≥3 fields. Put a blank line between paragraphs. Use `### ` for section headings \
when the answer is long. {language_instruction} Clear and well-structured.",
        now = now_block(),
        home = std::env::var("HOME").unwrap_or_else(|_| "~".to_string()),
        language_instruction = response_language_instruction(&effective_user_language()),
    );
    // Code-map steering: if THIS project has an imported code graph, tell the
    // orchestrator to query it FIRST for structure/dependency questions instead of
    // grepping/reading files by default (the natural reflex). Conditional: only when a
    // map exists for the active scope (else query_code_graph would just say "no map"
    // and grep is the correct fallback). Cheap count on the already-scoped workspace.
    let has_code_map = {
        let st = state.clone();
        tokio::task::spawn_blocking(move || {
            memory_facade(&st)
                .list_entities_for_ui(&gateway_memory_user_id(), &gateway_memory_workspace_id())
                .ok()
                .map(|ents| ents.iter().any(|e| e.entity_type.starts_with("code_")))
                .unwrap_or(false)
        })
        .await
        .unwrap_or(false)
    };
    let system = if has_code_map {
        format!(
            "{system}\n\nCODE MAP: this project has an indexed code map. \
For questions about code STRUCTURE or DEPENDENCIES — \"what methods/functions \
does X have\", \"who calls/uses Y\", \"what does Z use\", \"where is W defined/which files use it\" — \
call `query_code_graph` FIRST (it's instant and authoritative). For HISTORY or the WHY \
OVER TIME — \"why/when did X change\", \"the history of Y\" — use `query_git_history` \
(commit messages are the why). Resort to read_file/list_files/run_in_project ONLY \
if the map and history aren't enough (e.g. reading the BODY of a function). Do NOT grep/list \
files for questions the map or history already answer."
        )
    } else {
        system
    };
    // Connected-service (Composio) tools are reached via a DISCOVERY meta-tool
    // (`find_connected_tools`), not dumped into the prompt: the model searches by
    // intent, we return the few relevant tools and inject their schemas for the
    // next round. Keeps the prompt small and scales to hundreds of tools — the
    // pattern Composio/Claude use.
    let catalog = {
        let st = state.clone();
        tokio::task::spawn_blocking(move || composio_chat_tools_cached(&st, COMPOSIO_CATALOG_CAP))
            .await
            .unwrap_or_default()
    };
    let mut composio_writes = catalog.writes.clone();
    // (name, lowercased "name + description" haystack, schema) for keyword search.
    let mut catalog_index: Vec<(String, String, serde_json::Value)> = catalog
        .schemas
        .iter()
        .filter_map(|s| {
            let f = s.get("function")?;
            let name = f.get("name")?.as_str()?.to_string();
            let desc = f.get("description").and_then(|d| d.as_str()).unwrap_or("");
            let haystack = format!("{name} {desc}").to_lowercase();
            Some((name, haystack, s.clone()))
        })
        .collect();
    // MCP server tools join the SAME discovery surface as Composio: they appear in
    // `find_connected_tools` and their writes share the confirmation gate. Read
    // from the local SQLite cache (cheap), still off the runtime to be safe.
    let mcp_catalog = {
        let st = state.clone();
        tokio::task::spawn_blocking(move || mcp_chat_tools(&st, MCP_CATALOG_CAP))
            .await
            .unwrap_or_default()
    };
    let filesystem_mcp_connected = mcp_catalog.schemas.iter().any(|schema| {
        schema
            .pointer("/function/name")
            .and_then(|name| name.as_str())
            .is_some_and(|name| name.starts_with("mcp__filesystem__"))
    });
    let system = match project_filesystem_mcp_instruction(
        project_root_for_thread(state, request.thread_id.as_deref()).as_deref(),
        filesystem_mcp_connected,
    ) {
        Some(instruction) => format!("{system}\n\n{instruction}"),
        None => system,
    };
    composio_writes.extend(mcp_catalog.writes.iter().cloned());
    for schema in &mcp_catalog.schemas {
        if let Some(f) = schema.get("function")
            && let Some(name) = f.get("name").and_then(|n| n.as_str())
        {
            let desc = f.get("description").and_then(|d| d.as_str()).unwrap_or("");
            let haystack = format!("{name} {desc}").to_lowercase();
            catalog_index.push((name.to_string(), haystack, schema.clone()));
        }
    }
    // `send_message` is a side-effecting action → route it through the same write-confirm
    // card as Composio/MCP writes (the confirm endpoint dispatches it to channel_send).
    composio_writes.insert("send_message".to_string());
    let composio_writes = composio_writes; // freeze: (Composio + MCP) write tools
    let has_composio = !catalog_index.is_empty();
    let system = if !has_composio {
        system
    } else {
        format!(
            "{system}\n\nCONNECTED-SERVICE TOOLS: the user has connected some services (e.g. Gmail, \
Google Calendar). To access them do NOT say you can't: call `find_capability` with a query \
about the intent (e.g. \"unread emails\", \"send email\", \"calendar events today\") to discover the \
right tool, then CALL the found tool with the complete arguments.\n\
TOOL CHOICE: use ONE SINGLE tool that matches the intent EXACTLY — for \
ADDING/CREATING use create/add/quick_add, for READING use fetch/list. NEVER call destructive \
tools (delete/remove/cancel) unless the user explicitly asks. find_capability \
finds the service's tools: to MODIFY something existing (e.g. the date of \
an event) use update/patch (NOT 'move', which moves between calendars). Do NOT conclude that a \
tool is missing after a single search.\n\
DATES AND TIMES: ALWAYS compute the ABSOLUTE date/time starting from 'Today is ...' above (e.g. tomorrow = today \
+ 1 day) and pass it to the tool in EXPLICIT ISO 8601 format with the timezone (e.g. \
start_datetime: 2026-06-08T11:00:00+02:00, end_datetime one hour later). Do NOT pass relative words \
like \"tomorrow\"/\"today\" in the arguments: the service's parsing may get the day wrong. Prefer \
a tool with explicit start/end over the textual \"quick add\" for times.\n\
WRITE ACTIONS (send/delete/modify): CALL the tool anyway with the complete arguments \
— the system will AUTOMATICALLY show the user a confirmation card before executing. \
Do NOT refuse, do NOT say you can't send, and do NOT ask the user to do it manually: your \
job is to call the right tool, the interface handles confirmation.\n\
COUNTS (e.g. \"how many unread emails\"): use the correct filter (for Gmail query \"is:unread\") and \
report the TOTAL indicated by the result (a field like resultSizeEstimate / total / nextPageToken \
absent), NOT the number of messages on the single returned page; if the result is paginated and \
doesn't give a reliable total, state that it's an estimate."
        )
    };
    // Connected-but-EXPIRED services: the integration EXISTS, the OAuth lapsed. Tell
    // the model so it says "reconnect" instead of "I have no integration" (the bug
    // that surfaced on a real "leggi le email" with an expired Gmail).
    let system = if catalog.inactive.is_empty() {
        system
    } else {
        format!(
            "{system}\n\nCONNECTED BUT EXPIRED SERVICES (slug): {}. The connection EXISTS but \
the authorization has EXPIRED. If the user asks for one of these services: do NOT say you don't have \
the integration; explain in ONE sentence that the connection has expired and just needs reauthorizing, and \
INCLUDE in the reply the marker (on its own line) `‹‹COMPOSIO_RECONNECT››<slug>‹‹/COMPOSIO_RECONNECT››` \
with only the slug of the affected service (e.g. gmail): the interface will show a \
\"Reconnect\" button that reopens authorization in one click.",
            catalog.inactive.join(", ")
        )
    };
    // Installed skills (Anthropic Agent Skills, progressive disclosure L1): pre-load
    // name+description; the model calls `use_skill(<id>)` to pull the full SKILL.md
    // when a request matches, then follows it.
    let homuncoder = tokio::task::spawn_blocking(homuncoder_skill_ids)
        .await
        .unwrap_or_default();
    // HomunCoder mode: the methodology skills surface only in PROJECT chats, so personal
    // chats aren't flooded with ~30 dev-discipline skills.
    let is_project = gateway_memory_workspace_id().as_str() != PERSONAL_WORKSPACE;
    let mut enabled_skills = tokio::task::spawn_blocking(enabled_skills_summary)
        .await
        .unwrap_or_default();
    if !is_project {
        enabled_skills.retain(|(id, _, _)| !homuncoder.contains(id));
    }
    let has_skills = !enabled_skills.is_empty();
    // The "Homun apprentice" persona (proactive/curious/onboarding on a dedicated
    // "homun" thread) is RETIRED: proactivity now lives solely in the Proattività
    // plugin (supervisor → cards). No per-thread persona prompt anymore.
    // Channel-contact persona + privacy perimeter. Prepended (like the Homun block,
    // which is mutually exclusive: homun is never a channel_ thread) so the contact
    // rules dominate the generic orchestrator voice.
    let system = if let Some(cx) = &contact_ctx {
        let mut block = format!(
            "REPLYING TO A CONTACT VIA CHANNEL: you are replying to {} on a \
messaging channel, on behalf of the user. Chat style: natural and concise.",
            cx.name
        );
        if !cx.tone_of_voice.trim().is_empty() {
            block.push_str(&format!(" REQUESTED TONE: {}.", cx.tone_of_voice.trim()));
        }
        if !cx.persona_instructions.trim().is_empty() {
            block.push_str(&format!(
                "\nPERSONA INSTRUCTIONS (always follow them): {}",
                cx.persona_instructions.trim()
            ));
        }
        if !cx.relationships.is_empty() {
            block.push_str(&format!(
                "\nKNOWN RELATIONSHIPS of {}: {}.",
                cx.name,
                cx.relationships.join("; ")
            ));
        }
        if !cx.perimeter.can_see_contacts {
            block.push_str(
                "\n[PRIVACY] NEVER mention other contacts, people or relationships \
of the user: with this person you know ONLY them.",
            );
        }
        if !cx.perimeter.can_see_calendar {
            block.push_str(
                "\n[PRIVACY] NEVER mention the user's commitments, appointments or \
calendar events.",
            );
        }
        format!("{block}\n\n{system}")
    } else {
        system
    };
    let system = if !has_skills {
        system
    } else {
        let lines = enabled_skills
            .iter()
            .map(|(id, name, desc)| format!("- {id}: {name} — {desc}"))
            .collect::<Vec<_>>()
            .join("\n");
        let methodology = if is_project
            && enabled_skills
                .iter()
                .any(|(id, _, _)| homuncoder.contains(id))
        {
            "\nMETHODOLOGY (HomunCoder) — for DEVELOPMENT work follow the evidence-first habits: \
plan with update_plan, REMEMBER/record decisions with their why, and VERIFY by executing \
(build/test/lint) before saying \"done\". When you apply one of these disciplines, call \
`use_skill` FIRST with the right skill (roadmap-first-planning, systematic-debugging, test-first-development, \
verification-before-completion, code-review-discipline, …) — so the user SEES which methodology \
you're following — and then follow its instructions. Don't just cite it: actually load it with use_skill."
        } else {
            ""
        };
        format!(
            "{system}\n\nINSTALLED SKILLS — when the request matches the description of one \
of these, PREFER it over the browser: call `use_skill` with its id to receive the complete \
instructions (SKILL.md). Then RUN the commands the skill indicates (e.g. `curl …`, `python …`) with the \
`run_in_sandbox` tool, which launches them in the contained computer, and use the output to reply.\n\
GENERATED FILES: if a skill or a command produces files (xlsx, pdf, csv, images, …), SAVE them in the \
environment folder `$OUTPUT_DIR` (e.g. `... --output \"$OUTPUT_DIR/report.xlsx\"`): files there \
automatically become artifacts downloadable by the user.{methodology}\n{lines}"
        )
    };
    // Inline choice prompts (Claude-Code style): when the answer is a pick among a few
    // discrete options, the model emits a CHOICES marker that the UI renders as clickable
    // single/multi-select buttons, instead of listing the options in prose.
    let system = format!(
        "{system}\n\nCHOICES: when you ask the user to choose among discrete OPTIONS \
(roughly 2-6 alternatives), you MUST emit on its own line the marker \
`‹‹CHOICES››{{\"question\":\"the question\",\"multi\":false,\"options\":[\"Option A\",\"Option B\"]}}‹‹/CHOICES››` \
(valid JSON; \"multi\":true if more than one can be chosen). Do NOT only list options in a markdown \
table or ask \"which do you prefer?\" in prose — without the marker the UI has no clickable buttons. \
The user will see clickable buttons and their choice will come back as a message. Use it ONLY for \
closed choices, not for open questions (name/email/free text).\n\
CLARIFY: when you need FREE-TEXT details from the user (name, email, phone, dates, payment prefs, …), \
you MUST emit on its own line \
`‹‹CLARIFY››{{\"question\":\"what you need\",\"fields\":[\"name\",\"email\"]}}‹‹/CLARIFY››` \
(valid JSON; \"fields\" optional). Do NOT only ask in prose — without the marker the harness cannot \
wait/resume correctly and will keep nudging the plan."
    );
    let system = format!("{system}\n{booking_choices}");
    let system = match choice_resume_slot {
        Some(resume) => format!("{system}\n\n{resume}"),
        None => system,
    };
    // Authorized write destinations: when present, the model can deliver
    // generated files to user-granted folders via `save_artifact`.
    let artifact_destinations = load_artifact_destinations();
    let system = if artifact_destinations.is_empty() {
        system
    } else {
        let labels = artifact_destinations
            .iter()
            .map(|d| d.label.as_str())
            .collect::<Vec<_>>()
            .join(", ");
        format!(
            "{system}\n\nDESTINATION FOLDERS: you can deliver generated files to these folders \
AUTHORIZED by the user with the `save_artifact` tool: {labels}. When the user asks to \
save/export a file to a folder, call save_artifact(file, destination)."
        )
    };
    // Layer boundary: everything added below through the end of recall assembly
    // is workspace/thread knowledge, not a core instruction. Keep the provider
    // prompt text-compatible while exposing the real content boundary to the
    // Prompt Inspector and independent budgets.
    let prompt_core = system.clone();
    let active_objective_contract =
        objective_contract_for_execution(state, request.thread_id.as_deref());
    let semantic_contract = active_objective_contract
        .as_ref()
        .and_then(semantic_decision::semantic_decision_from_contract);
    let objective_effect_policy =
        semantic_decision::ObjectiveEffectPolicy::from_contract(active_objective_contract.as_ref());
    catalog_index.retain(|(name, _, _)| {
        !objective_blocks_tool(&objective_effect_policy, name, &composio_writes)
    });
    let memory_intent = semantic_contract
        .as_ref()
        .map(|semantic| semantic.decision.memory_intent.clone())
        .unwrap_or_else(semantic_decision::MemoryIntent::safe_default);
    let memory_recall_allowed = memory_intent_allows_recall(&memory_intent);
    let memory_injection = memory_injection_policy(&memory_intent);
    // Memory scope. Perimeter "contact_only" (the default for channel contacts) is a
    // HARD gate: the user's personal profile + RAG are NOT injected — the turn only
    // sees the conversation history with THIS contact. "personal" opts a trusted
    // contact back into today's behavior.
    let contact_only = contact_ctx
        .as_ref()
        .map(|c| c.perimeter.memory_scope == "contact_only")
        .unwrap_or(false);
    // Finer-grained perimeter axes, independent of memory_scope. A contact opted into
    // "personal" memory (NOT contact_only) can still have can_see_contacts/can_see_calendar
    // = false; these are enforced HARD at dispatch below (not only in the prompt), so the
    // address book / calendar can't be exfiltrated even when broad memory is allowed.
    // No contact perimeter (self / in-app turn) → unrestricted.
    let (can_see_contacts, can_see_calendar) = contact_ctx
        .as_ref()
        .map(|c| (c.perimeter.can_see_contacts, c.perimeter.can_see_calendar))
        .unwrap_or((true, true));
    let can_use_project_memory = contact_ctx
        .as_ref()
        .map(|context| context.can_use_project_memory)
        .unwrap_or(true);
    // This is emitted as a structured stream event once the transport exists below.
    // Keep it next to prompt assembly so UI provenance and actual RAG context cannot diverge.
    let mut automatic_recall_payload = None;
    let system = if contact_only {
        let cx = contact_ctx
            .as_ref()
            .expect("contact_only implies contact_ctx");
        let episodes = {
            let facade = memory_facade(state);
            let user = gateway_memory_user_id();
            episode_texts_by_handles(facade, &user, &cx.handles)
        };
        if episodes.is_empty() {
            system
        } else {
            let mut block = String::from("HISTORY WITH THIS CONTACT (the only memory available):");
            let mut used = 0usize;
            for text in episodes.iter().rev().take(40).rev() {
                if used + text.len() > CHAT_MEMORY_BUDGET_CHARS {
                    break;
                }
                used += text.len();
                block.push_str("\n- ");
                block.push_str(text);
            }
            format!("{system}\n\n{block}")
        }
    } else if !memory_perimeter_allows_recall(
        contact_only,
        can_see_contacts,
        can_use_project_memory,
        is_project,
    ) {
        let scope = scope_from_active_workspace();
        automatic_recall_payload = Some(local_first_subagents::RecallStreamPayload {
            query: request.prompt.clone(),
            hits: Vec::new(),
            scope: match scope {
                MemoryScope::Personal => "personal".to_string(),
                MemoryScope::Project(_) | MemoryScope::Thread { .. } => "project".to_string(),
            },
            status: "denied".to_string(),
        });
        system
    } else {
        // Always-on memory profile (M1): inject what we durably know about the user
        // (personal scope) and the active project, so the chat is continuous instead
        // of starting cold every turn. Sensitive items are excluded here by design.
        //
        // ADR 0022 — Tappa 1: di default l'assemblaggio del briefing è
        // incapsulato in `MemoryRecallService::brief` (che delega alle stesse
        // funzioni, nello stesso ordine). Opt-out
        // `HOMUN_MEMORY_SERVICE=0`/`off`/`false` → path inline.
        let system = if let Some(service) = state.memory_service.as_ref() {
            let scope = memory_scope_for_turn(request.thread_id.as_deref());
            let pack = service.brief(&scope, &request.prompt);
            if !pack.linked_hits.is_empty() {
                merge_automatic_recall_payload(
                    &mut automatic_recall_payload,
                    recall_stream_payload_from_hits(&request.prompt, &scope, &pack.linked_hits),
                );
            }
            // ordered_blocks() = [profile, objective, brief, recent_work] — stesso
            // ordine dell'assemblaggio inline qui sotto. Mantiene la parità.
            let mut system = system;
            for block in pack.ordered_blocks().into_iter().flatten() {
                system = format!("{system}\n\n{block}");
            }
            system
        } else {
            let (memory_personal, memory_project) =
                gather_profile_memory_for_intent_with_provenance(state, &memory_intent);
            let memory_open_loops = if memory_injection.include_cross_thread {
                gather_open_loops(state, 6)
            } else {
                Vec::new()
            };
            let formatted_profile = format_memory_block_with_provenance(
                &memory_open_loops,
                &memory_personal,
                &memory_project,
                CHAT_MEMORY_BUDGET_CHARS,
            );
            if !formatted_profile.linked_hits.is_empty() {
                let scope = scope_from_active_workspace();
                merge_automatic_recall_payload(
                    &mut automatic_recall_payload,
                    recall_stream_payload_from_hits(
                        &request.prompt,
                        &scope,
                        &formatted_profile.linked_hits,
                    ),
                );
            }
            let system = match formatted_profile.block {
                Some(block) => format!("{system}\n\n{block}"),
                None => system,
            };
            // Project OBJECTIVE (always-on, FIRST): the north star + focus directive, so the
            // assistant keeps every implementation aligned and flags drift.
            let system = match project_objective_block(state) {
                Some(block) => format!("{system}\n\n{block}"),
                None => system,
            };
            // Project BRIEF (always-on): recent state, so "where this project is" is present
            // every turn — not just when the prompt happens to match.
            let system = match project_brief_block(state) {
                Some(block) => format!("{system}\n\n{block}"),
                None => system,
            };
            // Recent work (always-on): the last commits, so a new conversation resumes the
            // thread of what was just being done instead of starting cold.

            match recent_work_block(state) {
                Some(block) => format!("{system}\n\n{block}"),
                None => system,
            }
        };
        let thread_memory = request
            .thread_id
            .as_deref()
            .filter(|_| memory_injection.include_current_thread)
            .and_then(|thread_id| current_thread_episode_block(state, thread_id));
        let system = match thread_memory {
            Some(block) => format!("{system}\n\n{block}"),
            None => system,
        };
        // Goal-propose affordance (projects only): when the model articulates the project's
        // objective, it emits a marker → the UI shows a "Salva come obiettivo" card. This is
        // content-contextual via a MODEL-emitted affordance (not keyword parsing).
        let system = {
            let ws = gateway_memory_workspace_id();
            if ws.as_str() != PERSONAL_WORKSPACE && ws.as_str() != THREADS_WORKSPACE {
                format!(
                    "{system}\n\nIf you ARTICULATE or PROPOSE the OBJECTIVE or direction of THIS project \
(e.g. the user asks \"propose an objective\", or you are defining where the \
project should go), emit on its own line the marker \
‹‹GOAL_PROPOSE››{{\"objectives\":[\"objective 1\",\"objective 2\"]}}‹‹/GOAL_PROPOSE›› with 1-3 \
SHORT objectives looking FORWARD (the direction/the goal, NOT decisions already taken). \
The user will see a card to save them. Use it ONLY for real project objectives, never for \
normal answers."
                )
            } else {
                system
            }
        };
        // RAG: inject memory relevant to THIS prompt (decisions/facts), so the model
        // answers from what was already decided instead of saying it has nothing.
        // ADR 0022 — Tappa 1/4: via service quando il flag è ON; anche nel path OFF
        // usa le fn del crate (embed_query + recall_search_on_facade) con capability
        // client al volo — così `relevant_memory_for_prompt` non è più duplicata.
        let system = if memory_injection.include_cross_thread && applies_new_input {
            if let Some(service) = state.memory_service.as_ref() {
                let scope = memory_scope_for_turn(request.thread_id.as_deref());
                let pack = service.recall(&request.prompt, &scope).await;
                merge_automatic_recall_payload(
                    &mut automatic_recall_payload,
                    recall_stream_payload_from_pack(&pack),
                );
                let status = memory_access_status_instruction(pack.status);
                let system = match pack.block {
                    Some(block) => format!("{system}\n\n{block}"),
                    None => system,
                };
                format!("{system}\n\n{status}")
            } else {
                // Path OFF: stessa orchestrazione del crate, capability client al volo.
                let user = gateway_memory_user_id();
                let workspace = gateway_memory_workspace_id();
                let embedding: std::sync::Arc<dyn local_first_memory::EmbeddingClient> =
                    gateway_embedding_client(state.http.clone());
                let query_vec =
                    local_first_memory::embed_query(embedding.as_ref(), &request.prompt).await;
                let block = {
                    let facade = memory_facade(state);
                    let graph_context: Option<&local_first_memory::GraphContextHook<'_>> =
                        Some(&|facade, user, workspace, q| {
                            if let Some(workflow) =
                                workflow_status_context_for_query(facade, user, workspace, q)
                            {
                                return Some(workflow);
                            }
                            artifact_provenance_context_for_query(facade, user, workspace, q)
                        });
                    recall_pack_on_facade(
                        facade,
                        &user,
                        &workspace,
                        &request.prompt,
                        &query_vec,
                        graph_context,
                    )
                };
                merge_automatic_recall_payload(
                    &mut automatic_recall_payload,
                    recall_stream_payload_from_pack(&block),
                );
                let status = memory_access_status_instruction(block.status);
                let system = match block.block {
                    Some(block) => format!("{system}\n\n{block}"),
                    None => system,
                };
                format!("{system}\n\n{status}")
            }
        } else {
            system
        };
        // Anti-rewrite anchor: existing code components matching the request, so the
        // model extends/reuses instead of re-implementing (no-regression by default).
        match relevant_code_components_for_prompt(state, &request.prompt) {
            Some(block) => format!("{system}\n\n{block}"),
            None => system,
        }
    };
    let prompt_workspace = system
        .strip_prefix(&prompt_core)
        .unwrap_or_default()
        .trim()
        .to_string();
    let system = prompt_core.clone();
    let system = format!(
        "{system}\n\nMEMORY: you have a long-term memory of the user. If you need a personal \
or project detail you may have already learned (a name, a preference, a fact, a \
past decision and its why), OR if the user asks what was discussed or decided in \
PREVIOUS conversations, and the information is NOT already in the profile above, ALWAYS call the \
recall_memory tool BEFORE saying you don't know or don't remember. \
RECALL-BEFORE-ASKING: when the user refers to a POSSESSION, a PERSON or a \
CONTEXT they take as already known (typically with a possessive: «my motorbike», «my boss», «my \
house», «my brother», «my management software»…) and to act you need a detail about it that is NOT \
already in the profile above, do NOT instinctively ask the user: call recall_memory FIRST and USE what \
you find; then ask ONLY for the details that are truly still missing after the recall. \
E.g.: «find me a fuel cap for my motorbike» → recall_memory(«user's motorbike, make \
model year») → if you find «Moto Guzzi V7 Stone 850 2021» proceed with that and ask for the year only if \
it's not in memory. This concerns DURABLE facts plausibly already learned, not \
ephemeral information or things that just came up in the conversation. \
DECISIONS: BEFORE modifying a project's code/documents, call recall_memory to remember \
why things are the way they are (do NOT re-scan everything from scratch). AFTER a non-trivial choice — in \
ANY domain: code, a document (e.g. a customer quote), data, configurations — call \
record_decision with what you decided, the WHY, the rejected alternatives and the objects touched, so \
the rationale stays and doesn't have to be reconstructed. \
SENSITIVE VAULT: sensitive values are NOT in ordinary memory. If the user asks for a sensitive personal \
value (identity document, fiscal/tax code, vehicle plate, health note, credentials, payment data, private \
note), call recall_memory before saying you don't know it: if normal memory has no match, the gateway \
checks Vault metadata internally and returns only redacted metadata. Never reveal, infer, or guess the \
secret value from metadata. If a matching record exists, say it is saved in the Vault and local PIN unlock \
is required to reveal or edit it. If recall_memory returns a `reveal_card:` line, COPY the marker after \
`reveal_card:` EXACTLY into your final answer on its own line; do not paraphrase it. The UI hides that \
marker and renders the PIN unlock card. Do NOT send or forward raw Vault secret values through \
generic external channels/tools such as send_message. The configured Telegram authorization channel may \
receive Vault/payment summaries or approval prompts, but raw-value reveal stays behind the local PIN \
unlock card unless a dedicated approved reveal flow exists. \
OPERATIONAL PLAN: for a non-trivial MULTI-STEP task, call update_plan and then continue executing \
in the SAME turn. The plan is a live projection of the canonical objective, not a separate artifact \
and not an approval gate. Replace or revise it autonomously when the new steps are only a better way \
to reach the SAME objective. Ask the user before continuing only when the validated semantic decision \
says the request changes the objective, expands its scope, or introduces new effects. Use update_plan \
to create or revise the operational plan; do not write a free-form numbered plan in prose. \
Use update_plan to update the step status (doing→done), shown in the \
\"Plan\" panel. To move a step's status (e.g. doing→done) call step_advance with its id (shown in \
parentheses after the title in the plan card) and the new status — this updates that ONE step \
WITHOUT re-sending the plan, so steps never duplicate; use update_plan only to CREATE or revise \
the plan. GOAL: when CREATING the plan you MUST set the top-level `goal` field to the user's \
objective in ONE sentence, written in the USER'S language (use null when you are only updating \
step statuses of an existing plan). The plan is ALREADY shown to the user as a CARD: do NOT \
repeat it in the reply text too — no list or table of the steps in prose (at most one \
line of context). For single-step requests no plan is needed. \
STEP-AT-A-TIME EXECUTION: work the plan ONE step at a time — do, then VERIFY that step's \
result (file written, search returned usable results, build/render succeeded), and only \
THEN mark it `done` with update_plan before starting the next. Give each step a \
`done_criterion` (the concrete, checkable proof it's finished): a step you mark done is \
INDEPENDENTLY verified against its evidence before it counts — if it isn't actually complete \
you'll be told and must keep working on it. Your working budget RESETS every time a step is \
verified complete, so a long task (e.g. a 10-slide deck, a deep research) can run as long as \
it KEEPS CLOSING STEPS — never rush or skip verification to save rounds, and never mark a \
step done before its result actually exists. RESUMING: if the conversation ALREADY shows an \
in-progress plan (some steps done, others not), CONTINUE it — re-emit the plan with update_plan \
keeping the completed steps as done, and proceed from the first not-done step; do NOT restart \
from scratch or re-propose."
    );
    let system = if memory_recall_allowed {
        system
    } else {
        format!(
            "{system}\n\nMEMORY SCOPE FOR THIS OBJECTIVE: long-term recall and Vault lookup are not authorized. Use only current-thread context and current-turn tool evidence; do not call recall_memory."
        )
    };
    // LANGUAGE: the whole system prompt is in English, so without an explicit
    // directive coding-oriented models (e.g. kimi-*-code) reply in English even to an
    // Italian request — narration AND final answer. Pin it to the user's language.
    let system = format!(
        "{system}\n\nLANGUAGE: ALWAYS write in the SAME language as the user's latest \
message — both your step-by-step narration AND the final answer. If the user writes in \
Italian, reply entirely in Italian; if in English, in English. Match the user and never \
switch language on your own. (Tool arguments, code, file paths and URLs stay as-is.)"
    );
    // An active thread-scoped RoutingBinding records an exact route the user already selected.
    // It remains authoritative over the model-owned semantic decision; absent or malformed
    // bindings fall back to that structured decision, never to prompt keyword routing.
    let routing_binding: Option<RoutingBinding> =
        active_routing_binding(state, request.thread_id.as_deref());
    let capability_route =
        route_capability_with_binding(semantic_contract.as_ref(), routing_binding.as_ref());
    let workflow_route = workflow_route_from_capability(&capability_route);
    // S2 T4/T5: resolve the binding's WorkflowRouting ONCE — when it survived plan-precedence
    // AND still resolves to a registered routing — so the hard-prune's `deny_tools` (T4) and the
    // forced `tool_choice` gate (T5) both read off the SAME resolution.
    let resolved_workflow_routing = routing_binding
        .as_ref()
        .filter(|_| matches!(workflow_route, WorkflowRouteDecision::Workflow { .. }))
        .and_then(resolve_workflow_routing);
    // S2 T4: carry its `deny_tools` to the prune call sites below — hard-prune removes
    // skill:*/run_command/shell/the-sibling-make_* explicitly, not just by omission.
    let workflow_deny_tools: Vec<String> = resolved_workflow_routing
        .as_ref()
        .map(|routing| routing.deny_tools.clone())
        .unwrap_or_default();
    // S2 T5: force `tool_choice` to the routed tool — belt-and-suspenders on top of the hard-
    // prune above — but ONLY once the intake exchange is done. On the workflow's FIRST turn
    // (right after "Use template") the model must stay free to ask clarifying questions
    // ("auto"); forcing immediately would railroad an empty/guessed brief into the tool call.
    // Turn-index heuristic: the thread already carries >=2 user messages (the seed "Use
    // template" prompt + at least one intake reply) by the time generation runs here — the
    // broker inserts the CURRENT turn's user message atomically at enqueue, before the worker
    // ever calls in (see `enqueue_chat_turn_core`), so a plain count already includes it.
    // Final-review fix (I3): only compute the user-message count when a binding actually
    // resolved — `thread_user_message_count_fail_open` loads the WHOLE thread message history
    // + takes a store lock, and `forced_tool_for_turn` returns `None` unconditionally when
    // `routing` is `None` anyway, so an ordinary turn (no binding) previously paid for that
    // load and threw the result away. Gating here skips the messages() load entirely for the
    // overwhelming majority of turns; behavior is identical when a binding IS present.
    let forced_tool: Option<String> = match resolved_workflow_routing.as_ref() {
        Some(routing) => forced_tool_for_turn(
            Some(routing),
            thread_user_message_count_fail_open(state, request.thread_id.as_deref()),
        ),
        None => None,
    };
    let system = match capability_router_instruction_for_decision(&capability_route) {
        Some(instruction) => format!("{system}\n\n{instruction}"),
        None => system,
    };
    let system = format!(
        "{system}\n\nFRESHNESS / VERIFICATION: your internal knowledge may be dated. For ANY \
question whose answer depends on information that changes over time or that requires up-to-date \
accuracy — news and current events, the state/condition/health of people, results or scores, prices, \
schedules, rankings; but ALSO software (libraries, frameworks, APIs, SDKs, tools: versions, syntax, \
options, best practices, current state of the art) — you MUST verify on the web with the browser, preferring the \
OFFICIAL documentation or recent sources, BEFORE answering, instead of answering from memory. NEVER \
cite a source (site/publication/doc) you haven't actually opened in THIS turn: no invented sources, \
versions or dates. If you can't verify, say so openly instead of guessing. Timeless \
questions (concepts, logic, generic code) you can answer directly."
    );
    let system = format!(
        "{system}\n\nEXECUTION / VERIFICATION: when you produce CODE or a calculation and you have the \
execution tool (run_in_sandbox), do NOT assume it works — VERIFY BY EXECUTING: run build/test/lint or \
run the code, read the REAL output and iterate on the failures until it passes, BEFORE saying it's done. \
Trust the compiler and the tests, not your estimate."
    );
    let system = format!("{system}\n\n{}", manager_browser_guidance());
    // Composer interaction mode (agent = default). plan/ask/debug refine behavior;
    // "ask" also drops the toolset below (pure conversation).
    let mode = request.mode.as_deref().unwrap_or("agent").to_string();
    // Model tier remains useful observability for role selection and evals; it no longer changes
    // the agent-loop control flow.
    let turn_tier = load_provider_registry().tier_for_model(&model);
    // Turn trace: setup COMPLETED (memory recall and prompt-build) and generation is about to begin.
    // A `turn_start` following a `turn_received` implies setup succeeded (no pre-gen hang).
    turn_trace.record(local_first_engine::turn_trace::TurnEvent::TurnStart {
        prompt_head: request.prompt.chars().take(200).collect(),
        prompt_len: request.prompt.chars().count(),
        mode: mode.clone(),
        model: model.to_string(),
        tier: turn_tier.as_str().to_string(),
    });
    let system = match mode.as_str() {
        "plan" => format!(
            "{system}\n\nPLAN MODE (chosen by the user): maintain the canonical operational plan with \
update_plan and continue execution in this turn. Replan autonomously while the objective, scope and effects stay unchanged."
        ),
        "ask" => format!(
            "{system}\n\nASK MODE (chosen by the user): answer by conversing from your \
knowledge and memory. Do NOT use tools and do NOT perform external actions (no browser, files, \
sends, searches). If answering would require a tool, say so and suggest switching to \
Agent mode."
        ),
        "debug" => format!(
            "{system}\n\nDEBUG MODE (chosen by the user): SYSTEMATIC debugging — reproduce the \
problem, isolate the cause, form a hypothesis, verify it with a minimal experiment, then fix and \
RE-VERIFY by executing. One cause at a time, no blind attempts."
        ),
        _ => system,
    };
    let system = match objective_contract_for_execution(state, request.thread_id.as_deref()) {
        Some(objective) => format!(
            "{system}\n\nOBJECTIVE CONTRACT (canonical, harness-enforced): revision {}; mode={:?}; objective={}. Stay inside its scope and allowed actions. Replan autonomously only when the objective, scope and mutation level stay unchanged. A new objective, wider scope or newly mutating action requires explicit user confirmation. Plan completion requires recorded evidence; response length is never completion evidence.",
            objective.revision, objective.mode, objective.objective
        ),
        // No contract does NOT mean "no rules": execution defaults to read-only analysis, so the
        // effectful tools are gated. Saying nothing here was the worst combination — the gate was armed
        // and the model had no idea, so its writes came back refused for reasons it could not see.
        None => format!(
            "{system}\n\nOBJECTIVE CONTRACT: none recorded for this task, so execution defaults to READ-ONLY analysis. Reading, searching, browsing and analysing are available; tools that change something (writing files, sending, creating, booking, purchasing) are refused until the user asks for that change. Do the read-only work and say plainly what you would need to change, rather than attempting it."
        ),
    };
    let prompt_runtime = system
        .strip_prefix(&prompt_core)
        .unwrap_or_default()
        .trim()
        .to_string();
    let (system, prompt_packets) = compose_gateway_prompt_packets(
        state,
        request.thread_id.as_deref(),
        prompt_core,
        prompt_workspace,
        prompt_runtime,
    );
    let system = system.as_str();
    // (The 401/tool-compat/timeout fallback flags moved into GatewayModelClient::generate,
    // which now owns the per-round provider swap — ADR 0024.)
    // Channel turns run read-only: offer only tools without side effects (search,
    // recall, skill instructions, Composio reads). Side-effecting tools (write
    // files, run sandbox, Composio writes) are withheld → Phase 2 routes them to
    // approval. App chat (tool_policy unset) keeps the full toolset.
    let read_only = request.tool_policy.as_deref() == Some("read_only");
    // `autonomous` (set only by an Automation run whose rule is ApprovalPolicy::Autonomous):
    // side-effecting tools EXECUTE directly instead of proposing a confirm card. This is the
    // user's explicit per-automation opt-in; everything else still confirms.
    let autonomous = request.tool_policy.as_deref() == Some("autonomous");
    // Browser toolset: the main agent ALWAYS drives the browser itself via the
    // granular micro-tools. The legacy coarse `browse_web` handoff is gone.
    // read_only (channels) still gets browser_act, but the dispatch blocks any
    // committing action — channels can fill/scroll/read, never click-submit.
    // ADR 0025 (slice 4b — converged): the MANAGER sees a single `browse(goal)` tool; the 6 granular
    // browser tools are driven ONLY inside the isolated browse sub-loop (they're seeded there directly),
    // never offered to the manager. The mid-turn model-switch + the granular-tools-on-the-manager path
    // are retired — one canonical browser path.
    let mut base_tools = initial_manager_tool_schemas_for_test(read_only, contact_only);
    if memory_recall_allowed {
        base_tools.push(recall_memory_tool_schema());
    }
    base_tools.extend([
        query_code_graph_tool_schema(),
        query_git_history_tool_schema(),
        github_search_tool_schema(),
        // Unified capability discovery — find what to connect (MCP/skill/Composio)
        // for a need. Read-only (search), so offered to channels too.
        suggest_capabilities_tool_schema(),
        // Deterministic date/time resolution (Layer C). Read-only and needed most
        // on channels (e.g. WhatsApp "treni per domani"), so offered to everyone.
        resolve_datetime_tool_schema(),
    ]);
    if !read_only {
        if host_computer_gateway::manager_ready() {
            base_tools.push(use_computer_tool_schema());
        }
        base_tools.push(create_artifact_tool_schema());
        base_tools.push(generate_image_tool_schema());
        base_tools.push(render_deck_tool_schema());
        base_tools.push(make_deck_tool_schema());
        base_tools.push(make_document_tool_schema());
        base_tools.push(get_brand_kit_tool_schema());
        base_tools.push(create_skill_tool_schema());
        base_tools.push(record_decision_tool_schema());
        base_tools.push(forget_memory_tool_schema());
        base_tools.push(update_plan_tool_schema());
        base_tools.push(step_advance_tool_schema());
        base_tools.push(schedule_task_tool_schema());
        base_tools.push(create_automation_tool_schema());
        base_tools.push(update_automation_tool_schema());
        base_tools.push(send_message_tool_schema());
        base_tools.push(list_scheduled_tasks_tool_schema());
        base_tools.push(cancel_scheduled_task_tool_schema());
        // Shell execution is a general capability (run scripts, process data, and
        // verify-by-execution: build/test/lint), not skill-only. The Docker
        // sandbox + security scan are the safety boundary, so it's safe to offer
        // whenever the turn can act (not read-only channels).
        base_tools.push(run_in_sandbox_tool_schema());
        // In-place file tools on the conversation's project folder (Claude-Code
        // style, path-jailed). No-op-with-explanation when no project folder.
        base_tools.push(read_file_tool_schema());
        base_tools.push(write_file_tool_schema());
        base_tools.push(edit_file_tool_schema());
        // Codex-format multi-file patch: preferred for precise / multi-file edits.
        // Jailed via jail_in_root, gated exactly like write_file/edit_file.
        base_tools.push(apply_patch_tool_schema());
        base_tools.push(list_files_tool_schema());
        // Native filesystem (browse/read the user's authorized folders), so this
        // fundamental capability isn't outsourced to a third-party MCP.
        base_tools.push(list_directory_tool_schema());
        base_tools.push(read_text_file_tool_schema());
        base_tools.push(run_in_project_tool_schema());
        // Addons (process-skills, ADR 0011) stay DORMANT until the post-release
        // addon phase: foundation wired but off by default (HOMUN_ADDONS=1).
        if addons_enabled() {
            base_tools.push(list_addons_tool_schema());
            base_tools.push(show_addon_tool_schema());
            base_tools.push(customize_addon_tool_schema());
        }
    }
    // NB: find_connected_tools is no longer offered separately — `find_capability` now
    // searches connectors too (unified discovery). The connectors still enter the corpus
    // below via `catalog_index` (gated by has_composio).
    if has_skills {
        base_tools.push(use_skill_tool_schema());
    }
    if !artifact_destinations.is_empty() && !read_only {
        base_tools.push(save_artifact_tool_schema(&artifact_destinations));
    }
    prune_tools_for_objective_policy(&mut base_tools, &objective_effect_policy, &composio_writes);
    prune_tools_for_route(&mut base_tools, &workflow_route, &workflow_deny_tools);
    // Tool Search (Anthropic pattern): split the full toolset into a SMALL always-loaded
    // CORE + a DEFERRED registry the model discovers via `find_capability`. Keeps the
    // upfront tool count low (selection accuracy + context budget) as tools grow, and makes
    // the browser a discovered last-resort instead of the silent catch-all. `find_capability`
    // pushes matches into the live `tool_schemas` (same mechanism as `find_connected_tools`).
    // One machine-derived exception (see `tool_stays_live_this_turn`): a thread with either a warm
    // browser session or an active revision-matched checkpoint is MID web task, so `browse` stays
    // live instead of requiring a discovery hop. This probe consumes neither state source.
    let browser_continuation_available = request
        .thread_id
        .as_deref()
        .is_some_and(|thread_id| thread_has_browser_continuation(state, thread_id));
    let (mut base_tools, deferred_tools): (Vec<serde_json::Value>, Vec<serde_json::Value>) =
        base_tools.into_iter().partition(|schema| {
            schema
                .pointer("/function/name")
                .and_then(|v| v.as_str())
                .map(|name| tool_stays_live_this_turn(name, browser_continuation_available))
                .unwrap_or(false)
        });
    match &capability_route {
        CapabilityRouteDecision::Workflow { tool_name, .. } => {
            if let Some(capability) = native_workflow_by_tool_name(tool_name) {
                base_tools.push((capability.schema)());
            }
        }
        CapabilityRouteDecision::AtomicTool { capability_key, .. } => {
            if let Some(capability) = native_atomic_by_key(capability_key) {
                base_tools.push((capability.schema)());
            }
            base_tools.push(find_capability_tool_schema());
        }
        CapabilityRouteDecision::AgentLoop { .. } => {
            base_tools.push(find_capability_tool_schema());
        }
    }
    // HITL Choice resume: strip cold discovery so the model cannot derail to
    // suggest_capabilities / CONNECT_SUGGEST. Warm state or a durable checkpoint keeps browse
    // live via tool_stays_live_this_turn; only a truly dead continuation permits rediscovery.
    if hitl_choice_resume.is_some() {
        let browser_continuation_available = request
            .thread_id
            .as_deref()
            .is_some_and(|tid| thread_has_browser_continuation(state, tid));
        hitl_resume::prune_cold_discovery_tools(&mut base_tools, !browser_continuation_available);
    }
    // MCP servers are installed deliberately and are few, so their tools go STRAIGHT
    // into the live tool set (not deferred behind find_capability) when the count is
    // small — the model uses them naturally instead of having to "discover" them via
    // a keyword search it rarely thinks to run. Past the cap they fall back to
    // find_capability like the large Composio catalog.
    const MCP_ALWAYS_LOAD_MAX: usize = 24;
    if !mcp_catalog.schemas.is_empty() && mcp_catalog.schemas.len() <= MCP_ALWAYS_LOAD_MAX {
        for schema in &mcp_catalog.schemas {
            base_tools.push(schema.clone());
        }
    }
    // Composio is the LARGE catalog (hundreds of tools) → kept behind find_capability,
    // but pre-retrieve the few relevant to THIS message and load them up front, so the
    // model uses them without having to think to search. Best-effort; deduped against
    // what's already loaded (core + always-loaded MCP).
    if has_composio && applies_new_input {
        let loaded: std::collections::HashSet<String> = base_tools
            .iter()
            .filter_map(|s| {
                s.pointer("/function/name")
                    .and_then(|v| v.as_str())
                    .map(String::from)
            })
            .collect();
        for schema in auto_retrieve_composio(&state.http, &request.prompt, &catalog_index, 4).await
        {
            let name = schema
                .pointer("/function/name")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string();
            if !name.is_empty() && !loaded.contains(&name) {
                base_tools.push(schema);
            }
        }
    }
    prune_tools_for_objective_policy(&mut base_tools, &objective_effect_policy, &composio_writes);
    prune_tools_for_route(&mut base_tools, &workflow_route, &workflow_deny_tools);
    let capability_corpus = materialize_capability_corpus(CapabilityCorpusMaterializationInput {
        deferred_tools,
        read_only,
        objective_effect_policy: &objective_effect_policy,
        composio_writes: &composio_writes,
        mcp_schemas: &mcp_catalog.schemas,
        enabled_skills: &enabled_skills,
    });
    // Connectors are NOT flattened into the BM25 corpus: they're searched via the
    // toolkit-aware `search_composio_catalog` inside find_capability (returns a service's
    // full CRUD set together, so the model picks the right verb). The hits are still
    // converted to typed `CapabilityEntry` values before being surfaced.
    // Attachments (persistent): ingest NEW files off-runtime, PERSIST them on the
    // thread, then load the thread's FULL set so a file stays usable across turns
    // (no re-attach). A manifest lists the available files so the model uses their
    // content instead of improvising (sandbox / list_directory / download links).
    let new_files = if !applies_new_input || request.attachments.is_empty() {
        Vec::new()
    } else {
        let atts = request.attachments.clone();
        tokio::task::spawn_blocking(move || attachments::ingest_each(&atts))
            .await
            .unwrap_or_default()
    };
    let mut working: Vec<chat_store::StoredAttachment> = Vec::new();
    if applies_new_input && let Some(thread_id) = request.thread_id.as_deref() {
        // Persist new files + load the whole thread set (sync DB work, no await
        // while the lock is held).
        if let Ok(store) = lock_store(state) {
            for file in &new_files {
                let _ = store.upsert_thread_attachment(
                    thread_id,
                    &file.display_name,
                    &file.mime_type,
                    file.text.as_deref(),
                    &file.images,
                );
            }
            working = store.thread_attachments(thread_id).unwrap_or_default();
        }
    }
    // Guarantee THIS turn's files are present even if persistence failed / no thread.
    for file in &new_files {
        if !working.iter().any(|w| w.display_name == file.display_name) {
            working.push(chat_store::StoredAttachment {
                display_name: file.display_name.clone(),
                mime_type: file.mime_type.clone(),
                text: file.text.clone(),
                images: file.images.clone(),
            });
        }
    }

    let mut model_text = prompt.clone();
    let mut all_images = if applies_new_input {
        request.images.clone()
    } else {
        Vec::new()
    };
    let new_attachment_context = new_files
        .iter()
        .map(|file| chat_store::StoredAttachment {
            display_name: file.display_name.clone(),
            mime_type: file.mime_type.clone(),
            text: file.text.clone(),
            images: file.images.clone(),
        })
        .collect::<Vec<_>>();
    let attachment_context = if !applies_new_input || request.checkpoint_input.is_some() {
        &new_attachment_context
    } else {
        &working
    };
    all_images.extend(append_thread_attachment_context(
        &mut model_text,
        attachment_context,
    ));

    // Vision: when the turn carries images (request + rendered attachments), the
    // user message becomes multimodal content (text + image_url parts) per the
    // OpenAI-compatible schema; otherwise it stays a plain string.
    let user_content = if all_images.is_empty() {
        serde_json::Value::String(model_text.clone())
    } else {
        let mut parts = vec![serde_json::json!({ "type": "text", "text": model_text })];
        for url in &all_images {
            parts.push(serde_json::json!({
                "type": "image_url",
                "image_url": { "url": url }
            }));
        }
        serde_json::Value::Array(parts)
    };
    // Built once here, then moved into `ls.messages` at the loop's start (the loop grows it).
    // `mut` because the vision policy below may swap the images out for a description (see
    // `vision::AttachmentPlan`) before the manager ever sees them.
    let mut messages = vec![
        serde_json::json!({ "role": "system", "content": system }),
        serde_json::json!({ "role": "user", "content": user_content }),
    ];

    let (mpsc_tx, rx) = tokio::sync::mpsc::channel::<Result<Bytes, std::io::Error>>(32);
    // Resume registry entry: the generation records here so a reloaded client can
    // reattach to the in-flight answer (GET /api/chat/stream_resume/{id}).
    let (broadcast_tx, _) = tokio::sync::broadcast::channel::<String>(512);
    let stream_entry = std::sync::Arc::new(StreamEntry {
        lines: std::sync::Mutex::new(Vec::new()),
        tx: broadcast_tx,
        finished: std::sync::atomic::AtomicBool::new(false),
        last_event_at: std::sync::atomic::AtomicU64::new(now_epoch_secs()),
        thread_id: request.thread_id.clone(),
        assistant_message_id: std::sync::Mutex::new(None),
        outcome: std::sync::Mutex::new(None),
        outcome_ready: tokio::sync::Notify::new(),
    });
    let resume_id = request.request_id.clone();
    if let Ok(mut map) = stream_registry().lock() {
        map.insert(resume_id.clone(), stream_entry.clone());
    }
    let tx = StreamSink {
        mpsc: mpsc_tx,
        entry: stream_entry,
    };
    let orchestrator_is_local = provider_endpoint_is_local(&base_url) && !model_id_is_cloud(&model);
    let privacy_prompt = if applies_new_input {
        request.prompt.as_str()
    } else {
        ""
    };
    let deterministic_privacy_decision =
        privacy_guard::classify_sensitive_input_deterministic(privacy_prompt);
    let guarded_decision = if applies_new_input {
        match classify_sensitive_input_with_privacy_guard_model(&state.http, privacy_prompt).await {
            privacy_guard::PrivacyGuardModelOutcome::Classified(model_decision) => {
                Ok(privacy_guard::merge_guard_decisions(
                    privacy_prompt,
                    model_decision,
                    deterministic_privacy_decision.clone(),
                ))
            }
            privacy_guard::PrivacyGuardModelOutcome::Unavailable(reason) => Err(reason),
            privacy_guard::PrivacyGuardModelOutcome::InvalidOutput => Err("invalid_output"),
        }
    } else {
        Ok(deterministic_privacy_decision.clone())
    };
    let privacy_decision = match guarded_decision {
        Ok(decision) => decision,
        Err(reason) => match privacy_guard::failure_policy(orchestrator_is_local) {
            privacy_guard::PrivacyGuardFailurePolicy::DeterministicLocalOnly => {
                tracing::warn!(
                    target: "privacy::guard",
                    %reason,
                    "privacy guard unavailable; using deterministic local-only fallback"
                );
                deterministic_privacy_decision
            }
            privacy_guard::PrivacyGuardFailurePolicy::BlockAndRetry => {
                tracing::warn!(
                    target: "privacy::guard",
                    %reason,
                    "privacy guard unavailable; blocking remote inference"
                );
                let _ = emit_stream_event(
                    &tx,
                    GenerateStreamEvent::Error {
                        code: "privacy_guard_unavailable".to_string(),
                        message: "Privacy Guard non disponibile. Riprova senza inviare dati al provider remoto.".to_string(),
                        retryable: true,
                    },
                )
                .await;
                schedule_stream_registry_cleanup(resume_id.clone());
                let body =
                    Body::from_stream(futures_util::stream::unfold(rx, |mut rx| async move {
                        rx.recv().await.map(|item| (item, rx))
                    }));
                return Ok(Response::builder()
                    .status(StatusCode::OK)
                    .header("content-type", "application/x-ndjson")
                    .header("x-effective-model", "privacy_guard")
                    .body(body)
                    .expect("valid streaming response"));
            }
        },
    };
    if let Some(intercept) = privacy_guard::build_privacy_guard_intercept(
        &state.pending_vault_proposals,
        &request.request_id,
        &privacy_decision,
    ) {
        // The two failure branches above log; the branch that actually REWRITES the user's message
        // did not — and that is the common one. A false positive (an ordinary path or word read as a
        // credential) therefore silently changed what the model was asked, with nothing in the log to
        // explain the odd answer. Categories/kinds only — never the matched value.
        tracing::warn!(
            target: "privacy::guard",
            detections = privacy_decision.items.len(),
            kinds = %privacy_decision
                .items
                .iter()
                .map(|item| format!("{}:{}", item.category, item.kind))
                .collect::<Vec<_>>()
                .join(","),
            "privacy guard intercepted the turn (user text rewritten)"
        );
        // Privacy Guard runs before the agent loop: the raw secret must not reach
        // the main chat model or the committed user transcript. The actual value
        // lives only in the pending sidecar until the user accepts with the PIN.
        let _ = emit_stream_event(
            &tx,
            GenerateStreamEvent::Done {
                text: intercept.assistant_text,
                metrics: TokenMetrics::zero(),
                redacted_user_text: Some(intercept.user_text),
            },
        )
        .await;
        schedule_stream_registry_cleanup(resume_id.clone());
        let body = Body::from_stream(futures_util::stream::unfold(rx, |mut rx| async move {
            rx.recv().await.map(|item| (item, rx))
        }));
        return Ok(Response::builder()
            .status(StatusCode::OK)
            .header("content-type", "application/x-ndjson")
            .header("x-effective-model", "privacy_guard")
            .body(body)
            .expect("valid streaming response"));
    }

    // Vision: this turn carries images, so decide WHO is allowed to look at them before the loop
    // starts — the manager itself, a vision model standing in for it, or nobody. The manager's model
    // never changes (ADR 0025 retired the mid-turn model switch); what changes is what reaches it.
    let vision_fallback_armed = if vision::messages_have_image(&messages) {
        match vision::plan_attachments(model_vision_support(&base_url, &model), has_vision_model())
        {
            // Known-blind manager and nobody to read for it. Say so — shipping the image to a provider
            // that will reject it, and calling the rejection an answer, is what we're here to stop.
            vision::AttachmentPlan::Refuse => {
                let _ = emit_stream_event(
                    &tx,
                    GenerateStreamEvent::Done {
                        text: vision::no_vision_model_message(&model),
                        metrics: TokenMetrics::zero(),
                        redacted_user_text: None,
                    },
                )
                .await;
                schedule_stream_registry_cleanup(resume_id.clone());
                let body =
                    Body::from_stream(futures_util::stream::unfold(rx, |mut rx| async move {
                        rx.recv().await.map(|item| (item, rx))
                    }));
                return Ok(Response::builder()
                    .status(StatusCode::OK)
                    .header("content-type", "application/x-ndjson")
                    .header("x-effective-model", "vision")
                    .body(body)
                    .expect("valid streaming response"));
            }
            // Known-blind manager, but a vision model can stand in: it looks at the image and its
            // description takes the image's place. Same message, same position — only the modality
            // changed, and the manager keeps its own model, tools and context.
            vision::AttachmentPlan::Delegate => {
                let readers = vision_model_candidates();
                let images = vision::collect_image_urls(&messages);
                let descriptions =
                    vision::describe_images(&state.http, &readers, &images, &prompt).await;
                vision::replace_images_with_descriptions(&mut messages, &descriptions);
                false
            }
            // Sent inline, as before. The difference is only whether a vision model exists to rescue
            // the turn should the provider refuse the image anyway (see `run_agent_rounds`).
            vision::AttachmentPlan::InlineWithFallback => true,
            vision::AttachmentPlan::Inline => false,
        }
    } else {
        false
    };

    // Dedicated STREAMING client: HTTP/1.1 (avoids HTTP/2 RST_STREAM that CDNs in
    // front of cloud model hosts can throw on long streams) + no idle connection
    // reuse (a stale pooled keep-alive connection is a classic cause of the
    // intermittent "error decoding response body" mid/early stream). Falls back to the
    // shared pooled client if the builder fails.
    let http = reqwest::Client::builder()
        .http1_only()
        .pool_max_idle_per_host(0)
        .build()
        .unwrap_or_else(|_| state.http.clone());
    let state_owned = state.clone();
    let temperature = request.temperature;
    let execution_journal = agent_journal::for_run(request.agent_run_id.as_deref());
    let effect_run_id = request.agent_run_id.clone();
    let effect_turn_id = request.agent_run_id.as_ref().and_then(|_| {
        request
            .request_id
            .strip_prefix("broker-")
            .map(str::to_string)
    });
    // Thread this chat belongs to: lets browser work reuse a persistent
    // per-thread browser session (search → then book on the same tab).
    let thread_id = request.thread_id.clone();
    let automation_user_id = gateway_user_id();
    let automation_workspace_id = thread_id
        .as_deref()
        .and_then(|tid| {
            lock_store(state)
                .ok()
                .and_then(|store| store.workspace_for_thread(tid).ok())
        })
        .map(WorkspaceId::new)
        .unwrap_or_else(gateway_workspace_id);
    // Raw user message captured for post-turn memory extraction (M2).
    let memory_user_message = if applies_new_input {
        request.prompt.clone()
    } else {
        String::new()
    };
    // The assistant's most recent prior turn (the question a short "sì" would answer),
    // so the extractor can ground a confirmation into the fact it commits.
    let memory_prev_assistant = effective_context
        .iter()
        .rev()
        .find(|m| matches!(m.role, ChatContextRole::Assistant))
        .map(|m| m.text.clone());
    // F4: resume an interrupted long task on the CANONICAL plan so the turn continues on
    // the same authoritative state (done steps stay done) instead of RESTARTING. Prefer the
    // durable per-thread runtime-plan store (upserted on every plan call, survives even when
    // the prior turn hasn't yet persisted its ‹‹PLAN›› marker into this turn's context) —
    // reading only the context marker made a continuation turn resume 0 steps and revert
    // done→doing (the "il piano riparta" symptom). Fall back to the context marker for a
    // thread-less turn or a store miss.
    let (mut resume_plan, resume_goal): (Vec<serde_json::Value>, Option<String>) = {
        let from_store = runtime_plan_record_from_state(state, thread_id.as_deref());
        if let Some((goal, steps)) = from_store
            && !steps.is_empty()
        {
            (steps, goal)
        } else {
            // A marker-resumed plan carries no goal line (it was never part of the checklist
            // grammar) — without a durable goal the canonical plan starts goal-less.
            let steps = effective_context
                .iter()
                .rev()
                .find(|m| m.text.contains("‹‹PLAN››"))
                .map(|m| parse_plan_marker(&m.text))
                .unwrap_or_default();
            (steps, None)
        }
    };
    // F4: a RESUMED plan that closes no new step across turns is stuck (the per-turn recovery
    // counters reset each turn, so the same failing step retries forever). After the cap the
    // harness BLOCKS the stuck step (caposaldo #2) — `block_stalled_step` makes the plan
    // `settled`, so `upsert_runtime_plan_memory` stops it auto-resuming. Gated until validated
    // live; the bookkeeping is a no-op when off.
    if applies_new_input && !resume_plan.is_empty() && plan_stall_abort_enabled() {
        let stalled = runtime_plan_control_scope(state, thread_id.as_deref()).is_some_and(
            |(user_id, workspace_id, thread_id)| {
                plan_stall_check_and_bump(
                    state.task_store.as_ref(),
                    &user_id,
                    &workspace_id,
                    &thread_id,
                    &resume_plan,
                )
            },
        );
        if stalled && let Some(title) = block_stalled_step(&mut resume_plan) {
            upsert_runtime_plan_memory_from_state(
                state,
                thread_id.as_deref(),
                resume_goal.as_deref(),
                &resume_plan,
            );
            if verbose_debug() {
                eprintln!(
                    "[plan] F4: blocked stalled step after {MAX_PLAN_STALL_RESUMES} no-progress resumes: «{title}»"
                );
            }
        }
    }
    let capability_route_for_runtime = capability_route.clone();
    let abort_resume_id = resume_id.clone();
    let engine_task = tokio::spawn(async move {
        let mut ls = local_first_engine::LoopState::new();
        ls.prompt_packets = prompt_packets;
        ls.messages = messages;
        if applies_new_input {
            seed_loop_memory_reads(&mut ls, automatic_recall_payload.as_ref());
        }
        // RAG completed before the loop starts. Publish the exact selected hits before any
        // narration delta so a resumed client and the persisted assistant message agree on
        // which memory sources informed this turn.
        if applies_new_input && let Some(payload) = automatic_recall_payload {
            let _ = emit_stream_event(&tx, GenerateStreamEvent::Recall { payload }).await;
        }
        // Phase 3 (per-project skill confirmations): seed the turn's force-confirm set with the
        // workspace's configured categories so an effectful action is gated even with NO
        // sensitive skill loaded. Fail-safe — this only ADDS to `active_sensitive`; the loop
        // later unions per-skill categories via `ToolEffects::arm_sensitive`. `merged_sensitive`
        // dedups the (empty-at-init) skill set with the project set.
        {
            let existing: Vec<crate::skills::SensitiveCategory> = ls
                .active_sensitive
                .iter()
                .filter_map(|t| crate::skills::SensitiveCategory::parse(t))
                .collect();
            let project_sensitive =
                resolved_skill_confirmations(&state_owned, thread_id.as_deref());
            ls.active_sensitive = merged_sensitive(&existing, &project_sensitive)
                .iter()
                .map(|cat| cat.as_token().to_string())
                .collect();
        }
        // Last upstream model error this turn (e.g. a 410 "model retired"), already
        // human-readable. Surfaced as the final answer if the turn produces no text,
        // so a dead/blocked model is obvious instead of a generic "no answer".
        let last_model_error: Option<String> = None;
        // Final answer text captured for post-turn memory extraction (M2).
        let memory_answer = String::new();
        // Consequential actions performed this turn (any domain) → fed to the
        // memory extractor so the "why" of each mutation is remembered.
        if let Some(route_line) = capability_route_trace_line(&capability_route_for_runtime) {
            ls.tool_trace.push(route_line.clone());
            let _ = emit_stream_event(
                &tx,
                GenerateStreamEvent::Delta {
                    text: format!("‹‹ACT››🧭 {route_line}‹‹/ACT››"),
                },
            )
            .await;
        }
        // No-progress guard: if the model repeats the EXACT same tool calls round after
        // round, it's stuck (not making progress) → stop and synthesize, instead of
        // burning the whole round budget on a loop. This is what lets the budget be
        // generous: real long tasks run, loops are caught fast.
        let final_done = false;
        // Long-horizon execution (F1): the round budget is measured from the LAST
        // verified progress, not from round 0. Whenever a canonical plan step becomes
        // `done` (verified), we move the anchor to the current round and reset the
        // no-progress guard — so a big plan-driven task (10 slides, a long web research)
        // keeps going for as long as it KEEPS CLOSING STEPS, while a turn stuck on one
        // step still trips the per-step budget.
        // CANONICAL PLAN: the single source of truth for the task's steps + their status,
        // owned by the runtime (not rebuilt from the model's text each call). update_plan
        // MERGES into this by id/title and can never reset a done step; F1 budget reset,
        // F2 verification, F5 next-step and the ‹‹PLAN›› marker all read THIS. Seeded from
        // the prior conversation (F4 resume). A step is `done` only after F2 verified it.
        // P5: carried as an opaque `Value` in `LoopState` (engine-safe); seeded here from the resume.
        ls.plan = canonical_plan_value(resume_goal.as_deref(), &resume_plan);
        if verbose_debug() {
            let done = resume_plan
                .iter()
                .filter(|s| s.get("status").and_then(|v| v.as_str()) == Some("done"))
                .count();
            eprintln!(
                "[plan] turn-start: resumed {} steps ({done} done) from prior ‹‹PLAN›› marker",
                resume_plan.len()
            );
        }

        // F2 verification gate: the running evidence (tool name → result snippet) for the
        // CURRENT plan step, fed to the verifier when the model marks the step done, then
        // cleared. A chat model can claim "done" without doing the work; the gate checks.
        // F3 context compaction: `ls.step_messages_start` is the index in `ls.messages` where the
        // current step's work begins; once the step is verified, that slice is summarised
        // into one note so a long multi-step turn stays within the context window.
        // `ls.pending_compaction` defers the rewrite to the next round's safe boundary (never
        // mid tool-call/result group, which would break OpenAI-compat pairing).
        // Set right before the round loop (once the initial context is fully in
        // `ls.messages`) so compaction never folds the system/user context into a summary.
        // Plan-completion enforcement: counts consecutive turns where the model STOPPED
        // (no tool call) while its plan still has open steps. Reset on any tool call.
        let plan_nudges: u32 = 0;
        // Slice 2.5: did the model actually ACT (use a tool) this turn? Used at the no-tool
        // stop to tell a PREMATURE stop on a real task (judge it, bootstrap a plan) apart from
        // a plain conversational answer (let it end). Latches true once any tool has run.
        let turn_used_tools = false;
        // Source URLs visited via browse_web this request, for the "Fonti" footer.
        let browse_sources: Vec<String> = Vec::new();
        // Tools offered to the model this run: the base set, plus any tools the
        // model discovers via `find_connected_tools` (injected on demand).
        ls.tool_schemas = base_tools;
        // "Chiedi" mode: pure conversation — no tools, no actions.
        if mode == "ask" {
            ls.tool_schemas.clear();
        }
        // Contact perimeter tool filter (channel turns): denied wins, then the
        // allowlist (if non-empty) narrows further. Substring match on the function
        // name, composed ON TOP of the channel read-only policy.
        if let Some(cx) = &contact_ctx {
            let denied = &cx.perimeter.tools_denied;
            let allowed = &cx.perimeter.tools_allowed;
            if !denied.is_empty() || !allowed.is_empty() {
                let mut dropped: Vec<String> = Vec::new();
                ls.tool_schemas.retain(|schema| {
                    let name = schema
                        .pointer("/function/name")
                        .and_then(|v| v.as_str())
                        .unwrap_or("");
                    if denied.iter().any(|d| name.contains(d.as_str())) {
                        dropped.push(name.to_string());
                        return false;
                    }
                    // An allowlist narrows CAPABILITIES, not the loop's own machinery. Applied to
                    // everything, a perimeter allowing only e.g. "calendar" also deleted update_plan,
                    // step_advance, find_capability and recall_memory — so the turn lost the ability to
                    // plan, to discover what it may use, and to read memory, for a reason that has
                    // nothing to do with the contact's perimeter. Harness tools stay unless explicitly
                    // denied above.
                    if !allowed.is_empty()
                        && !HARNESS_CONTROL_TOOLS.contains(&name)
                        && !allowed.iter().any(|a| name.contains(a.as_str()))
                    {
                        dropped.push(name.to_string());
                        return false;
                    }
                    true
                });
                if !dropped.is_empty() {
                    // Was entirely silent: a turn could lose tools with nothing to explain why the
                    // model then said it could not do something it normally can.
                    tracing::warn!(
                        target: "perimeter::tools",
                        dropped = %dropped.join(","),
                        "contact perimeter withheld tools from this turn"
                    );
                }
            }
        }
        // Turn-local browser state now lives in the browser subsystem: the loop-visible fields
        // (browser_used / pending_browser_image / browser_tool_call_ids) travel in `LoopState`
        // (slice 5a), and the browser-private state (sidecar session, last snapshot, current tab /
        // opened targets, per-URL nav failures) is OWNED by `GatewayBrowserExecutor`, constructed
        // inside `run_agent_rounds` (slice 5b). Nothing to seed here.
        // Fresh terminal buffer for this request; the computer panel shows the
        // CLI commands + output run during THIS response.
        sandbox_clear(thread_id.clone());

        // F3: the first plan step's work begins after the initial context is in place.
        ls.step_messages_start = ls.messages.len();

        // F0 / model-io: detect+cache this Ollama model's capability profile (thinking, tools,
        // vision, context window) via one /api/show, so the harness can ADAPT — send `think`
        // only to thinking models, and (future) gate tools/images and budget on the real
        // context. The thinking gate in `build_chat_payload` reads this cache.
        if is_ollama_base(&base_url) {
            warm_ollama_capabilities(&http, &base_url, &model).await;
        }

        // The concrete model seam (ADR 0024): borrows the turn's client + sink for the loop.
        // The outer ceiling is the BROWSER budget; the EFFECTIVE budget is dynamic
        // (the normal 5 rounds until a browser tool is actually used, then the
        // larger browser budget). This keeps non-browser turns identical to today.
        // ADR 0026: provider binding travels with LoopState (per-round swap), not as separate args.
        ls.provider = local_first_engine::ProviderBinding {
            model,
            base_url,
            api_key,
        };
        let checkpoint_input = request
            .checkpoint_input
            .as_ref()
            .and_then(|_| ls.messages.last().cloned());
        apply_agent_recovery_checkpoint(&mut ls, recovery_checkpoint, checkpoint_input);
        // 5.D1c.1: resolve the loop's turn-constant config ONCE (env-stable for the turn) so the moved
        // loop never reads env. Behavior-preserving — same values the inline getters returned.
        let cfg = local_first_engine::TurnConfig {
            hard_round_ceiling: hard_round_ceiling(),
            max_rounds: chat_max_rounds(),
            browser_max_rounds: chat_browser_max_rounds(),
            browser_nav_cap: chat_browser_nav_cap(),
            // The MANAGER budget, not the shared one: its absolute wall clock must outlive the
            // `browse` sub-turns it delegates (see `manager_browser_max_elapsed_ms`), otherwise a
            // multi-phase task — search → choose → book, one browse per phase — is cut mid-flight
            // while every single delegation succeeded.
            browser_budget: chat_manager_browser_budget(),
            // Fase 1.1: the model's real context window (catalog `context_window`, resolved above)
            // drives token-budget auto-compaction. `None` → fail-open (no budget compaction).
            context_window: model_context_window,
            reconcile_on_delivery: plan_reconcile_on_delivery_enabled(),
            autoadvance_from_evidence: plan_autoadvance_from_evidence_enabled(),
            step_verification: step_verification_enabled(),
            verbose: verbose_debug(),
            // S2 T5: resolved above from (routing_binding, Forcing::Specific, turn-index).
            forced_tool: forced_tool.clone(),
            // E2: this is the manager (chat) turn, NOT the browse sub-turn. Its browser tool set
            // (`browser_registry_cached_tools`) deliberately excludes `browser_done` — reaching this
            // turn's dispatcher is a hallucination — so the terminal must stay disarmed here.
            browser_subturn: false,
            resolved_hitl: hitl_choice_resume.as_ref().map(|ctx| {
                local_first_engine::hitl::ResolvedHitlGuard {
                    envelope: local_first_engine::hitl::HitlEnvelope {
                        kind: match ctx.wait.kind {
                            hitl_resume::HitlWaitKind::Choice => {
                                local_first_engine::hitl::HitlKind::Choice
                            }
                            hitl_resume::HitlWaitKind::Clarify => {
                                local_first_engine::hitl::HitlKind::Clarify
                            }
                        },
                        hold_policy: local_first_engine::hitl::HoldPolicy::Free,
                        payload: ctx.wait.payload.clone(),
                        source_marker: "durable_resume".to_string(),
                    },
                    resolution: ctx.resolution.clone(),
                }
            }),
        };
        // 5.D1c.8: the post-turn tail (memory learn + code-graph refresh) is a GATEWAY concern, so it
        // runs HERE after the engine turn returns. Snapshot what it needs before the turn consumes the
        // owned values (AppState is a cheap Arc clone; the strings are small).
        let tail_state = state_owned.clone();
        let tail_user = memory_user_message.clone();
        let tail_thread = thread_id.clone();
        let tail_turn_id = request.request_id.clone();
        // Snapshots for the end-of-turn steering fence below: the originals are moved into
        // `run_agent_rounds` (and `tail_turn_id` into the memory-learn spawn).
        let fence_turn_id = request.request_id.clone();
        let fence_user_id = automation_user_id.clone();
        let fence_workspace_id = automation_workspace_id.clone();
        let canonical_broker_turn = effect_turn_id.is_some();
        // 5.D1c.9: resolve the trace-dump dir gateway-side (armed only when HOMUN_TRACE_DUMP=1) and
        // inject it, so the engine loop appends without calling the gateway's path resolver.
        let trace_dir = local_first_engine::trace::dump_enabled()
            .then(gateway_logs_dir)
            .and_then(Result::ok);
        let outcome = run_agent_rounds(
            ls,
            &tx,
            http,
            state_owned,
            temperature,
            prompt,
            thread_id,
            read_only,
            autonomous,
            channel_owner,
            contact_only,
            can_see_contacts,
            can_see_calendar,
            can_use_project_memory,
            memory_recall_allowed,
            memory_intent.vault_value_requested,
            memory_user_message,
            memory_answer,
            last_model_error,
            final_done,
            plan_nudges,
            turn_used_tools,
            composio_writes,
            catalog_index,
            capability_corpus,
            capability_route_for_runtime,
            automation_user_id,
            automation_workspace_id,
            browse_sources,
            cfg,
            trace_dir,
            execution_journal,
            effect_turn_id,
            effect_run_id,
            &turn_trace,
            vision_fallback_armed,
        )
        .await;
        if !canonical_broker_turn
            && let (Some(thread_id), Some(assistant_message_id)) = (
                tail_thread.as_deref(),
                tx.entry
                    .assistant_message_id
                    .lock()
                    .ok()
                    .and_then(|id| id.clone()),
            )
            && let Err(error) = persist_hitl_wait_from_outcome(
                &tail_state,
                thread_id,
                &assistant_message_id,
                &outcome,
            )
        {
            eprintln!("[hitl] legacy turn projection failed: {error}");
        }
        // Turn trace: the final record. `outcome.memory_answer` is the committed answer; `final_plan` is
        // the turn's last runtime plan (carried out for exactly this). The derived flags (incomplete
        // steps, artifact claimed-but-absent) are the high-value signal. Observability only.
        {
            let final_steps = plan_value_steps(&outcome.final_plan);
            let plan_final: Vec<String> = final_steps
                .iter()
                .map(|s| plan_step_status(s).to_string())
                .collect();
            let plan_titles: Vec<String> = final_steps
                .iter()
                .map(|s| plan_step_title(s).to_string())
                .collect();
            let artifact_count = outcome.memory_answer.matches("‹‹ARTIFACT››").count();
            let signals = local_first_engine::turn_trace::answer_signals(
                &outcome.memory_answer,
                artifact_count,
            );
            let derived =
                local_first_engine::turn_trace::derive_flags(&plan_final, &plan_titles, &signals);
            turn_trace.record(local_first_engine::turn_trace::TurnEvent::TurnEnd {
                final_len: outcome.memory_answer.chars().count(),
                plan_final,
                signals,
                derived,
            });
        }
        // M2: mine this exchange for durable personal memory (fire-and-forget, off the response path).
        // Best-effort; never blocks or fails the turn. Skip for channel turns (read_only): the inbound
        // is from a CONTACT, not the user, and the channel handler runs its own speaker-attributed learn
        // — this one (speaker=None) would mis-attribute the contact's facts to person:self.
        if applies_new_input && !outcome.memory_answer.trim().is_empty() && !read_only {
            let learn_state = tail_state.clone();
            let learn_user = tail_user;
            let learn_answer = outcome.memory_answer.clone();
            let learn_thread = tail_thread.clone();
            let learn_actions = outcome.tool_actions.clone();
            let learn_prev = memory_prev_assistant.clone();
            let learn_envelope = memory_reuse_envelope_from_read_set(&outcome.memory_reads);
            tokio::spawn(async move {
                learn_via_service_or_inline(
                    &learn_state,
                    &learn_user,
                    &learn_answer,
                    &learn_actions,
                    learn_thread.as_deref(),
                    Some(&tail_turn_id),
                    None,
                    learn_prev.as_deref(),
                    learn_envelope,
                )
                .await;
            });
        }
        // Keep the code map FRESH on every turn in a mapped project — driven by GIT, not by who edited:
        // spawn_project_graph_refresh re-extracts only if the git fingerprint changed since the last
        // build, so it catches the AGENT's writes AND the user's own editor edits (and checkout/pull),
        // while being a cheap no-op when nothing changed. Only refreshes already-mapped projects.
        if !read_only
            && let Some(ws) = tail_thread
                .as_deref()
                .and_then(|tid| {
                    lock_store(&tail_state)
                        .ok()
                        .and_then(|s| s.workspace_for_thread(tid).ok())
                })
                .filter(|w| !w.trim().is_empty())
        {
            spawn_project_graph_refresh(&tail_state, &ws);
        }
        // INVARIANT — nothing transient outlives its turn. This runs on EVERY exit of the turn task
        // (delivered, parked, error, abort), because the failure it prevents is not tied to any one
        // outcome: a steering row still `pending` when its turn ends can never be applied (the turn it
        // targeted is gone), but the next turn's finalization fence still sees PendingInput, waits its
        // budget and PARKS — so one uninterpretable instruction silently broke every following turn in
        // the thread. Resources with their own lifetime (the thread's warm browser session, reused for
        // "search → then book") are deliberately NOT touched here; they are owned per thread and reaped
        // on idle/close.
        finalize_turn_steering(
            &tail_state,
            tail_thread.as_deref(),
            &fence_turn_id,
            &fence_user_id,
            &fence_workspace_id,
        );
        publish_stream_outcome(&tx.entry, outcome);
        // Mark the resume entry finished and evict it after a grace window so a
        // client that reloaded right at the end can still reattach and read it.
        tx.entry
            .finished
            .store(true, std::sync::atomic::Ordering::Relaxed);
        schedule_stream_registry_cleanup(resume_id.clone());
    });
    if let Ok(mut map) = stream_abort_registry().lock() {
        map.insert(abort_resume_id, engine_task.abort_handle());
    }

    let body = Body::from_stream(futures_util::stream::unfold(rx, |mut rx| async move {
        rx.recv().await.map(|item| (item, rx))
    }));
    Ok(Response::builder()
        .status(StatusCode::OK)
        .header("content-type", "application/x-ndjson")
        .body(body)
        .expect("valid streaming response"))
}

fn apply_agent_recovery_checkpoint(
    state: &mut local_first_engine::LoopState,
    checkpoint: Option<local_first_engine::LoopCheckpoint>,
    new_input: Option<serde_json::Value>,
) {
    if let Some(checkpoint) = checkpoint {
        checkpoint.apply_to(state);
        if let Some(new_input) = new_input {
            state.messages.push(new_input);
        }
    }
}

/// Build the terminal outcome for an image rejection that has already been surfaced with `Done`.
/// Keeping this pure makes the stream event and outcome delivery state move together.
fn delivered_image_rejection_outcome(
    mut outcome: local_first_engine::TurnOutcome,
    rejection: String,
) -> local_first_engine::TurnOutcome {
    outcome.memory_answer = rejection;
    outcome.stop = local_first_engine::TurnStop::Completed;
    outcome
}

// ADR 0024 inc 5 (5.D1a): the agent turn's round loop + forced synthesis + post-turn
// learn, extracted VERBATIM from the tokio::spawn body of stream_chat_via_openai. The
// signature (the captured turn state) is what becomes engine::run_turn's interface at 5.D1c.
#[allow(clippy::too_many_arguments)]
async fn run_agent_rounds(
    ls: local_first_engine::LoopState,
    tx: &StreamSink,
    http: reqwest::Client,
    state_owned: AppState,
    temperature: f64,
    prompt: String,
    thread_id: Option<String>,
    read_only: bool,
    autonomous: bool,
    channel_owner: bool,
    contact_only: bool,
    can_see_contacts: bool,
    can_see_calendar: bool,
    can_use_project_memory: bool,
    memory_recall_allowed: bool,
    vault_value_requested: bool,
    memory_user_message: String,
    memory_answer: String,
    last_model_error: Option<String>,
    final_done: bool,
    plan_nudges: u32,
    turn_used_tools: bool,
    composio_writes: std::collections::BTreeSet<String>,
    catalog_index: Vec<(String, String, serde_json::Value)>,
    capability_corpus: Vec<CapabilityEntry>,
    capability_route_for_runtime: CapabilityRouteDecision,
    automation_user_id: UserId,
    automation_workspace_id: WorkspaceId,
    browse_sources: Vec<String>,
    cfg: local_first_engine::TurnConfig,
    // 5.D1c.9: the armed trace-dump dir (gateway-resolved `~/.homun/logs`), or None when the dump is
    // disarmed / the dir won't resolve. The engine appends here instead of calling `gateway_logs_dir`.
    trace_dir: Option<std::path::PathBuf>,
    execution_journal: agent_journal::GatewayJournal,
    effect_turn_id: Option<String>,
    effect_run_id: Option<String>,
    // Readable per-turn observability sink (ported): passed into the capability executor (Plan event)
    // and into `run_turn` (the in-loop events). No-op when disabled. See `engine::turn_trace`.
    turn_trace: &local_first_engine::turn_trace::TurnTrace,
    // The turn is sending images to a model on a guess (`AttachmentPlan::InlineWithFallback`), and a
    // vision model exists to describe them if the provider refuses. Passed rather than re-derived here:
    // the policy is decided ONCE, in `vision::plan_attachments`, and this is its consequence.
    vision_fallback_armed: bool,
) -> local_first_engine::TurnOutcome {
    // Build the seams `engine::run_turn` runs against — thin gateway adapters over AppState/transport/
    // stores, constructed ONCE per turn from this turn's context (ADR 0024/0026). model_client borrows
    // http+tx locally; the tool chokepoints hold the turn-constant read-only context and get `&mut ls`
    // per call from the engine.
    let steering_context = match (thread_id.as_deref(), effect_turn_id.as_deref()) {
        (Some(thread_id), Some(turn_id)) => Some(crate::model_client::GatewaySteeringContext {
            state: &state_owned,
            user_id: automation_user_id.as_str(),
            workspace_id: automation_workspace_id.as_str(),
            thread_id,
            turn_id,
            run_id: effect_run_id.as_deref().unwrap_or(turn_id),
        }),
        _ => None,
    };
    let model_client = crate::model_client::GatewayModelClient {
        http: &http,
        tx,
        usage: state_owned.usage_recorder.as_ref(),
        steering: steering_context,
    };
    let mut usage_context = local_first_inference_usage::UsageContext::new(
        uuid::Uuid::new_v4().to_string(),
        local_first_inference_usage::InferencePurpose::ChatResponse,
        automation_user_id.as_str(),
    );
    usage_context.workspace_id = Some(automation_workspace_id.as_str().to_string());
    usage_context.thread_id = thread_id.clone();
    usage_context.turn_id = effect_turn_id.clone();
    usage_context.run_id = effect_run_id.clone();
    let effect_contract = effect_turn_id.as_deref().and_then(|execution_id| {
        state_owned
            .task_store
            .lock()
            .ok()?
            .execution(execution_id)
            .ok()
            .flatten()
            .map(|record| record.contract)
    });
    let capability_executor = GatewayCapabilityExecutor {
        state: &state_owned,
        tx,
        thread_id: thread_id.as_deref(),
        read_only,
        contact_only,
        can_see_contacts,
        can_see_calendar,
        can_use_project_memory,
        memory_recall_allowed,
        vault_value_requested,
        autonomous,
        composio_writes: &composio_writes,
        catalog_index: &catalog_index,
        capability_corpus: &capability_corpus,
        automation_user_id: &automation_user_id,
        automation_workspace_id: &automation_workspace_id,
        // ADR 0025: turn-constants for a recursive `browse(goal)` sub-turn (used only when the manager
        // calls the `browse` tool; inert otherwise).
        prompt: &prompt,
        channel_owner,
        turn_trace,
        turn_id: effect_turn_id.as_deref(),
        run_id: effect_run_id.as_deref(),
        execution_contract: effect_contract.as_ref(),
    };
    // The browser tool chokepoint (ADR 0025 seam): OWNS the browser subsystem's private state (session +
    // snapshot/tab/nav bookkeeping); `&mut` because run_turn mutates it per browser call.
    let mut browser_executor = GatewayBrowserExecutor {
        browser_session: None,
        last_snapshot: String::new(),
        browse_sources: Vec::new(),
        last_payment_floor_refs: std::collections::HashMap::new(),
        payment_context_by_target: std::collections::HashMap::new(),
        result_contract: None,
        current_target: "chat_0".to_string(), // the first tab the tools operate on
        opened_targets: Vec::new(),
        nav_failures: std::collections::HashMap::new(),
        state: &state_owned,
        tx,
        thread_id: thread_id.as_deref(),
        prompt: &prompt,
        read_only,
        channel_owner,
        // C2: the manager turn's own registered journal — same handle `run_turn` below receives via
        // `&execution_journal`, so protocol metrics from a manager-level browser call land in the same
        // run as everything else this turn records.
        journal: execution_journal.clone(),
        execution_contract: effect_contract.clone(),
        effect_run_id: effect_run_id.clone(),
        turn_id: effect_turn_id.clone(),
        step_memory: None,
        auto_screenshot: false,
        screenshot_on_stall: false,
        consecutive_snapshot_count: 0,
        recent_action_signatures: std::collections::VecDeque::new(),
        recent_failed_action_families: std::collections::VecDeque::new(),
    };
    let plan_progress = GatewayPlanProgress {
        state: state_owned.clone(),
    };
    let compactor = GatewayContextCompactor {
        state: state_owned.clone(),
        thread_id: thread_id.clone(),
    };
    let turn_policy = GatewayTurnPolicy {
        route: capability_route_for_runtime,
        workflow_tool_calls: std::sync::atomic::AtomicUsize::new(0),
    };
    let completion_judge = GatewayTurnCompletionJudge {
        state: state_owned.clone(),
    };

    // Vision fallback (`AttachmentPlan::InlineWithFallback`): this turn's images ride the manager's
    // first call on nothing better than a catalog's opinion. Keep the turn's PRISTINE seed so we can
    // replay it: a provider that refuses to look at the images kills the turn before it has streamed a
    // token or run a tool (`TurnOutcome::image_rejection` — see the engine's early return), so we can
    // describe them on the vision role and re-run from a conversation the manager can actually read.
    // The user gets one answer, not a 400 followed by an apology. Cloning the seed is cheap (2
    // messages) and happens only for image turns that have a vision model to fall back on.
    let vision_seed = vision_fallback_armed.then(|| {
        (
            ls.clone(),
            cfg.clone(),
            memory_user_message.clone(),
            memory_answer.clone(),
            last_model_error.clone(),
            browse_sources.clone(),
            trace_dir.clone(),
        )
    });

    // ADR 0024 inc 5, 5.D2 — THE MOVE landed: the single guarded ReAct loop (motore #1) lives in
    // `engine::run_turn`. The gateway builds the seams above and invokes the ONE canonical loop — no
    // flag, no inline copy (converge, don't duplicate). ADR 0025 (browse-as-recursion) invokes this
    // same `run_turn` recursively for the browser.
    let outcome = local_first_engine::agent_loop::run_turn(
        ls,
        cfg,
        &usage_context,
        &model_client,
        &capability_executor,
        &mut browser_executor,
        &plan_progress,
        &completion_judge,
        &compactor,
        &turn_policy,
        &execution_journal,
        tx,
        temperature,
        thread_id.as_deref(),
        &composio_writes,
        &catalog_index,
        memory_user_message,
        memory_answer,
        last_model_error,
        final_done,
        plan_nudges,
        turn_used_tools,
        browse_sources,
        trace_dir,
        turn_trace,
    )
    .await;

    // A model suspension is a typed engine stop. The broker drain observes it
    // through the stream entry's outcome channel; no fabricated `done` event and
    // no task-state mutation are needed to unblock transport.
    if matches!(
        outcome.stop,
        local_first_engine::TurnStop::SuspendedModel { .. }
            | local_first_engine::TurnStop::SuspendedEffect { .. }
    ) {
        return outcome;
    }

    // The common case: the turn ran (whatever it concluded).
    let Some(rejection) = outcome.image_rejection.clone() else {
        return outcome;
    };

    let Some((
        mut seed_ls,
        seed_cfg,
        seed_user_msg,
        seed_answer,
        seed_error,
        seed_sources,
        seed_trace,
    )) = vision_seed
    else {
        // The model can't read the image and we have nobody to read it for us. The turn emitted
        // nothing, so this is its answer — the one case where the provider's refusal is the honest
        // thing to show.
        let _ = emit_stream_event(
            tx,
            GenerateStreamEvent::Done {
                text: rejection.clone(),
                metrics: TokenMetrics::zero(),
                redacted_user_text: None,
            },
        )
        .await;
        return delivered_image_rejection_outcome(outcome, rejection);
    };

    let readers = vision_model_candidates();
    if readers.is_empty() {
        // Armed at seed time but gone now (the role was cleared mid-turn) — same dead end.
        let _ = emit_stream_event(
            tx,
            GenerateStreamEvent::Done {
                text: rejection.clone(),
                metrics: TokenMetrics::zero(),
                redacted_user_text: None,
            },
        )
        .await;
        return delivered_image_rejection_outcome(outcome, rejection);
    }

    // Recover: describe the images the manager was refused, put the text where they were, run again.
    let images = vision::collect_image_urls(&seed_ls.messages);
    let descriptions = vision::describe_images(&http, &readers, &images, &prompt).await;
    vision::replace_images_with_descriptions(&mut seed_ls.messages, &descriptions);

    local_first_engine::agent_loop::run_turn(
        seed_ls,
        seed_cfg,
        &usage_context,
        &model_client,
        &capability_executor,
        &mut browser_executor,
        &plan_progress,
        &completion_judge,
        &compactor,
        &turn_policy,
        &execution_journal,
        tx,
        temperature,
        thread_id.as_deref(),
        &composio_writes,
        &catalog_index,
        seed_user_msg,
        seed_answer,
        seed_error,
        final_done,
        plan_nudges,
        turn_used_tools,
        seed_sources,
        seed_trace,
        turn_trace,
    )
    .await
}

#[derive(Debug, Deserialize)]
struct ToolRunsQuery {
    limit: Option<usize>,
}

/// GET /api/tools/runs?limit=N — recent connector tool executions (audit log, #6).
async fn tool_runs_list(
    State(state): State<AppState>,
    axum::extract::Query(q): axum::extract::Query<ToolRunsQuery>,
) -> Json<serde_json::Value> {
    let limit = q.limit.unwrap_or(50).clamp(1, 500);
    let runs = lock_store(&state)
        .ok()
        .and_then(|s| s.recent_tool_runs(limit).ok())
        .unwrap_or_default();
    let items: Vec<serde_json::Value> = runs
        .into_iter()
        .map(|r| {
            serde_json::json!({
                "ts": r.ts,
                "thread_id": r.thread_id,
                "tool": r.tool,
                "kind": r.kind,
                "ok": r.ok,
                "error_kind": r.error_kind,
                "duration_ms": r.duration_ms,
                "summary": r.summary,
            })
        })
        .collect();
    Json(serde_json::json!({ "runs": items }))
}

#[derive(Debug, Deserialize)]
struct SuggestionsQuery {
    scope: Option<String>,
    limit: Option<usize>,
}

/// GET /api/suggestions?scope=&limit= — pending proactive cards + per-scope counts
/// (ADR 0011 §7: the dashboard surface). Shows pending; status filters come later.
async fn suggestions_list(
    State(state): State<AppState>,
    axum::extract::Query(q): axum::extract::Query<SuggestionsQuery>,
) -> Json<serde_json::Value> {
    let limit = q.limit.unwrap_or(50).clamp(1, 200);
    let (rows, counts) = lock_store(&state)
        .map(|s| {
            (
                s.pending_suggestions(q.scope.as_deref(), limit)
                    .unwrap_or_default(),
                s.pending_suggestion_counts().unwrap_or_default(),
            )
        })
        .unwrap_or_default();
    let items: Vec<serde_json::Value> = rows
        .into_iter()
        .map(|r| {
            serde_json::json!({
                "id": r.id,
                "scope": r.scope,
                "kind": r.kind,
                "title": r.title,
                "body": r.body,
                "rationale": r.rationale,
                "proposed_action": r.proposed_action,
                "choices": suggestion_choices_json(&r.choices),
                "status": r.status,
                "feedback": r.feedback,
                "created_at": r.created_at,
                "generated_at": r.created_at,
                "source_ref": r.source_ref,
                "relevant_until": r.relevant_until,
            })
        })
        .collect();
    let counts: Vec<serde_json::Value> = counts
        .into_iter()
        .map(|(scope, count)| serde_json::json!({ "scope": scope, "count": count }))
        .collect();
    Json(serde_json::json!({ "suggestions": items, "counts": counts }))
}

#[derive(Debug, Deserialize)]
struct SuggestionActRequest {
    status: String,
    #[serde(default)]
    feedback: Option<String>,
    #[serde(default)]
    note: Option<String>,
}

/// POST /api/suggestions/{id}/act — accept|dismiss|snooze a card + optional feedback
/// (liked|disliked). Dismissed cards never reappear (durable dedup); feedback
/// conditions future suggestions.
async fn suggestion_act(
    State(state): State<AppState>,
    Path(id): Path<i64>,
    Json(req): Json<SuggestionActRequest>,
) -> Json<serde_json::Value> {
    let status = match req.status.as_str() {
        "accepted" | "dismissed" | "snoozed" => req.status.as_str(),
        _ => "dismissed",
    };
    let feedback = req
        .feedback
        .as_deref()
        .filter(|f| matches!(*f, "liked" | "disliked"));
    let row = lock_store(&state)
        .ok()
        .and_then(|s| s.suggestion(id).ok().flatten());
    let ok = lock_store(&state)
        .ok()
        .and_then(|s| {
            s.set_suggestion_status(id, status, feedback, req.note.as_deref())
                .ok()
        })
        .is_some();
    if ok && let Some(row) = row {
        write_proactive_action_memory(&state, &row, status, feedback, req.note.as_deref());
    }
    Json(serde_json::json!({ "ok": ok }))
}

fn write_proactive_action_memory(
    state: &AppState,
    row: &chat_store::SuggestionRow,
    status: &str,
    feedback: Option<&str>,
    note: Option<&str>,
) {
    let lifecycle = MemoryLifecycleRequest {
        actor_id: "proactivity".to_string(),
        user_id: gateway_memory_user_id(),
        workspace_id: MemoryWorkspaceId::new(&row.scope),
        purpose: "proactive_action_writeback".to_string(),
    };
    let Some(request) =
        proactive_memory_request_for_suggestion_action(row, status, feedback, note, lifecycle)
    else {
        return;
    };
    let facade = memory_facade(state);
    if let Ok(record) = facade.create_memory_candidate(request.clone()) {
        let _ = facade.confirm_memory(
            &request.request,
            &record.reference,
            "proactive action write-back",
        );
    }
}

fn proactive_memory_request_for_suggestion_action(
    row: &chat_store::SuggestionRow,
    status: &str,
    feedback: Option<&str>,
    note: Option<&str>,
    request: MemoryLifecycleRequest,
) -> Option<MemoryCreateRequest> {
    let memory_type = match status {
        "accepted" | "snoozed" => "open_loop",
        "dismissed" => "decision",
        _ => return None,
    };
    let note = note.map(str::trim).filter(|value| !value.is_empty());
    let feedback = feedback.map(str::trim).filter(|value| !value.is_empty());
    let action = row
        .proposed_action
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let text = match status {
        "accepted" => {
            let action_text = action.unwrap_or(row.body.as_str());
            format!(
                "Open loop from proactive card accepted: {} — follow through on: {}",
                row.title, action_text
            )
        }
        "snoozed" => format!(
            "Open loop from proactive card snoozed: {} — revisit later. {}",
            row.title, row.body
        ),
        "dismissed" => {
            let reason = note.or(feedback).unwrap_or("no reason recorded");
            format!(
                "Decision from proactive card: dismissed '{}' — reason: {}",
                row.title, reason
            )
        }
        _ => return None,
    };
    Some(MemoryCreateRequest {
        request,
        memory_type: memory_type.to_string(),
        text: redact_sensitive_text(&text),
        aliases: vec![row.title.clone(), row.kind.clone(), row.dedup_key.clone()],
        language_hints: Vec::new(),
        confidence: 1.0,
        privacy_domain: PrivacyDomain::new("work"),
        sensitivity: MemoryDataSensitivity::Internal,
        evidence_refs: Vec::new(),
        metadata: serde_json::json!({
            "source": "proactivity",
            "suggestion": {
                "id": row.id,
                "scope": row.scope.clone(),
                "kind": row.kind.clone(),
                "title": row.title.clone(),
                "status": status,
                "feedback": feedback,
                "note": note,
                "dedup_key": row.dedup_key.clone(),
                "proposed_action": row.proposed_action.clone(),
            }
        }),
    })
}

#[derive(Debug, Deserialize)]
struct ProactiveReviewRequest {
    /// A workspace id or "__personal__". Empty → personal scope.
    #[serde(default)]
    scope: String,
}

/// POST /api/proactivity/review-now — run the A2 supervisor review IMMEDIATELY for
/// a scope (the manual trigger): assemble real
/// context, emit AT MOST ONE grounded card, dedup, insert. Returns the emitted
/// card or `{emitted:false}`. Lets us verify the engine end-to-end on demand,
/// before the idle/connector trigger is wired.
async fn proactivity_review_now(
    State(state): State<AppState>,
    Json(req): Json<ProactiveReviewRequest>,
) -> Json<serde_json::Value> {
    let scope = {
        let s = req.scope.trim();
        if s.is_empty() {
            PERSONAL_WORKSPACE.to_string()
        } else {
            s.to_string()
        }
    };
    if !lock_store(&state)
        .map(|s| s.plugin_enabled("proattivita"))
        .unwrap_or(true)
    {
        return Json(serde_json::json!({ "emitted": false, "disabled": true }));
    }
    match run_proactive_review(&state, &scope).await {
        Some(id) => {
            let card = lock_store(&state)
                .ok()
                .and_then(|s| s.pending_suggestions(Some(&scope), 50).ok())
                .and_then(|cards| cards.into_iter().find(|c| c.id == id))
                .map(|r| {
                    serde_json::json!({
                        "id": r.id,
                        "scope": r.scope,
                        "kind": r.kind,
                        "title": r.title,
                        "body": r.body,
                        "rationale": r.rationale,
                        "proposed_action": r.proposed_action,
                        "choices": suggestion_choices_json(&r.choices),
                        "status": r.status,
                        "created_at": r.created_at,
                    })
                });
            Json(serde_json::json!({ "emitted": true, "id": id, "card": card }))
        }
        None => Json(serde_json::json!({ "emitted": false })),
    }
}

#[derive(Debug, Clone)]
struct VisibleConversationTurn {
    turn_id: String,
    user_message_id: String,
    assistant_message_id: String,
}

fn thread_turn_started_event(
    thread_id: &str,
    workspace: &str,
    source: &str,
    channel: Option<&str>,
    title: &str,
    turn: &VisibleConversationTurn,
) -> serde_json::Value {
    let mut event = serde_json::json!({
        "type": "thread.turn_started",
        "thread_id": thread_id,
        "workspace": workspace,
        "source": source,
        "title": title,
        "turn_id": turn.turn_id,
        "user_message_id": turn.user_message_id,
        "assistant_message_id": turn.assistant_message_id,
    });
    if let Some(channel) = channel {
        event["channel"] = serde_json::Value::String(channel.to_string());
    }
    event
}

/// A store error a retry (fresh transaction) can plausibly clear: SQLite BUSY/LOCKED
/// under the unified homun.sqlite/WAL when another writer is active. `busy_timeout`
/// handles pure busy-waiting, but a write-write snapshot conflict returns immediately —
/// only re-running the transaction (not waiting) resolves it.
fn is_transient_store_error(error: &rusqlite::Error) -> bool {
    matches!(
        error,
        rusqlite::Error::SqliteFailure(e, _)
            if matches!(
                e.code,
                rusqlite::ErrorCode::DatabaseBusy | rusqlite::ErrorCode::DatabaseLocked
            )
    )
}

#[allow(clippy::too_many_arguments)]
fn start_visible_conversation_turn(
    state: &AppState,
    thread_id: &str,
    workspace: &str,
    source: &str,
    channel: Option<&str>,
    title: &str,
    user_text: &str,
    // When the broker's atomic enqueue already persisted a tree-linked prompt
    // (`local_user_{request_id}`), REUSE its id here so `commit_prompt_result`'s
    // INSERT OR IGNORE no-ops on it instead of minting a second `msg_...` row.
    // `None` for the inline paths (channel / automation / approval) that have no
    // pre-seeded message and must mint a fresh id.
    preseeded_user_message_id: Option<&str>,
    // The assistant placeholder is preallocated with the user prompt by broker
    // enqueue. Reusing this stable id across worker attempts prevents duplicate
    // assistant bubbles after a retry.
    preseeded_assistant_message_id: Option<&str>,
    // The broker turn id (`turn_{request_id}` = the task id) to advertise in the
    // `thread.turn_started` event. This is the SAME id the live WS `turn.event` fan-out and
    // the resumable turn stream key on, so a client that receives the event can attach to the
    // running turn (live island + transcript) — including a channel turn it never launched.
    // `None` for legacy inline paths with no broker task: they mint a throwaway id (nothing
    // downstream joins on the visible turn_id, so it stays cosmetic for those).
    turn_id_override: Option<&str>,
    // A persisted-bubble executor (currently proactive automation) owns this
    // assistant from creation, so an inline action card can later resolve the
    // exact waiting task without guessing from thread state.
    linked_task_id: Option<&str>,
) -> Option<VisibleConversationTurn> {
    let user_message = match preseeded_user_message_id {
        Some(id) => channel_chat_message_with_id("user", user_text, id),
        None => channel_chat_message("user", user_text),
    };
    let mut assistant_message = match preseeded_assistant_message_id {
        Some(id) => channel_chat_message_with_id("assistant", "", id),
        None => channel_chat_message("assistant", "…"),
    };
    assistant_message.memory_reuse =
        Some(local_first_memory::MemoryReuseEnvelope::blocked_unknown());
    assistant_message.delivery_state = local_first_desktop_gateway::MessageDeliveryState::Streaming;
    assistant_message.linked_task_id = linked_task_id.map(str::to_string);
    let turn = VisibleConversationTurn {
        turn_id: match turn_id_override {
            Some(id) => id.to_string(),
            None => format!(
                "turn_{}_{}",
                now_epoch_secs(),
                uuid::Uuid::new_v4().simple()
            ),
        },
        user_message_id: user_message.id.clone(),
        assistant_message_id: assistant_message.id.clone(),
    };
    // Persist the visible turn via commit_prompt_result (inserts both messages AND
    // synthesizes the provisional title from the first prompt when the thread is still
    // titled "New task"). This is a fail-closed safety boundary: a failure here aborts
    // the whole turn ("could not start a visible ... turn").
    //
    // Under the UNIFIED homun.sqlite (chat + task stores on ONE WAL file), a concurrent
    // writer can make this hit a TRANSIENT `SQLITE_BUSY`/`LOCKED`. `busy_timeout` alone
    // doesn't cover a write-write *snapshot* conflict (it returns immediately; only a
    // fresh transaction — a retry — resolves it, not waiting). That's why unattended
    // automations failed intermittently (e.g. 09:00 ok, 09:06 "failed") while
    // interactive chats mostly succeeded. So retry a few times before giving up, and
    // never swallow the error silently.
    let mut attempt = 0u32;
    loop {
        attempt += 1;
        let persisted = match lock_store(state) {
            Ok(store) => {
                store.commit_prompt_result(thread_id, &user_message, &assistant_message, None)
            }
            Err(error) => {
                tracing::error!(
                    target: "gateway::visible_turn",
                    %thread_id, %source, error = %error.message,
                    "start_visible_conversation_turn: chat store lock failed"
                );
                return None;
            }
        };
        match persisted {
            Ok(_) => break,
            Err(error) if is_transient_store_error(&error) && attempt < 5 => {
                tracing::warn!(
                    target: "gateway::visible_turn",
                    %thread_id, %source, attempt, error = %error,
                    "start_visible_conversation_turn: transient store contention — retrying"
                );
                std::thread::sleep(std::time::Duration::from_millis(u64::from(attempt) * 40));
            }
            Err(error) => {
                tracing::error!(
                    target: "gateway::visible_turn",
                    %thread_id, %source, attempt, error = %error,
                    "start_visible_conversation_turn: could not persist the turn — failing closed"
                );
                return None;
            }
        }
    }
    if let Some(assistant_message_id) = preseeded_assistant_message_id {
        let reopened = lock_store(state).ok().and_then(|store| {
            store
                .set_message_delivery_state(
                    thread_id,
                    assistant_message_id,
                    local_first_desktop_gateway::MessageDeliveryState::Streaming,
                )
                .ok()
        });
        if reopened != Some(true) {
            tracing::error!(
                target: "gateway::visible_turn",
                %thread_id,
                %assistant_message_id,
                "start_visible_conversation_turn: could not reopen assistant stream"
            );
            return None;
        }
    }
    // Re-read the (now provisional) title so the event reflects what was persisted,
    // rather than echoing the raw prompt passed in by the caller.
    let started_title = lock_store(state)
        .ok()
        .and_then(|store| store.thread(thread_id).ok().flatten())
        .map(|t| t.title)
        .unwrap_or_else(|| title.to_string());
    publish_app_event(thread_turn_started_event(
        thread_id,
        workspace,
        source,
        channel,
        &started_title,
        &turn,
    ));
    Some(turn)
}

fn context_message_for_model(
    _facade: &MemoryFacade,
    _consumer: (&MemoryUserId, &MemoryWorkspaceId),
    message: &ChatMessage,
    _now_unix: i64,
) -> Option<ChatContextMessage> {
    local_first_desktop_gateway::chat_message_for_existing_thread_context(message)
}

fn thread_context_for_model(
    state: &AppState,
    thread_id: &str,
    skip_message_ids: &[&str],
    current_prompt: Option<&str>,
) -> Option<Vec<ChatContextMessage>> {
    let skip: std::collections::HashSet<&str> = skip_message_ids.iter().copied().collect();
    let (snapshot, workspace_id) = {
        let Ok(store) = lock_store(state) else {
            return None;
        };
        (
            store.messages(thread_id).ok()?,
            store.workspace_for_thread(thread_id).ok()?,
        )
    };
    let mut messages: Vec<ChatMessage> = snapshot
        .messages
        .into_iter()
        .filter(|m| matches!(m.role.as_str(), "user" | "assistant"))
        .filter(|m| !skip.contains(m.id.as_str()))
        .collect();
    if messages
        .last()
        .is_some_and(|message| message.role == "assistant" && message.text.trim() == "…")
    {
        messages.pop();
    }
    if let Some(current_prompt) = current_prompt
        && messages.last().is_some_and(|message| {
            message.role == "user" && message.text.trim() == current_prompt.trim()
        })
    {
        messages.pop();
    }
    let facade = memory_facade(state);
    let user = gateway_memory_user_id();
    let workspace = MemoryWorkspaceId::new(workspace_id);
    let now_unix = i64::try_from(now_epoch_secs()).unwrap_or(i64::MAX);
    let mut msgs: Vec<ChatContextMessage> = messages
        .iter()
        .filter_map(|message| {
            context_message_for_model(facade, (&user, &workspace), message, now_unix)
        })
        .collect();
    let len = msgs.len();
    if len > 16 {
        msgs.drain(0..len - 16);
    }
    Some(msgs)
}

fn agent_turn_context(
    state: &AppState,
    thread_id: &str,
    skip_message_ids: &[&str],
) -> Option<Vec<ChatContextMessage>> {
    thread_context_for_model(state, thread_id, skip_message_ids, None)
}

fn apply_agent_stream_line(
    line: &str,
    streamed_text: &mut String,
    final_text: &mut Option<String>,
) -> bool {
    let line = line.trim();
    if line.is_empty() {
        return false;
    }
    let Ok(value) = serde_json::from_str::<serde_json::Value>(line) else {
        return false;
    };
    match value.get("type").and_then(|t| t.as_str()) {
        Some("delta") => {
            if let Some(text) = value.get("text").and_then(|t| t.as_str()) {
                streamed_text.push_str(text);
            }
            false
        }
        Some("done") => {
            if let Some(text) = value.get("text").and_then(|t| t.as_str()) {
                *final_text = Some(text.to_string());
            } else if !streamed_text.trim().is_empty() {
                *final_text = Some(streamed_text.clone());
            }
            true
        }
        Some("error") => true,
        _ => false,
    }
}

fn update_channel_assistant_message(
    state: &AppState,
    thread_id: &str,
    message_id: &str,
    text: &str,
) {
    if let Ok(store) = lock_store(state) {
        let _ = store.set_message_text(thread_id, message_id, text);
    }
    publish_app_event(serde_json::json!({
        "type": "thread.updated",
        "thread_id": thread_id,
        "workspace": base_workspace_id(),
    }));
}

fn memory_reuse_envelope_from_read_set(
    reads: &local_first_engine::events::TurnMemoryReadSet,
) -> local_first_memory::MemoryReuseEnvelope {
    if reads.is_blocked_unknown() {
        return local_first_memory::MemoryReuseEnvelope::blocked_unknown();
    }
    if !reads.has_linked_reads() {
        return local_first_memory::MemoryReuseEnvelope::normal();
    }
    local_first_memory::MemoryReuseEnvelope::user_input_only(
        reads
            .linked
            .iter()
            .map(|read| local_first_memory::LinkedMemoryReadRef {
                source_workspace_id: read.source_workspace_id.clone(),
                grant_id: read.grant_id.clone(),
                policy_version: read.policy_version,
                memory_ref: read.memory_ref.clone(),
                source_revision: read.source_revision.clone(),
            })
            .collect(),
    )
}

#[derive(Debug, Default)]
struct StreamMemoryReuseCollector {
    event_parts: Vec<serde_json::Value>,
    reads: local_first_engine::events::TurnMemoryReadSet,
}

impl StreamMemoryReuseCollector {
    fn observe_line(&mut self, line: &str) {
        let Ok(value) = serde_json::from_str::<serde_json::Value>(line.trim()) else {
            return;
        };
        if value.get("type").and_then(serde_json::Value::as_str) != Some("recall") {
            return;
        }
        let Some(payload_value) = value.get("payload").cloned() else {
            self.reads.blocked_unknown = true;
            return;
        };
        let part = serde_json::json!({
            "type": "recall",
            "payload": payload_value,
        });
        if !self.event_parts.contains(&part) {
            self.event_parts.push(part);
        }
        match serde_json::from_value::<local_first_subagents::RecallStreamPayload>(payload_value) {
            Ok(payload) => self.reads.extend_payload(&payload),
            Err(_) => self.reads.blocked_unknown = true,
        }
    }

    fn event_parts(&self) -> &[serde_json::Value] {
        &self.event_parts
    }

    fn observe_remote_approval(&mut self, intent: &RemoteApprovalIntent) {
        let part = remote_approval_event_part(intent);
        if !self.event_parts.contains(&part) {
            self.event_parts.push(part);
        }
    }

    fn observe_actionable_cards(&mut self, cards: &[ActionableCard]) {
        for card in cards {
            let part = serde_json::json!({
                "type": "actionable_card",
                "kind": card.kind,
                "payload": card.payload,
                "raw": card.raw,
            });
            if !self.event_parts.contains(&part) {
                self.event_parts.push(part);
            }
        }
    }

    fn envelope(&self) -> local_first_memory::MemoryReuseEnvelope {
        memory_reuse_envelope_from_read_set(&self.reads)
    }
}

fn finalize_streamed_assistant_message(
    state: &AppState,
    thread_id: &str,
    message_id: &str,
    text: &str,
    collector: &StreamMemoryReuseCollector,
    requested_delivery_state: local_first_desktop_gateway::MessageDeliveryState,
) -> Result<(), String> {
    let store = lock_store(state).map_err(|error| error.message)?;
    store
        .finalize_assistant_message_with_delivery_state(
            thread_id,
            message_id,
            text,
            collector.event_parts(),
            &collector.envelope(),
            requested_delivery_state,
        )
        .map_err(|error| error.to_string())?;
    publish_app_event(serde_json::json!({
        "type": "thread.updated",
        "thread_id": thread_id,
        "workspace": base_workspace_id(),
    }));
    Ok(())
}

/// Typed TurnOutcome projection: this is the gateway's source of truth for opening
/// Free HITL waits. Marker/event-part persistence remains only as stream compatibility.
fn persist_hitl_wait_from_outcome(
    state: &AppState,
    thread_id: &str,
    message_id: &str,
    outcome: &local_first_engine::TurnOutcome,
) -> Result<(), String> {
    let Some(envelope) = outcome.awaiting_user.as_ref() else {
        return Ok(());
    };
    if !envelope.is_free() {
        return Ok(());
    }
    let wait_kind = match envelope.kind {
        local_first_engine::hitl::HitlKind::Choice
        | local_first_engine::hitl::HitlKind::Clarify
        | local_first_engine::hitl::HitlKind::PlanPropose => envelope.wait_kind_key(),
        local_first_engine::hitl::HitlKind::Confirm
        | local_first_engine::hitl::HitlKind::Vault
        | local_first_engine::hitl::HitlKind::Payment => return Ok(()),
    };
    let store = lock_store(state).map_err(|error| error.message)?;
    persist_hitl_wait_payload(
        &store,
        state,
        thread_id,
        message_id,
        wait_kind,
        envelope.payload.clone(),
    )
}

fn persist_hitl_wait_payload(
    store: &chat_store::ChatStore,
    state: &AppState,
    thread_id: &str,
    message_id: &str,
    wait_kind: &str,
    payload: serde_json::Value,
) -> Result<(), String> {
    let browser_live = state
        .browser_thread_sessions
        .lock()
        .map_err(|error| format!("browser session store unavailable: {error}"))?
        .get(thread_id)
        .is_some_and(|session| thread_browser_session_is_live(session.last_used));
    // `store` is already held by both callers. Resolve the workspace through that
    // guard and read task state directly; calling `runtime_plan_control_scope` here
    // would try to acquire the same chat-store mutex again and self-deadlock.
    let workspace_id = store
        .workspace_for_thread(thread_id)
        .map_err(|error| format!("HITL workspace lookup failed: {error}"))?;
    let task_store = state
        .task_store
        .lock()
        .map_err(|error| format!("task store unavailable while persisting HITL wait: {error}"))?;
    let user_id = gateway_user_id();
    let contract = task_store
        .load_objective_contract(user_id.as_str(), &workspace_id, thread_id)
        .map_err(|error| format!("HITL objective lookup failed: {error}"))?
        .as_ref()
        .map(hitl_resume::ResumeContractSnapshot::from_objective);
    let plan = task_store
        .load_runtime_plan(user_id.as_str(), &workspace_id, thread_id)
        .map_err(|error| format!("HITL runtime plan lookup failed: {error}"))?
        .filter(|plan| plan.status == "open")
        // Tolerates both persistence shapes: `{"goal", "steps"}` and the legacy bare step array.
        .map(|plan| local_first_engine::plan::plan_value_steps(&plan.plan_json))
        .unwrap_or_default();
    let remaining_plan = hitl_resume::bounded_remaining_plan(plan);
    let browser_checkpoint_generation = task_store
        .load_active_browser_checkpoint_for_thread(user_id.as_str(), &workspace_id, thread_id)
        .map_err(|error| format!("HITL browser checkpoint lookup failed: {error}"))?
        .map(|checkpoint| checkpoint.generation);
    drop(task_store);
    let open_work = hitl_resume::OpenWorkSnapshot {
        schema_version: hitl_resume::OPEN_WORK_SCHEMA_VERSION,
        browser_session_live: browser_live,
        browser_checkpoint_available: browser_checkpoint_generation.is_some(),
        browser_checkpoint_generation,
        last_url: None,
        capability_hint: (browser_live || browser_checkpoint_generation.is_some())
            .then(|| "browse".to_string()),
        contract,
        remaining_plan,
    };
    let wait_id = format!("hitl_{wait_kind}_{message_id}");
    let payload_json = serde_json::to_string(&payload)
        .map_err(|error| format!("HITL payload serialization failed: {error}"))?;
    let open_work_json = serde_json::to_string(&open_work)
        .map_err(|error| format!("HITL open-work serialization failed: {error}"))?;
    store
        .set_open_hitl_wait(
            &wait_id,
            thread_id,
            message_id,
            wait_kind,
            &payload_json,
            &open_work_json,
        )
        .map_err(|error| format!("HITL wait persistence failed: {error}"))
}

#[derive(Debug, Clone)]
pub(crate) struct AgentTurnResult {
    text: String,
    actionable_cards: Vec<ActionableCard>,
    outcome: local_first_engine::TurnOutcome,
}

pub(crate) struct BrokerAgentTurnResult {
    outcome: local_first_engine::TurnOutcome,
}

fn wake_for_agent_stop(
    contract: &local_first_execution_protocol::ValidatedExecutionContract,
    stop: &local_first_engine::TurnStop,
    action: Option<&str>,
) -> Option<local_first_execution_protocol::WakeCondition> {
    match stop {
        local_first_engine::TurnStop::SuspendedUser => {
            Some(local_first_execution_protocol::WakeCondition::User {
                wait_ref: format!(
                    "{}:{}:user",
                    contract.as_ref().execution_id,
                    contract.as_ref().revision
                ),
            })
        }
        local_first_engine::TurnStop::SuspendedApproval => {
            Some(local_first_execution_protocol::WakeCondition::Approval {
                approval_ref: format!(
                    "{}:{}:approval:{}",
                    contract.as_ref().execution_id,
                    contract.as_ref().revision,
                    action.unwrap_or("action_card")
                ),
            })
        }
        local_first_engine::TurnStop::SuspendedEffect { receipt_ref } => Some(
            local_first_execution_protocol::WakeCondition::EffectResolution {
                receipt_ref: receipt_ref.clone(),
            },
        ),
        local_first_engine::TurnStop::SuspendedModel { role } => Some(
            local_first_execution_protocol::WakeCondition::ModelAvailable { role: role.clone() },
        ),
        local_first_engine::TurnStop::Completed | local_first_engine::TurnStop::Failed { .. } => {
            None
        }
    }
}

async fn drain_agent_stream_into_message(
    state: &AppState,
    thread_id: &str,
    assistant_message_id: &str,
    entry: std::sync::Arc<StreamEntry>,
    requested_delivery_state: local_first_desktop_gateway::MessageDeliveryState,
) -> Result<Option<AgentTurnResult>, String> {
    if let Ok(mut stored_id) = entry.assistant_message_id.lock() {
        *stored_id = Some(assistant_message_id.to_string());
    }
    let mut streamed_text = String::new();
    let mut final_text: Option<String> = None;
    let mut last_flush = std::time::Instant::now();
    let mut last_flushed_len = 0usize;
    let mut memory_reuse = StreamMemoryReuseCollector::default();

    let (snapshot, mut brx) = {
        let buf = entry.lines.lock().expect("stream lines lock");
        (buf.clone(), entry.tx.subscribe())
    };
    for line in snapshot {
        let terminal = apply_agent_stream_line(&line, &mut streamed_text, &mut final_text);
        memory_reuse.observe_line(&line);
        persist_recall_event_part(state, thread_id, assistant_message_id, &line);
        if streamed_text.len() != last_flushed_len
            && last_flush.elapsed() >= std::time::Duration::from_millis(200)
        {
            update_channel_assistant_message(
                state,
                thread_id,
                assistant_message_id,
                &streamed_text,
            );
            last_flush = std::time::Instant::now();
            last_flushed_len = streamed_text.len();
        }
        if terminal {
            break;
        }
    }

    while final_text.is_none() {
        match brx.recv().await {
            Ok(line) => {
                let terminal = apply_agent_stream_line(&line, &mut streamed_text, &mut final_text);
                memory_reuse.observe_line(&line);
                persist_recall_event_part(state, thread_id, assistant_message_id, &line);
                if streamed_text.len() != last_flushed_len
                    && last_flush.elapsed() >= std::time::Duration::from_millis(200)
                {
                    update_channel_assistant_message(
                        state,
                        thread_id,
                        assistant_message_id,
                        &streamed_text,
                    );
                    last_flush = std::time::Instant::now();
                    last_flushed_len = streamed_text.len();
                }
                if terminal {
                    break;
                }
            }
            Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => continue,
            Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
        }
    }

    let outcome = wait_for_stream_outcome(entry).await;
    let raw_final_text = final_text.unwrap_or(streamed_text);
    let remote_approval = remote_approval_intent_from_raw_text(&raw_final_text);
    let actionable_cards = actionable_cards_from_raw_text(&raw_final_text);
    if let Some(intent) = remote_approval.as_ref() {
        memory_reuse.observe_remote_approval(intent);
    }
    memory_reuse.observe_actionable_cards(&actionable_cards);
    let mut final_text = strip_chat_markers(&raw_final_text);
    if final_text.is_empty() && actionable_cards.is_empty() {
        return Ok(None);
    }
    if final_text.is_empty() {
        final_text = "Waiting for your approval.".to_string();
    }
    finalize_streamed_assistant_message(
        state,
        thread_id,
        assistant_message_id,
        &raw_final_text,
        &memory_reuse,
        requested_delivery_state,
    )?;
    Ok(Some(AgentTurnResult {
        text: final_text,
        actionable_cards,
        outcome,
    }))
}

/// Maps a raw stream value to a durable TurnEventKind and its transport payload.
fn turn_event_from_stream_value(
    value: &serde_json::Value,
) -> Option<(local_first_task_runtime::TurnEventKind, serde_json::Value)> {
    let kind_str = value.get("type").and_then(|t| t.as_str())?;
    let (kind, payload) = match kind_str {
        "delta" => (
            local_first_task_runtime::TurnEventKind::Delta,
            serde_json::json!({ "text": value.get("text").and_then(|t| t.as_str()).unwrap_or("") }),
        ),
        "reasoning" => (
            local_first_task_runtime::TurnEventKind::Reasoning,
            serde_json::json!({ "text": value.get("text").and_then(|t| t.as_str()).unwrap_or("") }),
        ),
        "activity" => (
            local_first_task_runtime::TurnEventKind::Activity,
            serde_json::json!({ "text": value.get("text").and_then(|t| t.as_str()).unwrap_or("") }),
        ),
        "plan_update" => (
            local_first_task_runtime::TurnEventKind::PlanUpdate,
            serde_json::json!({ "markdown": value.get("markdown").and_then(|t| t.as_str()).unwrap_or("") }),
        ),
        "tool_result" => (local_first_task_runtime::TurnEventKind::Tool, value.clone()),
        "step_advance" => (
            local_first_task_runtime::TurnEventKind::StepAdvance,
            // Frontend contract (exact): step_id, title, from (null for a new step), to,
            // verified (F2 verdict, null for plain moves), note.
            serde_json::json!({
                "step_id": value.get("step_id").and_then(|v| v.as_str()).unwrap_or(""),
                "title": value.get("title").and_then(|v| v.as_str()).unwrap_or(""),
                "from": value.get("from").cloned().filter(|v| !v.is_null()).unwrap_or(serde_json::Value::Null),
                "to": value.get("to").and_then(|v| v.as_str()).unwrap_or(""),
                "verified": value.get("verified").cloned().filter(|v| !v.is_null()).unwrap_or(serde_json::Value::Null),
                "note": value.get("note").cloned().filter(|v| !v.is_null()).unwrap_or(serde_json::Value::Null),
            }),
        ),
        "recall" => (
            local_first_task_runtime::TurnEventKind::Recall,
            value
                .get("payload")
                .cloned()
                .unwrap_or(serde_json::Value::Null),
        ),
        "error" => (
            local_first_task_runtime::TurnEventKind::Error,
            serde_json::json!({
                "code": value.get("code").and_then(Value::as_str).unwrap_or(""),
                "message": value.get("message").and_then(Value::as_str).unwrap_or(""),
                "retryable": value.get("retryable").and_then(Value::as_bool).unwrap_or(false),
            }),
        ),
        // unknown event types (e.g. choice_prompt, vault_propose) are not turn events
        _ => return None,
    };
    Some((kind, payload))
}

/// Stores an emitted Recall part with the assistant message. This is deliberately
/// idempotent because a stream snapshot and its broadcast tail can overlap.
fn persist_recall_event_part(
    state: &AppState,
    thread_id: &str,
    assistant_message_id: &str,
    line: &str,
) {
    let Ok(value) = serde_json::from_str::<serde_json::Value>(line.trim()) else {
        return;
    };
    if value.get("type").and_then(|kind| kind.as_str()) != Some("recall") {
        return;
    }
    let Some(payload) = value.get("payload") else {
        return;
    };
    let part = serde_json::json!({ "type": "recall", "payload": payload });
    if let Ok(store) = lock_store(state) {
        let _ = store.append_assistant_event_part(thread_id, assistant_message_id, &part);
    }
}

fn redacted_user_text_from_stream_line(line: &str) -> Option<String> {
    let value = serde_json::from_str::<serde_json::Value>(line.trim()).ok()?;
    if value.get("type").and_then(|kind| kind.as_str()) != Some("done") {
        return None;
    }
    value
        .get("redacted_user_text")
        .and_then(|text| text.as_str())
        .map(str::trim)
        .filter(|text| !text.is_empty())
        .map(str::to_string)
}

fn persist_redacted_user_text_from_stream_line(
    state: &AppState,
    thread_id: &str,
    user_message_id: &str,
    line: &str,
) {
    let Some(redacted) = redacted_user_text_from_stream_line(line) else {
        return;
    };
    if let Ok(store) = lock_store(state) {
        let _ = store.set_message_text(thread_id, user_message_id, &redacted);
    }
}

/// Maps a raw stream NDJSON line to a TurnEventKind + payload and emits it via
/// the turn_executor fan-out (durable turn_events + live broadcast). Best-effort:
/// unparseable lines or unknown types are silently skipped (they don't affect the
/// assistant message accumulation either).
fn fanout_turn_event(state: &AppState, turn_id: &str, line: &str) {
    let line = line.trim();
    if line.is_empty() {
        return;
    }
    let Ok(value) = serde_json::from_str::<serde_json::Value>(line) else {
        return;
    };
    let kind_str = value
        .get("type")
        .and_then(|t| t.as_str())
        .unwrap_or("unknown");
    tracing::debug!(target: "broker::fanout", turn_id = %turn_id, kind = %kind_str, "stream event");
    let Some((kind, payload)) = turn_event_from_stream_value(&value) else {
        return;
    };
    if let Ok(store) = state.task_store.lock() {
        let _ = crate::turn_executor::emit_turn_event(state, &store, turn_id, kind, payload);
    }
}

/// Like `drain_agent_stream_into_message` but additionally mirrors each raw
/// stream event into the turn_events durable log + per-turn live broadcast via
/// `fanout_turn_event`. Used by the broker executor path; the automation path
/// keeps using the plain drain.
async fn drain_agent_stream_into_message_with_fanout(
    state: &AppState,
    thread_id: &str,
    user_message_id: &str,
    assistant_message_id: &str,
    entry: std::sync::Arc<StreamEntry>,
    turn_id: &str,
    requested_delivery_state: local_first_desktop_gateway::MessageDeliveryState,
) -> Result<BrokerAgentTurnResult, String> {
    if let Ok(mut stored_id) = entry.assistant_message_id.lock() {
        *stored_id = Some(assistant_message_id.to_string());
    }
    let mut streamed_text = String::new();
    let mut final_text: Option<String> = None;
    let mut last_flush = std::time::Instant::now();
    let mut last_flushed_len = 0usize;
    let mut memory_reuse = StreamMemoryReuseCollector::default();

    let (snapshot, mut brx) = {
        let buf = entry.lines.lock().expect("stream lines lock");
        (buf.clone(), entry.tx.subscribe())
    };
    for line in snapshot {
        let terminal = apply_agent_stream_line(&line, &mut streamed_text, &mut final_text);
        memory_reuse.observe_line(&line);
        persist_redacted_user_text_from_stream_line(state, thread_id, user_message_id, &line);
        persist_recall_event_part(state, thread_id, assistant_message_id, &line);
        fanout_turn_event(state, turn_id, &line);
        if streamed_text.len() != last_flushed_len
            && last_flush.elapsed() >= std::time::Duration::from_millis(200)
        {
            update_channel_assistant_message(
                state,
                thread_id,
                assistant_message_id,
                &streamed_text,
            );
            last_flush = std::time::Instant::now();
            last_flushed_len = streamed_text.len();
        }
        if terminal {
            break;
        }
    }

    let mut typed_outcome = None;
    while final_text.is_none() && typed_outcome.is_none() {
        let outcome_ready = entry.outcome_ready.notified();
        if let Some(outcome) = entry.outcome.lock().ok().and_then(|slot| slot.clone()) {
            typed_outcome = Some(outcome);
            break;
        }
        tokio::select! {
            received = brx.recv() => match received {
            Ok(line) => {
                let terminal = apply_agent_stream_line(&line, &mut streamed_text, &mut final_text);
                memory_reuse.observe_line(&line);
                persist_redacted_user_text_from_stream_line(
                    state,
                    thread_id,
                    user_message_id,
                    &line,
                );
                persist_recall_event_part(state, thread_id, assistant_message_id, &line);
                fanout_turn_event(state, turn_id, &line);
                if streamed_text.len() != last_flushed_len
                    && last_flush.elapsed() >= std::time::Duration::from_millis(200)
                {
                    update_channel_assistant_message(
                        state,
                        thread_id,
                        assistant_message_id,
                        &streamed_text,
                    );
                    last_flush = std::time::Instant::now();
                    last_flushed_len = streamed_text.len();
                }
                if terminal {
                    break;
                }
            }
            Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => continue,
            Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
            },
            _ = outcome_ready => {
                typed_outcome = entry.outcome.lock().ok().and_then(|slot| slot.clone());
            }
        }
    }

    // The engine publishes the typed outcome only after all stream emissions.
    // Drain any lines already queued before using the outcome as the transport close.
    while let Ok(line) = brx.try_recv() {
        apply_agent_stream_line(&line, &mut streamed_text, &mut final_text);
        memory_reuse.observe_line(&line);
        persist_redacted_user_text_from_stream_line(state, thread_id, user_message_id, &line);
        persist_recall_event_part(state, thread_id, assistant_message_id, &line);
        fanout_turn_event(state, turn_id, &line);
    }
    let outcome = match typed_outcome {
        Some(outcome) => outcome,
        None => wait_for_stream_outcome(entry.clone()).await,
    };

    let raw_final_text = final_text.unwrap_or(streamed_text);
    let remote_approval = remote_approval_intent_from_raw_text(&raw_final_text);
    let actionable_cards = actionable_cards_from_raw_text(&raw_final_text);
    if let Some(intent) = remote_approval.as_ref() {
        memory_reuse.observe_remote_approval(intent);
    }
    memory_reuse.observe_actionable_cards(&actionable_cards);
    let final_text = strip_chat_markers(&raw_final_text);
    if !(final_text.is_empty() && actionable_cards.is_empty()) {
        finalize_streamed_assistant_message(
            state,
            thread_id,
            assistant_message_id,
            &raw_final_text,
            &memory_reuse,
            requested_delivery_state,
        )?;
    }
    Ok(BrokerAgentTurnResult { outcome })
}

/// Runs an agent turn for channel-originated work while keeping the owning chat
/// visible: the inbound user message and assistant placeholder already exist,
/// and this function streams deltas into that assistant message.
fn agent_turn_stream_request_id(assistant_message_id: &str) -> String {
    format!("agentturn-{assistant_message_id}")
}

async fn run_agent_turn_into_message(
    state: &AppState,
    thread_id: &str,
    prompt: &str,
    tool_policy: &str,
    source_user_message_id: &str,
    assistant_message_id: &str,
    requested_delivery_state: local_first_desktop_gateway::MessageDeliveryState,
) -> Result<Option<AgentTurnResult>, String> {
    let (base_url, model, api_key) = chat_role_config_for_thread(state, Some(thread_id))
        .ok_or_else(|| "chat role configuration is unavailable".to_string())?;
    let context = agent_turn_context(
        state,
        thread_id,
        &[source_user_message_id, assistant_message_id],
    )
    .ok_or_else(|| "chat context is unavailable".to_string())?;
    let request_id = agent_turn_stream_request_id(assistant_message_id);
    let request = ChatGenerateStreamRequest {
        request_id: request_id.clone(),
        agent_run_id: None,
        agent_checkpoint: None,
        checkpoint_input: None,
        prompt: prompt.to_string(),
        thread_id: Some(thread_id.to_string()),
        context,
        max_context_chars: None,
        model: None,
        images: Vec::new(),
        attachments: Vec::new(),
        max_tokens: 2000,
        temperature: 0.3,
        wait_if_busy: true,
        request_timeout_seconds: None,
        tool_policy: Some(tool_policy.to_string()),
        mode: None,
    };
    let response = stream_chat_via_openai(state, request, base_url, model, api_key)
        .await
        .map_err(|error| error.message)?;
    let entry = stream_registry()
        .lock()
        .ok()
        .and_then(|map| map.get(&request_id).cloned());
    let body_task = tokio::spawn(async move {
        let _ = axum::body::to_bytes(response.into_body(), usize::MAX).await;
    });

    let result = match entry {
        Some(entry) => {
            drain_agent_stream_into_message(
                state,
                thread_id,
                assistant_message_id,
                entry,
                requested_delivery_state,
            )
            .await
        }
        None => {
            let _ = body_task.await;
            return Err("stream registration disappeared before draining".to_string());
        }
    };
    let _ = body_task.await;
    result
}

/// Like `run_agent_turn_into_message` but additionally mirrors each stream
/// event into turn_events (durable) + the per-turn broadcast (live) via the
/// fan-out drain. Used by the broker executor path.
#[allow(clippy::too_many_arguments)]
async fn run_agent_turn_into_message_with_fanout(
    state: &AppState,
    thread_id: &str,
    prompt: &str,
    tool_policy: &str,
    images: Vec<String>,
    attachments: Vec<AttachmentInput>,
    source_user_message_id: &str,
    assistant_message_id: &str,
    turn_id: &str,
    agent_run_id: Option<&str>,
    agent_checkpoint: Option<serde_json::Value>,
    checkpoint_input: Option<serde_json::Value>,
    model_override: Option<&str>,
    requested_delivery_state: local_first_desktop_gateway::MessageDeliveryState,
) -> Result<BrokerAgentTurnResult, String> {
    let (base_url, model, api_key) =
        chat_model_config_for_turn(state, Some(thread_id), model_override)?;
    let context = agent_turn_context(
        state,
        thread_id,
        &[source_user_message_id, assistant_message_id],
    )
    .ok_or_else(|| "chat context is unavailable".to_string())?;
    let request_id = format!("broker-{turn_id}");
    let request = ChatGenerateStreamRequest {
        request_id: request_id.clone(),
        agent_run_id: agent_run_id.map(str::to_string),
        agent_checkpoint,
        checkpoint_input,
        prompt: prompt.to_string(),
        thread_id: Some(thread_id.to_string()),
        context,
        max_context_chars: None,
        model: None,
        images,
        attachments,
        max_tokens: 2000,
        temperature: 0.3,
        wait_if_busy: true,
        request_timeout_seconds: None,
        tool_policy: Some(tool_policy.to_string()),
        mode: None,
    };
    let response = stream_chat_via_openai(state, request, base_url, model, api_key)
        .await
        .map_err(|error| error.message)?;
    let entry = stream_registry()
        .lock()
        .ok()
        .and_then(|map| map.get(&request_id).cloned());
    if let Some(abort) = stream_abort_registry()
        .lock()
        .ok()
        .and_then(|map| map.get(&request_id).cloned())
    {
        crate::turn_executor::attach_turn_engine_abort(turn_id, abort);
    }

    let body_task = tokio::spawn(async move {
        let _ = axum::body::to_bytes(response.into_body(), usize::MAX).await;
    });

    let result = match entry {
        Some(entry) => {
            drain_agent_stream_into_message_with_fanout(
                state,
                thread_id,
                source_user_message_id,
                assistant_message_id,
                entry,
                turn_id,
                requested_delivery_state,
            )
            .await
        }
        None => {
            let _ = body_task.await;
            return Err("stream registration disappeared before draining".to_string());
        }
    };
    let _ = body_task.await;
    result
}

// `extract_source_urls`, `is_low_value_source_url`, `fonti_section` moved to `engine::text`
// (ADR 0024 inc 5e.3, pure loop-delivery helpers); imported below.

/// The engine's runtime-plan progress port (ADR 0024 inc 5c): when the loop moves into the engine it
/// persists/records/verifies plan progress through this seam instead of reaching into `AppState`. Owns
/// a cheap `AppState` clone (all-`Arc` fields) because `persist_plan`/`record_step_outcome` move it into
/// `spawn_blocking` (the memory facade is sync). Delegates verbatim to the three existing helpers, so
/// behavior is unchanged — the loop still calls them directly until inc 5e adopts this adapter.
// Constructed live in run_agent_rounds (5.D1c.4): the loop routes the delivery reconcile through this
// adapter; 5.D1c.5 adds the plan persist + step verification paths.
pub(crate) struct GatewayPlanProgress {
    pub state: AppState,
}

impl local_first_engine::PlanProgress for GatewayPlanProgress {
    async fn persist_plan(
        &self,
        thread: Option<&str>,
        goal: Option<&str>,
        steps: &[serde_json::Value],
    ) {
        let st = self.state.clone();
        let thread = thread.map(str::to_string);
        let goal = goal.map(str::to_string);
        let steps = steps.to_vec();
        let _ = tokio::task::spawn_blocking(move || {
            upsert_runtime_plan_memory_from_state(&st, thread.as_deref(), goal.as_deref(), &steps);
        })
        .await;
    }

    async fn record_step_outcome(
        &self,
        thread: Option<&str>,
        step: &serde_json::Value,
        evidence: &[String],
    ) {
        let st = self.state.clone();
        let thread = thread.map(str::to_string);
        let step = step.clone();
        let evidence = evidence.to_vec();
        let _ = tokio::task::spawn_blocking(move || {
            record_runtime_plan_step_outcome_from_state(&st, thread.as_deref(), &step, &evidence);
        })
        .await;
    }

    async fn verify_step_complete(
        &self,
        title: &str,
        criterion: &str,
        evidence: &str,
    ) -> (bool, String) {
        verify_step_complete(&self.state.http, title, criterion, evidence).await
    }

    fn reconcile_on_delivery(
        &self,
        plan: &serde_json::Value,
        delivered: &str,
    ) -> Option<Vec<serde_json::Value>> {
        // The Value↔ExecutionPlan bridge (5.D1c.4): convert the engine's opaque plan `Value` to the
        // typed `ExecutionPlan` and run the delivery reconcile. Pure — no `self.state` needed.
        plan_steps_reconciled_on_delivery(&plan_value_from(plan), delivered)
    }

    fn plan_value_from_steps(
        &self,
        goal: Option<&str>,
        steps: &[serde_json::Value],
    ) -> serde_json::Value {
        // The other half of the bridge (5.D1c.5): a fresh step list as the canonical plan Value —
        // the shape the loop reads back. Pure — no `self.state` needed.
        canonical_plan_value(goal, steps)
    }
}

/// The gateway's `ContextCompactor` (ADR 0024 inc 5, 5.D1c.6): wraps the two harness-driven
/// compaction paths — `compact_completed_step` (F3 per-step summary) and `compact_for_context_budget`
/// (Fase 1.1 token-budget checkpoint). Holds the `AppState` (a cheap Arc clone) because the budget path
/// writes the dropped span to the memory engine, and the turn's `thread_id` so that write is scoped.
/// Constructed live in run_agent_rounds.
pub(crate) struct GatewayContextCompactor {
    pub state: AppState,
    pub thread_id: Option<String>,
}

impl local_first_engine::ContextCompactor for GatewayContextCompactor {
    async fn compact(&self, messages: &mut Vec<serde_json::Value>, start: &mut usize) -> bool {
        compact_completed_step(&self.state.http, messages, start).await
    }

    async fn compact_for_budget(
        &self,
        messages: &mut Vec<serde_json::Value>,
        context_window: Option<usize>,
        memory_reads: &local_first_engine::events::TurnMemoryReadSet,
    ) -> bool {
        compact_for_context_budget(
            &self.state,
            messages,
            context_window,
            self.thread_id.as_deref(),
            memory_reads,
        )
        .await
    }
}

/// The gateway's `TurnPolicy` (ADR 0024 inc 5, 5.D1c.7): the two sync gates the loop consults —
/// workflow-route blocking (holds the turn's `CapabilityRouteDecision`, a gateway type) and provider
/// vision capability (reads the cached `ollama_capabilities`). Constructed live in run_agent_rounds.
pub(crate) struct GatewayTurnPolicy {
    pub route: CapabilityRouteDecision,
    workflow_tool_calls: std::sync::atomic::AtomicUsize,
}

impl local_first_engine::TurnPolicy for GatewayTurnPolicy {
    fn route_blocked(&self, tool: &str) -> Option<String> {
        if let CapabilityRouteDecision::Workflow {
            workflow_id,
            tool_name,
            ..
        } = &self.route
            && tool == *tool_name
            && self
                .workflow_tool_calls
                .fetch_add(1, std::sync::atomic::Ordering::Relaxed)
                > 0
        {
            return Some(format!(
                "WORKFLOW_ROUTE_ALREADY_CALLED: workflow `{workflow_id}` already called `{tool_name}` in this turn. Do not retry or change parameters. Report the first result accurately and stop."
            ));
        }
        workflow_route_blocked_tool_message(&self.route, tool)
    }

    fn route_block_ends_turn(&self) -> bool {
        matches!(self.route, CapabilityRouteDecision::Workflow { .. })
            && self
                .workflow_tool_calls
                .load(std::sync::atomic::Ordering::Relaxed)
                > 0
    }

    fn supports_vision(&self, base_url: &str, model: &str) -> bool {
        // The browser's screenshot gate: skip the image ONLY for a model the catalog confidently calls
        // text-only. `Unknown` still sends — a screenshot wasted on a blind model costs one round,
        // whereas withholding it from a model that CAN see blinds the whole browsing turn. (The user's
        // own uploads make the opposite trade: see `vision::plan_attachments`.)
        model_supports_vision(base_url, model)
    }
}

/// The engine's turn-completion judge port (ADR 0024 inc 5, Point 2a): when the loop moves into the
/// engine it asks "did the model stop with the request unfinished (and no plan)?" through this seam
/// instead of calling `task_appears_incomplete` directly. Holds an `AppState` only to reach the shared
/// HTTP client (the judge is a `memory`-role LLM call); delegates verbatim so behavior is unchanged —
/// the loop still calls the free fn until inc 5e adopts this adapter.
// Constructed live in run_agent_rounds (5.D1c.7-followup): the no-plan completion judge.
pub(crate) struct GatewayTurnCompletionJudge {
    pub state: AppState,
}

impl local_first_engine::TurnCompletionJudge for GatewayTurnCompletionJudge {
    async fn task_appears_incomplete(&self, request: &str, work: &str) -> bool {
        task_appears_incomplete(&self.state.http, request, work).await
    }
}

fn agent_output_incomplete_reason(answer: &str) -> Option<String> {
    let trimmed = answer.trim();
    if trimmed.is_empty() || trimmed == "No reply generated for the scheduled task." {
        return Some("scheduled task produced no final reply".to_string());
    }

    let plan = parse_plan_marker(trimmed);
    plan_incomplete_reason(&plan)
        .map(|reason| format!("agent output stopped before finishing: {reason}"))
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ProactiveThreadPlan {
    thread_id: Option<String>,
    workspace_id: String,
    source: String,
    channel: Option<String>,
    title: String,
    scheduled_root: Option<String>,
}

fn proactive_thread_plan(task: &TaskRecord, goal: &str) -> ProactiveThreadPlan {
    let workspace_id = task
        .input_json
        .get("workspace_id")
        .and_then(|v| v.as_str())
        .filter(|v| !v.trim().is_empty())
        .unwrap_or_else(|| task.workspace_id.as_str())
        .to_string();
    let thread_id = task
        .input_json
        .get("thread_id")
        .and_then(|v| v.as_str())
        .filter(|v| !v.trim().is_empty())
        .map(str::to_string);
    let source = task
        .input_json
        .get("thread_source")
        .or_else(|| task.input_json.get("source"))
        .and_then(|v| v.as_str())
        .filter(|v| !v.trim().is_empty())
        .unwrap_or("scheduled")
        .to_string();
    let channel = task
        .input_json
        .get("thread_channel")
        .and_then(|v| v.as_str())
        .filter(|v| !v.trim().is_empty())
        .map(str::to_string);
    let title = task
        .input_json
        .get("thread_title")
        .and_then(|v| v.as_str())
        .filter(|v| !v.trim().is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| scheduled_thread_title(goal));
    let (derived_root, derived_thread_id) = proactive_thread_scope(task.task_id.as_str(), &source);
    let scheduled_root = (thread_id.is_none()
        || thread_id.as_deref() == Some(derived_thread_id.as_str()))
    .then_some(derived_root);
    ProactiveThreadPlan {
        thread_id,
        workspace_id,
        source,
        channel,
        title,
        scheduled_root,
    }
}

fn start_proactive_visible_turn(
    state: &AppState,
    task: &TaskRecord,
    thread_id: &str,
    thread_plan: &ProactiveThreadPlan,
    goal: &str,
) -> Result<VisibleConversationTurn, LocalTaskExecutionError> {
    let visible_turn = start_visible_conversation_turn(
        state,
        thread_id,
        &thread_plan.workspace_id,
        &thread_plan.source,
        thread_plan.channel.as_deref(),
        &thread_plan.title,
        goal,
        None,
        None,
        None,
        Some(task.task_id.as_str()),
    )
    .ok_or_else(|| LocalTaskExecutionError {
        message: "could not start a visible automation turn".to_string(),
    })?;

    let store = lock_task_store(state).map_err(local_task_gateway_error)?;
    let mut persisted = store
        .get_task(&task.task_id, &task.user_id, &task.workspace_id)
        .map_err(GatewayError::task)
        .map_err(local_task_gateway_error)?
        .ok_or_else(|| LocalTaskExecutionError {
            message: "owning proactive task disappeared before execution".to_string(),
        })?;
    let mut input = persisted
        .input_json
        .as_object()
        .cloned()
        .unwrap_or_default();
    input.insert(
        "thread_id".to_string(),
        Value::String(thread_id.to_string()),
    );
    input.insert(
        "assistant_message_id".to_string(),
        Value::String(visible_turn.assistant_message_id.clone()),
    );
    persisted.input_json = Value::Object(input);
    persisted.updated_at = OffsetDateTime::now_utc();
    store
        .insert_task(&persisted)
        .map_err(GatewayError::task)
        .map_err(local_task_gateway_error)?;
    Ok(visible_turn)
}

/// Executes a scheduled/recurring "proactive prompt": runs a full agent turn on
/// the task's goal in a stable per-schedule chat thread, persists the exchange,
/// and pushes a live `/api/events` update so the desktop app surfaces it — the
/// same delivery path channel messages use. Tools stay read-only (safe by
/// default for unattended runs). Async `run_agent_turn` is driven to completion
/// via the runtime handle: this executor runs inside `spawn_blocking`, so
/// blocking on the current runtime here does not stall the async workers.
fn execute_proactive_prompt_task(
    state: &AppState,
    task: &TaskRecord,
    contract: &local_first_execution_protocol::ValidatedExecutionContract,
    control: std::sync::Arc<crate::execution_control::ExecutionAttemptControl>,
) -> Result<local_first_execution_protocol::ExecutionOutcome, LocalTaskExecutionError> {
    let goal = task.goal.clone();
    let thread_plan = proactive_thread_plan(task, &goal);

    // Scheduled tasks get a stable per-schedule thread. Evented tasks can carry
    // their owning thread explicitly (channel, connector, addon), so the visible
    // run lands where the trigger happened instead of in a generic background chat.
    let thread_id = if let Some(root) = thread_plan.scheduled_root.clone() {
        match lock_store(state) {
            Ok(store) => store
                .find_or_create_channel_thread(
                    &thread_plan.workspace_id,
                    &thread_plan.source,
                    &root,
                    &thread_plan.title,
                )
                .ok()
                .map(|thread| thread.thread_id),
            Err(_) => None,
        }
    } else {
        thread_plan.thread_id.clone()
    };
    let Some(thread_id) = thread_id else {
        return Err(LocalTaskExecutionError {
            message: "could not create the automation thread".to_string(),
        });
    };

    // Automation runs (input_json carries `automation_id`) may ACT. Three policies:
    // - `autonomous`  → the rule is marked Autonomous: side-effecting tools execute directly.
    // - `full`        → the rule needs confirmation: writes PROPOSE a confirm card.
    // - `read_only`   → check-in / curiosity runs (no automation_id): "no actions".
    let is_automation = task.input_json.get("automation_id").is_some();
    let is_autonomous = task
        .input_json
        .get("approval")
        .and_then(|v| v.as_str())
        .is_some_and(|s| s.eq_ignore_ascii_case("autonomous"));
    let policy = if is_automation && is_autonomous {
        "autonomous"
    } else if is_automation {
        "full"
    } else {
        "read_only"
    };

    // Safety boundary: scheduled/automation work must be visible in its owning
    // chat before any model/tool/browser work starts. If the durable turn cannot
    // be persisted, fail closed instead of running invisible background work.
    let visible_turn = start_proactive_visible_turn(state, task, &thread_id, &thread_plan, &goal)?;

    let request_id = agent_turn_stream_request_id(&visible_turn.assistant_message_id);
    let result = tokio::runtime::Handle::current().block_on(async {
        tokio::select! {
            biased;
            interruption = control.interrupted() => {
                tracing::info!(
                    target: "proactive::executor",
                    execution_id = %contract.as_ref().execution_id,
                    ?interruption,
                    "runtime interruption reached proactive agent turn"
                );
                abort_stream_generation(&request_id);
                Ok(None)
            }
            result = run_agent_turn_into_message(
                state,
                &thread_id,
                &goal,
                policy,
                &visible_turn.user_message_id,
                &visible_turn.assistant_message_id,
                local_first_desktop_gateway::MessageDeliveryState::Streaming,
            ) => result,
        }
    });
    let agent_result = result.ok().flatten();
    let waiting_action = agent_result
        .as_ref()
        .and_then(|result| result.actionable_cards.first())
        .map(|card| card.kind.to_string());
    let wake = agent_result.as_ref().and_then(|result| {
        wake_for_agent_stop(contract, &result.outcome.stop, waiting_action.as_deref())
    });
    let answer = agent_result.as_ref().map(|result| result.text.clone());
    let stop_failure = agent_result
        .as_ref()
        .and_then(|result| match &result.outcome.stop {
            local_first_engine::TurnStop::Failed { failure } => {
                Some(failure.redacted_detail.clone())
            }
            _ => None,
        });
    let incomplete_reason = stop_failure.or_else(|| {
        answer
            .as_deref()
            .and_then(agent_output_incomplete_reason)
            .or_else(|| {
                answer
                    .is_none()
                    .then(|| "scheduled task produced no final reply".to_string())
            })
    });

    let completed = incomplete_reason.is_none()
        && agent_result
            .as_ref()
            .is_some_and(|result| result.outcome.stop == local_first_engine::TurnStop::Completed);
    let suspended = wake.is_some();
    let blocked_reason = if suspended {
        Some("scheduled task is waiting for its durable wake".to_string())
    } else {
        incomplete_reason.clone()
    };
    let summary = blocked_reason.clone().unwrap_or_else(|| {
        if suspended {
            "Scheduled task is waiting for its durable wake.".to_string()
        } else {
            "Scheduled task executed.".to_string()
        }
    });
    let presentation = TaskExecutionPresentation {
        pending_approval: matches!(
            wake,
            Some(local_first_execution_protocol::WakeCondition::Approval { .. })
        )
        .then(|| PendingExecutorApproval {
            action: waiting_action
                .clone()
                .unwrap_or_else(|| "action card".to_string()),
            risk_level: "high".to_string(),
            data_boundary: "in-chat action card".to_string(),
            explanation: "The scheduled task is waiting for its persisted action card.".to_string(),
            inline_action_card: true,
        }),
        summary,
        checkpoint_payload: serde_json::json!({
            "kind": "proactive_prompt",
            "goal": goal,
            "thread_id": thread_id,
            "assistant_message_id": visible_turn.assistant_message_id,
            "user_message_id": visible_turn.user_message_id,
            "objective_revision": contract.as_ref().objective.as_ref().map(|objective| objective.revision),
            "awaiting_user": agent_result.as_ref().and_then(|result| result.outcome.awaiting_user.clone()),
            "answer": answer,
            "completed": completed,
            "suspended": suspended,
        }),
        checkpoint_redacted: serde_json::json!({
            "kind": "proactive_prompt",
            "completed": completed,
        }),
        chat_message: answer.clone().unwrap_or_default(),
        result_surfacing: TaskResultSurfacing::AlreadyPersisted,
        surface: SurfaceKind::Logs,
        event_kind: if completed {
            "proactive_prompt_completed".to_string()
        } else if suspended {
            "proactive_prompt_suspended".to_string()
        } else {
            "proactive_prompt_incomplete".to_string()
        },
        event_title: if completed {
            "Scheduled task completed".to_string()
        } else if suspended {
            "Scheduled task suspended".to_string()
        } else {
            "Scheduled task incomplete".to_string()
        },
        event_subtitle: if completed {
            "Scheduled proactive execution.".to_string()
        } else if suspended {
            "The execution is waiting for its registered wake condition.".to_string()
        } else {
            "Scheduled task stopped before finishing its plan.".to_string()
        },
        event_payload: serde_json::json!({ "goal": goal }),
        artifacts: vec![],
    };
    if completed {
        execution_runtime::complete_task_execution(state, task, presentation)
    } else if let Some(wake) = wake {
        execution_runtime::suspend_task_execution(state, task, contract, wake, presentation)
    } else {
        execution_runtime::fail_task_execution(
            state,
            task,
            local_first_execution_protocol::ExecutionFailure::transient(
                "proactive_prompt_incomplete",
                incomplete_reason
                    .as_deref()
                    .unwrap_or("scheduled task stopped before completing"),
            ),
            presentation,
        )
    }
}

fn scheduled_thread_sender_for_task_id(task_id: &str) -> String {
    task_id.split("@occ@").next().unwrap_or(task_id).to_string()
}

pub(crate) fn proactive_thread_scope(task_id: &str, source: &str) -> (String, String) {
    let root = scheduled_thread_sender_for_task_id(task_id);
    let thread_id = format!("channel_{source}_{root}");
    (root, thread_id)
}

fn scheduled_thread_title(goal: &str) -> String {
    let trimmed: String = goal.chars().take(48).collect();
    format!("Pianificato · {trimmed}")
}

fn execute_capability_browser_task(
    state: &AppState,
    task: &TaskRecord,
    contract: &local_first_execution_protocol::ValidatedExecutionContract,
) -> Result<local_first_execution_protocol::ExecutionOutcome, LocalTaskExecutionError> {
    let payload: CapabilityTaskPayload =
        serde_json::from_value(task.input_json.clone()).map_err(|error| {
            LocalTaskExecutionError {
                message: format!("Invalid browser capability payload: {error}"),
            }
        })?;
    let method = browser_method_for_capability_tool(&payload.call.tool_name).ok_or_else(|| {
        LocalTaskExecutionError {
            message: format!("Unsupported browser tool: {}", payload.call.tool_name),
        }
    })?;

    append_task_progress_checkpoint(
        state,
        task,
        "capability_browser_executor_started",
        SurfaceKind::Browser,
        "Browser executor",
        &format!(
            "Running capability `{}` via BrowserTaskExecutor.",
            payload.call.tool_name
        ),
        serde_json::json!({
            "kind": "capability_browser_executor_started",
            "tool": payload.call.tool_name,
            "provider": payload.call.provider_id.as_str(),
        }),
    )
    .map_err(local_task_gateway_error)?;

    let result =
        execute_persistent_browser_capability(state, task, method, payload.call.arguments)?;

    task_execution_outcome_from_executor_result(
        state,
        task,
        contract,
        "browser-capability-executor",
        &payload.call.tool_name,
        result,
    )
}

/// True when a browser client error means the single persistent sidecar process
/// is gone (broken IPC pipe, or a garbled/empty reply because the child closed
/// its stdout) and the cached handle should be dropped so the next attempt
/// respawns. `InvalidRequest` is our own serialization bug and the policy/path
/// blocks are legitimate per-call errors — none of those imply a dead process.
fn browser_error_indicates_dead_sidecar(error: &BrowserAutomationError) -> bool {
    matches!(
        error,
        BrowserAutomationError::Sidecar(_) | BrowserAutomationError::InvalidResponse(_)
    )
}

/// Fixed label for the one tab the execution surface manages per session. Using
/// a constant label (instead of a runtime-generated id) lets the planner emit
/// high-level steps while the executor keeps a stable target.
const BROWSER_MANAGED_TARGET: &str = "primary";

/// Maps a planner-level browser call onto the executor-managed tab.
///
/// The sidecar's capability tools are tab-scoped: `navigate`/`act`/`snapshot`/…
/// all require a `target_id`. But the planner emits intent ("navigate to URL",
/// "fill these fields") and cannot know a tab id that only exists at runtime. So
/// the single execution surface owns ONE managed tab (label "primary"):
/// - `navigate {url}` with no target becomes an idempotent `open {url, label}`
///   (open creates the tab on first use and re-navigates it afterwards),
/// - other tab-scoped calls get `target_id` injected,
/// - tabless calls (health/profiles/tabs/open/start/stop) pass through.
///
/// A call that already carries an explicit `target_id` is left untouched.
fn normalize_browser_call(method: BrowserMethod, mut params: Value) -> (BrowserMethod, Value) {
    let has_target = params
        .get("target_id")
        .and_then(Value::as_str)
        .is_some_and(|value| !value.is_empty());
    if has_target {
        return (method, params);
    }
    if !params.is_object() {
        params = serde_json::json!({});
    }
    match method {
        BrowserMethod::Navigate => {
            // open is idempotent on the label: creates+navigates the managed tab.
            params["label"] = serde_json::json!(BROWSER_MANAGED_TARGET);
            (BrowserMethod::Open, params)
        }
        BrowserMethod::Snapshot
        | BrowserMethod::Checkpoint
        | BrowserMethod::Restore
        | BrowserMethod::Rehydrate
        | BrowserMethod::Act
        | BrowserMethod::Screenshot
        | BrowserMethod::Console
        | BrowserMethod::Pdf
        | BrowserMethod::Focus
        | BrowserMethod::CloseTab
        | BrowserMethod::ArmFileChooser
        | BrowserMethod::RespondDialog
        | BrowserMethod::WaitDownload => {
            params["target_id"] = serde_json::json!(BROWSER_MANAGED_TARGET);
            (method, params)
        }
        BrowserMethod::Health
        | BrowserMethod::Profiles
        | BrowserMethod::Tabs
        | BrowserMethod::Open
        | BrowserMethod::Start
        | BrowserMethod::Stop => (method, params),
    }
}

/// Outcome of a call against the single shared browser sidecar.
enum SharedSidecarCall {
    /// The sidecar replied (the response may still be a browser-level error).
    Response(BrowserResponse),
    /// The sidecar process was gone; the cached handle has been dropped and the
    /// task should retry (which respawns a fresh sidecar). Carries the reason.
    SidecarLost(String),
}

/// A CDP "wedge": the sidecar IPC is healthy but its inner `connectOverCDP` to the
/// contained-computer Chromium times out. Happens when a long-lived container
/// accumulates stale CDP targets — `/json/version` still answers (so `browser_cdp_ok`
/// can't see it), yet the ws handshake hangs. The cure is recycling the container.
/// Matched conservatively on Playwright's English message (its only producer). This
/// is the gap that turned a transient wedge into the drive's hard browse failure:
/// motore #1's HTTP-only self-heal misses it too, but its warm per-thread session
/// usually predates the wedge — the drive spawns cold into it.
/// The textual signature of a CDP wedge in an error string: a `connectOverCDP` timeout.
fn cdp_wedge_signature(message: &str) -> bool {
    let message = message.to_ascii_lowercase();
    message.contains("connectovercdp") && message.contains("timeout")
}

fn browser_response_indicates_cdp_wedge(response: &BrowserResponse) -> bool {
    match response {
        BrowserResponse::Error { error, .. } => cdp_wedge_signature(&error.message),
        BrowserResponse::Success { .. } => false,
    }
}

/// Throttle container recycles so a burst of wedge responses (an agentic loop
/// retrying every round) recycles AT MOST once per window — never thrashing
/// `docker rm -f`. Returns true and arms the window when a recycle is allowed.
fn browser_recycle_throttle_ok() -> bool {
    static LAST: std::sync::OnceLock<std::sync::Mutex<Option<std::time::Instant>>> =
        std::sync::OnceLock::new();
    let cell = LAST.get_or_init(|| std::sync::Mutex::new(None));
    let Ok(mut guard) = cell.lock() else {
        return false;
    };
    let now = std::time::Instant::now();
    let allowed = guard
        .map(|last| now.duration_since(last) >= std::time::Duration::from_secs(90))
        .unwrap_or(true);
    if allowed {
        *guard = Some(now);
    }
    allowed
}

/// THE single browser execution surface (A1.3). All durable browser capability
/// execution flows through here so there is exactly one owner of the persistent
/// sidecar: this function holds `state.browser_capability_client`, lazily spawns
/// the process once, reuses it across calls/tasks, and self-heals by dropping a
/// dead handle. Any future live read-only provider must delegate here rather
/// than spawn a competing sidecar.
fn call_shared_browser_sidecar(
    state: &AppState,
    task: &TaskRecord,
    method: BrowserMethod,
    params: Value,
) -> Result<SharedSidecarCall, LocalTaskExecutionError> {
    // Map the planner-level call onto the managed tab (inject/translate target).
    let (method, params) = normalize_browser_call(method, params);
    let mut client_guard =
        state
            .browser_capability_client
            .lock()
            .map_err(|error| LocalTaskExecutionError {
                message: format!("Browser capability lock fallita: {error}"),
            })?;
    if client_guard.is_none() {
        *client_guard = Some(BrowserAutomationClient::new(
            spawn_browser_sidecar_for_task(state, task)?,
        ));
    }
    // Borrow the shared client only for the call so we can replace it afterwards
    // if the sidecar turns out to be dead.
    let call_result = {
        let client = client_guard
            .as_ref()
            .ok_or_else(|| LocalTaskExecutionError {
                message: "Browser capability not initialized.".to_string(),
            })?;
        client.call_response(method, params)
    };
    match call_result {
        // Self-heal a CDP wedge (connectOverCDP timeout despite a live sidecar):
        // recycle the contained computer once per window, drop the sidecar so the next
        // call respawns against the fresh CDP, and report SidecarLost so the caller
        // retries (the drive's agentic loop retries next round; the durable runtime
        // re-enqueues). Closes the gap `browser_cdp_ok`'s HTTP probe can't catch.
        Ok(response)
            if browser_response_indicates_cdp_wedge(&response) && browser_recycle_throttle_ok() =>
        {
            crate::sandbox::recycle_container();
            let _ = crate::sandbox::ensure_contained_computer();
            *client_guard = None;
            Ok(SharedSidecarCall::SidecarLost(
                "browser CDP wedged (connectOverCDP timeout); recycled contained computer, \
                 respawning on retry"
                    .to_string(),
            ))
        }
        Ok(response) => Ok(SharedSidecarCall::Response(response)),
        // Self-heal: a broken IPC pipe (Sidecar) or a garbled/empty reply
        // (InvalidResponse, e.g. the child closed stdout) means the single
        // persistent sidecar process is gone. Drop the dead handle so the next
        // attempt respawns a fresh one, and let the durable task runtime retry
        // instead of failing the task permanently against a corpse.
        Err(error) if browser_error_indicates_dead_sidecar(&error) => {
            *client_guard = None;
            Ok(SharedSidecarCall::SidecarLost(format!(
                "browser sidecar lost ({error}); respawning on retry"
            )))
        }
        Err(error) => Err(LocalTaskExecutionError {
            message: format!("Browser capability fallita: {error}"),
        }),
    }
}

/// Fail-closed safety gate for the durable, NON-INTERACTIVE browser capability
/// executor. Returns the refusal reason, or `None` when the call is safe to run.
///
/// The interactive guarded loop (`execute_browser_tool` + `browser_safety`) is the
/// ONLY place a browser *action* can be gated safely: it owns the live page snapshot
/// (needed to resolve the target control's label) and the per-turn Payment Approval
/// Card (the `payment_approval_id` a final purchase requires). A durable capability
/// task — materialized by the OrchestratorBrain and run by the background worker —
/// has NEITHER: there is no chat turn to carry an approval, and no snapshot to
/// evaluate against, so `browser_safety::high_risk_reason` would itself fail OPEN
/// here on an unresolved `ref`. Reusing that gate would therefore be a fail-open, not
/// a fix. So this executor must never perform a committing browser action: `Act`
/// (the sidecar's single committing/interactive surface) is refused outright, as is
/// any method carrying payment-commit intent. Page reads (snapshot/tabs/screenshot)
/// and navigation stay allowed. This is deliberately scoped to THIS pipeline and does
/// not touch the interactive `browser_safety` gate (converge, don't duplicate).
fn browser_capability_action_refusal(method: BrowserMethod, params: &Value) -> Option<String> {
    if method == BrowserMethod::Act {
        return Some(
            "refused: browser_act cannot run in a non-interactive durable task — a \
             click/type/payment can only be gated by the interactive guarded loop (live \
             snapshot + Payment Approval Card). Drive the browser inline in chat instead."
                .to_string(),
        );
    }
    // Defense in depth: refuse payment-commit intent declared or carried on ANY method.
    // A `payment_approval_id`/`vault_secret` cannot be validated without the interactive
    // approval flow, so its presence here is a rejection, never an implicit unlock.
    let declares_payment_commit = browser_safety::declared_action_class(params)
        == Some(browser_safety::ActionClass::PaymentCommit);
    let carries_payment_field = ["payment_approval_id", "vault_secret"].iter().any(|field| {
        params
            .get(*field)
            .and_then(Value::as_str)
            .is_some_and(|value| !value.trim().is_empty())
    });
    if declares_payment_commit || carries_payment_field {
        return Some(
            "refused: a payment-commit browser action cannot run in a non-interactive durable \
             task — it requires a Payment Approval Card that only the interactive guarded loop \
             can issue and validate."
                .to_string(),
        );
    }
    None
}

fn execute_persistent_browser_capability(
    state: &AppState,
    task: &TaskRecord,
    method: BrowserMethod,
    params: Value,
) -> Result<ExecutorResult, LocalTaskExecutionError> {
    // Fail-closed gate BEFORE the shared sidecar's `Act` call: this durable, headless
    // context can never present a Payment Approval Card nor a live snapshot, so a
    // committing/payment browser action is refused here rather than forwarded ungated.
    if let Some(reason) = browser_capability_action_refusal(method, &params) {
        return Err(LocalTaskExecutionError { message: reason });
    }
    let response = match call_shared_browser_sidecar(state, task, method, params.clone())? {
        SharedSidecarCall::SidecarLost(reason) => {
            return Ok(ExecutorResult::RetryableFailure { reason });
        }
        SharedSidecarCall::Response(response) => response,
    };
    match response {
        BrowserResponse::Success {
            ok: true, result, ..
        } if method == BrowserMethod::Snapshot => Ok(ExecutorResult::Checkpoint {
            payload: result.clone(),
            redacted_payload: browser_capability_redacted_checkpoint(method, &params, result),
        }),
        BrowserResponse::Success {
            ok: true, result, ..
        } => Ok(ExecutorResult::Completed { output: result }),
        BrowserResponse::Success { .. } => Ok(ExecutorResult::RetryableFailure {
            reason: "browser returned invalid success envelope".to_string(),
        }),
        BrowserResponse::Error { error, .. } if error.manual_action_required => {
            Ok(ExecutorResult::NeedsApproval {
                action: "browser.manual_action".to_string(),
                risk_level: "medium".to_string(),
                data_boundary: "local_browser".to_string(),
                explanation: error.message,
            })
        }
        BrowserResponse::Error { error, .. } => Ok(ExecutorResult::RetryableFailure {
            reason: format!("{}:{}", error.code, error.message),
        }),
    }
}

fn browser_capability_redacted_checkpoint(
    method: BrowserMethod,
    params: &Value,
    result: Value,
) -> Value {
    let method_name = serde_json::to_value(method).unwrap_or(Value::Null);
    let target_id = params.get("target_id").cloned().unwrap_or(Value::Null);
    let mut browser = serde_json::json!({
        "method": method_name,
        "target_id": target_id,
    });
    if let Some(url) = result.get("url") {
        browser["url"] = url.clone();
    }
    if let Some(snapshot) = result.get("snapshot").and_then(Value::as_str) {
        browser["snapshot_excerpt"] =
            Value::String(redact_sensitive_text(&truncate_chars(snapshot, 2_000)));
    }
    browser
}

/// Runs a `subagent.*` task through the real `SubagentTaskExecutor` (trait-based)
/// and maps its `ExecutorResult` into the canonical execution protocol.
/// (ADR 0008 pillar #3 / GAP 4: de-stub the registered executors). The runner
/// only needs the local LLM runtime.
fn execute_subagent_task(
    state: &AppState,
    task: &TaskRecord,
    contract: &local_first_execution_protocol::ValidatedExecutionContract,
) -> Result<local_first_execution_protocol::ExecutionOutcome, LocalTaskExecutionError> {
    // Pick the model that best fits THIS task's goal: the semantic stage-2 router
    // (with heuristic fallback) over the "orchestrator" role.
    let goal = task
        .input_json
        .get("goal")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let router = match resolve_role_for_task(goal, "orchestrator") {
        Some(resolved) => build_router_for_resolved(&resolved),
        None => router_for_role("orchestrator"),
    };

    let mut executor = SubagentTaskExecutor::new(router);
    let executor_id = executor.executor_id().to_string();
    let result = executor
        .execute_step(task, None)
        .map_err(|error| LocalTaskExecutionError {
            message: format!("subagent executor failed: {error}"),
        })?;
    // Reuse the shared ExecutorResult presentation mapping used by browser capabilities.
    task_execution_outcome_from_executor_result(
        state,
        task,
        contract,
        &executor_id,
        "subagent",
        result,
    )
}

/// P2: executes a non-browser `capability.*` task by building a LIVE provider
/// from the registry and dispatching through `CapabilityFacade::call_tool`.
///
/// Today MCP is wired end-to-end (the crate ships a real `McpStdioTransport`):
/// the registry connection metadata gives the command/args, the provider spawns
/// the server and speaks JSON-RPC, and the facade enforces the grant-based
/// policy before calling the tool. Composio (no real HTTP transport yet) and
/// skills (need a runner) report a clear "kind not yet wired" instead of the
/// previous blanket "unwired" — so the unlock is incremental and honest.
fn execute_capability_generic(
    state: &AppState,
    task: &TaskRecord,
    _contract: &local_first_execution_protocol::ValidatedExecutionContract,
) -> Result<local_first_execution_protocol::ExecutionOutcome, LocalTaskExecutionError> {
    let payload: CapabilityTaskPayload =
        serde_json::from_value(task.input_json.clone()).map_err(|error| {
            LocalTaskExecutionError {
                message: format!("Invalid capability payload: {error}"),
            }
        })?;
    let call = payload.call;
    let provider_id = call.provider_id.clone();
    let user = gateway_capability_user_id();
    let workspace = gateway_capability_workspace_id();

    let (kind, connection, tool_policies, policy_context) = {
        let registry = lock_capability_registry(state).map_err(local_task_gateway_error)?;
        let kind = registry
            .provider_config(&provider_id)
            .map_err(|error| LocalTaskExecutionError {
                message: format!("provider config: {error}"),
            })?
            .map(|config| config.provider_kind)
            .ok_or_else(|| LocalTaskExecutionError {
                message: format!("provider not configured: {}", provider_id.as_str()),
            })?;
        let connection = registry
            .connection_configs(&user, &workspace)
            .map_err(|error| LocalTaskExecutionError {
                message: format!("connection configs: {error}"),
            })?
            .into_iter()
            .find(|config| config.provider_id == provider_id);
        let tool_policies = registry
            .cached_tools(&provider_id)
            .map_err(|error| LocalTaskExecutionError {
                message: format!("cached tools: {error}"),
            })?
            .into_iter()
            .map(|cached| McpToolPolicy {
                tool_name: cached.tool.name,
                action: cached.tool.action,
                privacy_domains: cached.tool.privacy_domains,
                sensitivity: cached.tool.sensitivity,
            })
            .collect::<Vec<_>>();
        let policy_context = registry
            .policy_context(&user, &workspace)
            .map_err(|error| LocalTaskExecutionError {
                message: format!("policy context: {error}"),
            })?;
        (kind, connection, tool_policies, policy_context)
    };

    let result = match kind {
        CapabilityProviderKind::Mcp => {
            let connection = connection.ok_or_else(|| LocalTaskExecutionError {
                message: format!("no connection for provider {}", provider_id.as_str()),
            })?;
            let transport = build_mcp_transport(state, &connection)
                .map_err(|message| LocalTaskExecutionError { message })?;
            let mut facade =
                CapabilityFacade::new(CapabilityPolicy, InMemoryCapabilityAudit::default());
            facade.register_provider(McpCapabilityProvider::new(
                provider_id.clone(),
                true,
                transport,
                tool_policies,
            ));
            facade.call_tool(&policy_context, call)
        }
        CapabilityProviderKind::Managed => {
            // Composio: converged onto the SINGLE v3 execution path (F1.c, caposaldo #5).
            // The task-runtime used to wrap the pre-v3 `ComposioCapabilityProvider` in a
            // throwaway facade, but the facade locates the tool via `provider.list_tools()`,
            // which does `GET /tools` and parses the pre-v3 `{tools}` shape — that FAILS
            // against Composio v3 (`{items}`), so the call errored before ever executing
            // (autonomous Composio runs were broken). We now re-check the SAME deny-by-default
            // policy (`CapabilityPolicy::tool_access`, no gate duplication) against the
            // v3-sourced cached tool metadata, then execute through `composio_execute_tool` —
            // the one v3 path the chat loop already uses. `connection` is unused here now:
            // the v3 transport is resolved by `composio_transport_for` (single source).
            if let Err(reason) = authorize_managed_capability_tool(
                &tool_policies,
                &policy_context,
                &provider_id,
                call.tool_name.as_str(),
            ) {
                return execution_runtime::fail_task_execution(
                    state,
                    task,
                    local_first_execution_protocol::ExecutionFailure::policy_denied(
                        "capability_policy_denied",
                        &reason,
                    ),
                    capability_call_failed_outcome(task, &reason),
                );
            }
            composio_execute_tool(state, call.tool_name.as_str(), &call.arguments)
                .map(|output| local_first_capabilities::CapabilityCallResult {
                    provider_id: provider_id.clone(),
                    tool_name: call.tool_name.clone(),
                    output,
                })
                .map_err(|error| CapabilityError::ToolExecutionFailed(error.message))
        }
        other => {
            let presentation = capability_kind_not_wired_outcome(task, other);
            return execution_runtime::fail_task_execution(
                state,
                task,
                local_first_execution_protocol::ExecutionFailure::permanent(
                    "capability_provider_not_wired",
                    &presentation.summary,
                ),
                presentation,
            );
        }
    };

    match result {
        Ok(call_result) => execution_runtime::complete_task_execution(
            state,
            task,
            capability_call_completed_outcome(task, &call_result),
        ),
        Err(error) => {
            let reason = error.to_string();
            execution_runtime::fail_task_execution(
                state,
                task,
                local_first_execution_protocol::ExecutionFailure::transient(
                    "capability_call_failed",
                    &reason,
                ),
                capability_call_failed_outcome(task, &reason),
            )
        }
    }
}

/// Re-check the deny-by-default policy for a Managed (Composio) tool before AUTONOMOUS
/// execution by the task-runtime. Returns `Ok(())` if authorized, else a human-readable
/// denial reason. Pure (so the security gate is unit-testable without app state), and it
/// reuses the ONE canonical `CapabilityPolicy::tool_access` — no gate logic is duplicated
/// here. Fail-closed: a tool absent from the v3 catalog cache (`cached_tools`) cannot be
/// authorized, so a stale/uncached slug is denied rather than executed blindly. This is the
/// gate the old facade path enforced; it is preserved here while execution moves to the v3
/// `composio_execute_tool` (F1.c).
fn authorize_managed_capability_tool(
    tool_policies: &[McpToolPolicy],
    policy_context: &PolicyContext,
    provider_id: &CapabilityProviderId,
    tool_name: &str,
) -> Result<(), String> {
    let Some(policy) = tool_policies.iter().find(|p| p.tool_name == tool_name) else {
        return Err(format!(
            "Composio tool «{tool_name}» is not in the catalog cache — cannot authorize it \
             for autonomous execution; open the chat once to refresh the connected toolkit."
        ));
    };
    let tool = CapabilityTool {
        name: policy.tool_name.clone(),
        provider_id: provider_id.clone(),
        provider_kind: CapabilityProviderKind::Managed,
        action: policy.action,
        description: String::new(),
        privacy_domains: policy.privacy_domains.clone(),
        sensitivity: policy.sensitivity.clone(),
        input_schema: serde_json::json!({ "type": "object" }),
    };
    let decision = CapabilityPolicy.tool_access(policy_context, &tool);
    if decision.executable {
        Ok(())
    } else {
        Err(format!("denied: {}", decision.reasons.join("; ")))
    }
}

fn capability_call_completed_outcome(
    _task: &TaskRecord,
    result: &local_first_capabilities::CapabilityCallResult,
) -> TaskExecutionPresentation {
    let summary = format!("Tool `{}` eseguito.", result.tool_name);
    TaskExecutionPresentation {
        pending_approval: None,
        summary: summary.clone(),
        // Raw output stays in the (audited, non-UI) checkpoint; the redacted
        // checkpoint and chat message carry only provider/tool identifiers.
        checkpoint_payload: serde_json::json!({
            "kind": "capability_tool_completed",
            "provider": result.provider_id.as_str(),
            "tool": result.tool_name,
            "output": result.output,
        }),
        checkpoint_redacted: serde_json::json!({
            "kind": "capability_tool_completed",
            "provider": result.provider_id.as_str(),
            "tool": result.tool_name,
        }),
        chat_message: format!(
            "Ran `{}` via `{}`.",
            result.tool_name,
            result.provider_id.as_str()
        ),
        result_surfacing: TaskResultSurfacing::AppendToChat,
        surface: SurfaceKind::Logs,
        event_kind: "capability_tool_completed".to_string(),
        event_title: "Tool executed".to_string(),
        event_subtitle: summary,
        event_payload: serde_json::json!({
            "provider": result.provider_id.as_str(),
            "tool": result.tool_name,
        }),
        artifacts: vec![],
    }
}

fn capability_call_failed_outcome(task: &TaskRecord, reason: &str) -> TaskExecutionPresentation {
    TaskExecutionPresentation {
        pending_approval: None,
        summary: reason.to_string(),
        checkpoint_payload: serde_json::json!({
            "kind": "capability_tool_failed",
            "task_kind": task.kind,
            "reason": reason,
        }),
        checkpoint_redacted: serde_json::json!({
            "kind": "capability_tool_failed",
            "task_kind": task.kind,
            "reason": reason,
        }),
        chat_message: format!("The capability tool failed: {reason}"),
        result_surfacing: TaskResultSurfacing::AppendToChat,
        surface: SurfaceKind::Logs,
        event_kind: "capability_tool_failed".to_string(),
        event_title: "Tool failed".to_string(),
        event_subtitle: reason.to_string(),
        event_payload: serde_json::json!({ "task_kind": task.kind }),
        artifacts: vec![],
    }
}

fn capability_kind_not_wired_outcome(
    task: &TaskRecord,
    kind: CapabilityProviderKind,
) -> TaskExecutionPresentation {
    let reason = format!(
        "Capability execution for provider kind {kind:?} not yet wired (MCP and Composio active)."
    );
    capability_call_failed_outcome(task, &reason)
}

// ---- P4.3 Composio connect -------------------------------------------------

#[derive(Debug, Deserialize)]
struct ConnectComposioRequest {
    api_key: String,
    base_url: Option<String>,
    display_name: Option<String>,
}

#[derive(Debug, Serialize)]
struct ConnectComposioResponse {
    provider_id: String,
    tools_cached: usize,
}

fn composio_base_url(explicit: Option<String>) -> String {
    explicit
        .filter(|url| !url.trim().is_empty())
        .or_else(|| {
            env::var("HOMUN_COMPOSIO_BASE_URL")
                .ok()
                .filter(|url| !url.is_empty())
        })
        .unwrap_or_else(|| "https://backend.composio.dev/api/v3".to_string())
}

/// Registers a Composio managed provider: stores the API key as an encrypted
/// secret (only the ref lands in the registry), records provider/grant/
/// connection config, then lists the available tools through the live HTTP
/// transport and caches them so the Brain can plan with them. Composio runs in
/// the cloud, so per ADR 0009 it needs no local sandbox — approval gates govern
/// its writes.
fn connect_composio_blocking(
    state: &AppState,
    request: ConnectComposioRequest,
) -> Result<ConnectComposioResponse, GatewayError> {
    let api_key = request.api_key.trim().to_string();
    if api_key.is_empty() {
        return Err(GatewayError {
            status: StatusCode::BAD_REQUEST,
            code: "composio_api_key_required",
            message: "Composio API key must not be empty".to_string(),
        });
    }
    let base_url = composio_base_url(request.base_url);
    let display_name = request
        .display_name
        .filter(|name| !name.trim().is_empty())
        .unwrap_or_else(|| "Composio".to_string());
    let user = gateway_capability_user_id();
    let workspace = gateway_capability_workspace_id();
    let provider_id = CapabilityProviderId::new("composio");

    // Verify the key against the v3 API FIRST and count available toolkits (apps),
    // before persisting anything. A bad key must not leave a phantom "active"
    // connection behind. We go transport-direct here (v3 `{items}` shape). We cache
    // TOOLKITS (apps) for the connectors UI, not the 1000s of individual tools —
    // those are fetched per toolkit on demand.
    let transport = GatewayComposioTransport::new(base_url.clone(), api_key.clone());
    let toolkits = transport
        .request("GET", "/toolkits", None)
        .map_err(GatewayError::capability)?;
    let tools_cached = toolkits
        .get("items")
        .and_then(serde_json::Value::as_array)
        .map(|items| items.len())
        .unwrap_or(0);

    // Key verified — now persist the secret (only the ref lands in the registry)
    // and the provider/grant/connection config.
    let secret_ref = SecretRef::new(user.as_str(), workspace.as_str(), "composio", "default")
        .map_err(|error| GatewayError {
            status: StatusCode::INTERNAL_SERVER_ERROR,
            code: "secret_ref_invalid",
            message: error.to_string(),
        })?;
    state
        .secret_store
        .put(secret_ref.clone(), SecretMaterial::from_string(api_key))
        .map_err(|error| GatewayError {
            status: StatusCode::INTERNAL_SERVER_ERROR,
            code: "secret_store_failed",
            message: error.to_string(),
        })?;

    {
        let registry = lock_capability_registry(state)?;
        registry
            .upsert_provider_config(&CapabilityProviderConfig::new(
                provider_id.clone(),
                CapabilityProviderKind::Managed,
                display_name.clone(),
                true,
            ))
            .map_err(GatewayError::capability)?;
        registry
            .upsert_provider_grant(
                &CapabilityProviderGrant::new(provider_id.clone(), user.clone(), workspace.clone())
                    .with_allow_managed_cloud(true)
                    .with_privacy_domains(vec!["managed-cloud".to_string()])
                    .with_allowed_actions(vec![
                        ActionClass::Read,
                        ActionClass::WriteWithConfirmation,
                    ])
                    .with_max_autonomy_level(3),
            )
            .map_err(GatewayError::capability)?;
        registry
            .upsert_connection_config(
                &CapabilityConnectionConfig::new(
                    "composio-default",
                    provider_id.clone(),
                    user.clone(),
                    workspace.clone(),
                    display_name.clone(),
                    secret_ref.as_str(),
                )
                .with_privacy_domains(vec!["managed-cloud".to_string()])
                .with_metadata(serde_json::json!({ "base_url": base_url })),
            )
            .map_err(GatewayError::capability)?;
    }

    composio_catalog_invalidate(); // new account → next turn sees its toolkits
    Ok(ConnectComposioResponse {
        provider_id: provider_id.as_str().to_string(),
        tools_cached,
    })
}

#[derive(Debug, Serialize)]
struct ComposioToolkit {
    slug: String,
    name: String,
    managed_oauth: bool,
    no_auth: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    logo: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    description: Option<String>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    categories: Vec<String>,
}

#[derive(Debug, Serialize)]
struct ComposioToolkitsResponse {
    toolkits: Vec<ComposioToolkit>,
    total: u64,
}

/// Builds a live Composio v3 transport from the stored connection: base URL from
/// the connection metadata, API key from the encrypted secret store. Errors if
/// Composio is not connected for the active workspace.
fn composio_transport_for(state: &AppState) -> Result<GatewayComposioTransport, GatewayError> {
    let user = gateway_capability_user_id();
    let workspace = gateway_capability_workspace_id();
    let connection = {
        let registry = lock_capability_registry(state)?;
        registry
            .connection_configs(&user, &workspace)
            .map_err(GatewayError::capability)?
            .into_iter()
            .find(|config| config.provider_id.as_str() == "composio")
    }
    .ok_or_else(|| GatewayError {
        status: StatusCode::NOT_FOUND,
        code: "composio_not_connected",
        message: "Composio is not connected for this workspace".to_string(),
    })?;
    let base_url = connection
        .metadata
        .get("base_url")
        .and_then(serde_json::Value::as_str)
        .map(str::to_string)
        .unwrap_or_else(|| composio_base_url(None));
    let secret_ref = SecretRef::new(user.as_str(), workspace.as_str(), "composio", "default")
        .map_err(|error| GatewayError {
            status: StatusCode::INTERNAL_SERVER_ERROR,
            code: "secret_ref_invalid",
            message: error.to_string(),
        })?;
    let api_key = state
        .secret_store
        .get(&secret_ref)
        .map_err(|error| GatewayError {
            status: StatusCode::INTERNAL_SERVER_ERROR,
            code: "secret_get_failed",
            message: error.to_string(),
        })?
        .ok_or_else(|| GatewayError {
            status: StatusCode::NOT_FOUND,
            code: "composio_secret_missing",
            message: "Composio API key not found".to_string(),
        })?
        .expose_utf8()
        .map_err(|error| GatewayError {
            status: StatusCode::INTERNAL_SERVER_ERROR,
            code: "secret_decode_failed",
            message: error.to_string(),
        })?;
    Ok(GatewayComposioTransport::new(base_url, api_key))
}

fn composio_toolkits_blocking(state: &AppState) -> Result<ComposioToolkitsResponse, GatewayError> {
    let transport = composio_transport_for(state)?;
    let response = transport
        .request("GET", "/toolkits", None)
        .map_err(GatewayError::capability)?;
    let items = response
        .get("items")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    let total = response
        .get("total_items")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(items.len() as u64);
    let toolkits = items
        .iter()
        .filter(|item| {
            !item
                .get("deprecated")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false)
        })
        .filter_map(|item| {
            let slug = item
                .get("slug")
                .and_then(serde_json::Value::as_str)?
                .to_string();
            let name = item
                .get("name")
                .and_then(serde_json::Value::as_str)
                .unwrap_or(&slug)
                .to_string();
            let managed_oauth = item
                .get("composio_managed_auth_schemes")
                .and_then(serde_json::Value::as_array)
                .map(|schemes| {
                    schemes
                        .iter()
                        .any(|s| s.as_str().is_some_and(|s| s.eq_ignore_ascii_case("OAUTH2")))
                })
                .unwrap_or(false);
            let no_auth = item
                .get("no_auth")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false);
            // Composio v3 exposes display metadata under `meta`: logo URL, a short
            // description, and category tags (objects with a `name`, or bare strings).
            let meta = item.get("meta");
            let logo = meta
                .and_then(|m| m.get("logo"))
                .and_then(serde_json::Value::as_str)
                .filter(|s| !s.is_empty())
                .map(str::to_string);
            let description = meta
                .and_then(|m| m.get("description"))
                .and_then(serde_json::Value::as_str)
                .filter(|s| !s.is_empty())
                .map(str::to_string);
            let categories = meta
                .and_then(|m| m.get("categories"))
                .and_then(serde_json::Value::as_array)
                .map(|arr| {
                    arr.iter()
                        .filter_map(|c| {
                            c.as_str()
                                .or_else(|| c.get("name").and_then(serde_json::Value::as_str))
                                .map(str::to_string)
                        })
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            Some(ComposioToolkit {
                slug,
                name,
                managed_oauth,
                no_auth,
                logo,
                description,
                categories,
            })
        })
        .collect::<Vec<_>>();
    // Remember slug → logo URL so the logo PROXY has something to resolve against. The renderer never
    // sees these URLs as image sources (its CSP forbids remote images); it asks the gateway by slug.
    if let Ok(mut urls) = composio_logo_urls().lock() {
        for toolkit in &toolkits {
            if let Some(logo) = toolkit.logo.as_deref() {
                urls.insert(toolkit.slug.clone(), logo.to_string());
            }
        }
    }
    Ok(ComposioToolkitsResponse { toolkits, total })
}

#[derive(Debug, Deserialize)]
struct ComposioLinkRequest {
    toolkit_slug: String,
    /// Legacy: when present, run the custom API-key flow instead of managed OAuth.
    #[serde(default)]
    api_key: Option<String>,
    /// Schema-driven path: the chosen auth scheme (OAUTH2 | API_KEY | …) from the toolkit's
    /// real auth_config_details. When set, supersedes `api_key`.
    #[serde(default)]
    scheme: Option<String>,
    /// Use Composio's managed credentials for this scheme (no custom client_id/secret).
    #[serde(default)]
    managed: Option<bool>,
    /// Fields for auth_config CREATION (e.g. OAuth client_id/client_secret).
    #[serde(default)]
    credentials: Option<serde_json::Value>,
    /// Fields for connection INITIATION (e.g. an API key value).
    #[serde(default)]
    initiation: Option<serde_json::Value>,
}

#[derive(Debug, Serialize)]
struct ComposioLinkResponse {
    redirect_url: String,
    connected_account_id: String,
}

#[derive(Debug, Serialize)]
struct ComposioConnection {
    id: String,
    toolkit_slug: String,
    status: String,
}

#[derive(Debug, Serialize)]
struct ComposioConnectionsResponse {
    connections: Vec<ComposioConnection>,
}

/// The Composio "user" (entity) for connected accounts. We scope it to the
/// active workspace so a project's connected accounts are isolated per project.
fn composio_entity_id() -> String {
    // The Composio platform entity the accounts are linked under — global (base
    // workspace), matching where the connection config lives, so it resolves in any
    // project. (Was the active workspace → "non connesso" inside a project.)
    base_workspace_id()
}

/// Composio function tools to expose to the chat model, plus the subset that are
/// writes (need confirmation before running).
#[derive(Debug, Default, Clone)]
struct ComposioChatTools {
    /// OpenAI-style function tool schemas (name = tool slug).
    schemas: Vec<serde_json::Value>,
    /// Slugs classified as write/destructive actions.
    writes: std::collections::BTreeSet<String>,
    /// Toolkits CONNECTED but not ACTIVE (e.g. EXPIRED OAuth) — drive a
    /// "reconnect" hint so the agent doesn't claim it has no integration.
    inactive: Vec<String>,
}

/// Read-vs-write classification from the tool slug. Composio puts the verb
/// anywhere in the action (e.g. GMAIL_FETCH_EMAILS but also
/// GOOGLECALENDAR_EVENTS_LIST), so we tokenize and call it read only when a read
/// verb is present AND no write verb is — conservative: anything ambiguous is a
/// write that must be confirmed.
fn composio_tool_is_read(slug: &str) -> bool {
    const READ_VERBS: &[&str] = &[
        "FETCH", "GET", "LIST", "SEARCH", "READ", "FIND", "RETRIEVE", "VIEW", "DOWNLOAD", "CHECK",
        "COUNT", "QUERY", "LOOKUP", "DESCRIBE", "EXPORT",
    ];
    const WRITE_VERBS: &[&str] = &[
        "SEND",
        "CREATE",
        "DELETE",
        "UPDATE",
        "REMOVE",
        "ADD",
        "INSERT",
        "MODIFY",
        "EDIT",
        "ARCHIVE",
        "MOVE",
        "PATCH",
        "PUT",
        "POST",
        "REPLY",
        "FORWARD",
        "DRAFT",
        "TRASH",
        "MARK",
        "SET",
        "CLEAR",
        "WRITE",
        "UPLOAD",
        "IMPORT",
        "ENABLE",
        "DISABLE",
        "REVOKE",
        "GRANT",
        "CANCEL",
        "DUPLICATE",
        "RENAME",
        "PUBLISH",
    ];
    let upper = slug.to_ascii_uppercase();
    // Drop the toolkit prefix (first token), classify the action tokens.
    let action = upper.split_once('_').map(|x| x.1).unwrap_or(&upper);
    let tokens: Vec<&str> = action.split('_').collect();
    let has_write = tokens.iter().any(|t| WRITE_VERBS.contains(t));
    let has_read = tokens.iter().any(|t| READ_VERBS.contains(t));
    has_read && !has_write
}

/// Does this connector tool touch the user's CALENDAR? Used to enforce the
/// `can_see_calendar` perimeter axis at dispatch. Matches Composio toolkits
/// (GOOGLECALENDAR_*, OUTLOOK_CALENDAR_*, …) and any MCP tool whose name carries
/// "calendar". Heuristic by design — builtins are matched by exact name earlier,
/// so only connector tools ever reach this classifier.
fn tool_touches_calendar(name: &str) -> bool {
    name.to_ascii_uppercase().contains("CALENDAR")
}

/// Does this connector tool touch the user's ADDRESS BOOK / contacts? Used to
/// enforce the `can_see_contacts` perimeter axis at dispatch (Google Contacts,
/// the People API, Outlook contacts, …).
fn tool_touches_contacts(name: &str) -> bool {
    let upper = name.to_ascii_uppercase();
    upper.contains("CONTACT") || upper.contains("PEOPLE_API") || upper.contains("GOOGLE_PEOPLE")
}

/// Human-readable tool name from a Composio slug, e.g. GMAIL_SEND_EMAIL →
/// "Send email · Gmail". Used wherever a tool is shown to the user.
fn humanize_composio_tool(slug: &str) -> String {
    let parts: Vec<&str> = slug.split('_').filter(|s| !s.is_empty()).collect();
    let Some((toolkit_raw, action_parts)) = parts.split_first() else {
        return slug.to_string();
    };
    let capitalize = |w: &str| {
        let mut chars = w.chars();
        match chars.next() {
            Some(first) => {
                first.to_uppercase().collect::<String>() + &chars.as_str().to_lowercase()
            }
            None => String::new(),
        }
    };
    let toolkit = capitalize(toolkit_raw);
    if action_parts.is_empty() {
        return toolkit;
    }
    let action = capitalize(
        &action_parts
            .iter()
            .map(|w| w.to_lowercase())
            .collect::<Vec<_>>()
            .join(" "),
    );
    format!("{action} · {toolkit}")
}

/// Connected toolkits for the current entity as `(slug, is_active)`. A toolkit is
/// active if ANY of its connected accounts has status ACTIVE; connected-but-not-
/// active (e.g. EXPIRED OAuth) shows as `false` so the caller can prompt a reconnect.
fn composio_connected_toolkits(transport: &GatewayComposioTransport) -> Vec<(String, bool)> {
    let resp = transport
        .request(
            "GET",
            &format!("/connected_accounts?user_ids={}", composio_entity_id()),
            None,
        )
        .ok();
    let mut by_slug: std::collections::BTreeMap<String, bool> = std::collections::BTreeMap::new();
    if let Some(items) = resp
        .as_ref()
        .and_then(|r| r.get("items"))
        .and_then(|v| v.as_array())
    {
        for item in items {
            let active = item
                .get("status")
                .and_then(serde_json::Value::as_str)
                .is_some_and(|s| s.eq_ignore_ascii_case("ACTIVE"));
            if let Some(slug) = item
                .get("toolkit")
                .and_then(|t| t.get("slug"))
                .or_else(|| item.get("toolkit_slug"))
                .and_then(serde_json::Value::as_str)
            {
                let entry = by_slug.entry(slug.to_string()).or_insert(false);
                *entry = *entry || active;
            }
        }
    }
    by_slug.into_iter().collect()
}

type ComposioCatalogCache = std::sync::OnceLock<
    std::sync::Mutex<std::collections::HashMap<usize, (std::time::Instant, ComposioChatTools)>>,
>;

fn composio_catalog_cache() -> &'static std::sync::Mutex<
    std::collections::HashMap<usize, (std::time::Instant, ComposioChatTools)>,
> {
    static CELL: ComposioCatalogCache = std::sync::OnceLock::new();
    CELL.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

fn composio_catalog_ttl() -> std::time::Duration {
    let secs = std::env::var("HOMUN_COMPOSIO_CACHE_SECS")
        .ok()
        .and_then(|v| v.trim().parse::<u64>().ok())
        .unwrap_or(60);
    std::time::Duration::from_secs(secs)
}

/// Drop the cached connector catalog — call after any change to connected accounts so a
/// freshly connected/disconnected service is reflected on the next turn (no TTL wait).
fn composio_catalog_invalidate() {
    if let Ok(mut cache) = composio_catalog_cache().lock() {
        cache.clear();
    }
}

/// Cached wrapper over `composio_chat_tools`: that call is an N-toolkit `/tools` HTTP fan-out
/// rebuilt every chat turn. Cache per `cap` with a short TTL (HOMUN_COMPOSIO_CACHE_SECS, default
/// 60s); `composio_catalog_invalidate()` clears it on connect/link/disconnect for immediacy.
fn composio_chat_tools_cached(state: &AppState, cap: usize) -> ComposioChatTools {
    let now = std::time::Instant::now();
    if let Ok(cache) = composio_catalog_cache().lock()
        && let Some((stamped, tools)) = cache.get(&cap)
        && now.duration_since(*stamped) < composio_catalog_ttl()
    {
        return tools.clone();
    }
    let fresh = composio_chat_tools(state, cap);
    if let Ok(mut cache) = composio_catalog_cache().lock() {
        cache.insert(cap, (now, fresh.clone()));
    }
    fresh
}

/// Fetches the executable tools (with input schemas) for the connected toolkits
/// and turns them into OpenAI function schemas, capped to avoid prompt bloat.
/// Best-effort: any failure yields an empty set so chat still works.
fn composio_chat_tools(state: &AppState, cap: usize) -> ComposioChatTools {
    let mut out = ComposioChatTools::default();
    let Ok(transport) = composio_transport_for(state) else {
        return out;
    };
    let connected = composio_connected_toolkits(&transport);
    out.inactive = connected
        .iter()
        .filter(|(_, active)| !*active)
        .map(|(slug, _)| slug.clone())
        .collect();
    let slugs: Vec<String> = connected
        .into_iter()
        .filter(|(_, active)| *active)
        .map(|(slug, _)| slug)
        .collect();
    if slugs.is_empty() {
        // No ACTIVE tools, but `out.inactive` still drives the reconnect hint below.
        return out;
    }
    // Composio v3 /tools filters by the SINGULAR `toolkit_slug=` param, one
    // toolkit per request — verified empirically: `toolkits=`/`toolkit_slugs=`
    // are silently ignored (return the whole catalogue). So we query per
    // connected toolkit and merge, capping the total to avoid prompt bloat.
    let per_toolkit = cap.max(1);
    'outer: for slug in &slugs {
        let resp = match transport.request(
            "GET",
            &format!("/tools?toolkit_slug={slug}&limit={per_toolkit}"),
            None,
        ) {
            Ok(resp) => resp,
            Err(_) => continue,
        };
        let items = resp
            .get("items")
            .and_then(serde_json::Value::as_array)
            .cloned()
            .unwrap_or_default();
        for item in items {
            if out.schemas.len() >= cap {
                break 'outer;
            }
            let Some(tool_slug) = item.get("slug").and_then(serde_json::Value::as_str) else {
                continue;
            };
            if item
                .get("is_deprecated")
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false)
            {
                continue;
            }
            let description = item
                .get("description")
                .or_else(|| item.get("human_description"))
                .and_then(serde_json::Value::as_str)
                .unwrap_or("")
                .chars()
                .take(300)
                .collect::<String>();
            let parameters = item
                .get("input_parameters")
                .cloned()
                .unwrap_or_else(|| serde_json::json!({ "type": "object", "properties": {} }));
            if !composio_tool_is_read(tool_slug) {
                out.writes.insert(tool_slug.to_string());
            }
            out.schemas.push(serde_json::json!({
                "type": "function",
                "function": { "name": tool_slug, "description": description, "parameters": parameters },
            }));
        }
    }
    out
}

/// Result of a capability search: the human-readable text returned to the MODEL
/// as the tool result, plus an optional structured `card` payload that the chat
/// UI renders as clickable connect-cards (install skill / connect MCP / link
/// Composio in-chat, no Settings trip).
struct CapabilitySuggestions {
    /// Text for the model/log (used when no card is shown).
    model_text: String,
    /// `{ need, items: [...] }` for the in-chat card, or None when nothing found.
    card: Option<serde_json::Value>,
}

/// Searches MCP registry + Skill marketplace + Composio toolkits for a need and
/// returns a unified, human-readable suggestion list AND a structured card payload
/// (with everything each in-chat connect button needs to act).
async fn suggest_capabilities(state: &AppState, need: &str) -> CapabilitySuggestions {
    let need = need.trim();
    if need.is_empty() {
        return CapabilitySuggestions {
            model_text: "Specify what you want to do, so I can search for the right connectors."
                .to_string(),
            card: None,
        };
    }
    // MCP registry (async network).
    let mcp = mcp_registry::fetch_servers(&state.http, Some(need), 4)
        .await
        .unwrap_or_default();
    // Refresh the skills catalog if stale, so the search below has data.
    if let Some(path) = skills_catalog_path()
        && !skills_catalog::load_cache(&path).is_some_and(|c| skills_catalog::cache_is_fresh(&c))
    {
        let _ = skills_catalog::refresh_cache(&state.http, &path).await;
    }
    // Skills catalog + Composio toolkits (blocking work off the runtime).
    let need_owned = need.to_string();
    let st = state.clone();
    let (skills, composio): (Vec<skills_catalog::CatalogEntry>, Vec<ComposioToolkit>) =
        tokio::task::spawn_blocking(move || {
            let skills = skills_catalog_path()
                .and_then(|p| skills_catalog::load_cache(&p))
                .map(|cache| skills_catalog::search(&cache, &need_owned, None, 4))
                .unwrap_or_default();
            let terms: Vec<String> = need_owned
                .to_lowercase()
                .split_whitespace()
                .map(str::to_string)
                .collect();
            let composio = composio_toolkits_blocking(&st)
                .map(|resp| {
                    resp.toolkits
                        .into_iter()
                        .filter(|t| {
                            let hay = format!(
                                "{} {} {}",
                                t.slug,
                                t.name,
                                t.description.clone().unwrap_or_default()
                            )
                            .to_lowercase();
                            terms.iter().any(|term| hay.contains(term.as_str()))
                        })
                        .take(5)
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            (skills, composio)
        })
        .await
        .unwrap_or_default();

    let mut out = format!("Suggested connectors for: \"{need}\"\n");
    // Structured items for the clickable in-chat card (parallel to the text below).
    let mut items: Vec<serde_json::Value> = Vec::new();
    let installable: Vec<_> = mcp.iter().filter(|s| s.installable).take(4).collect();
    if !installable.is_empty() {
        out.push_str("\nMCP SERVERS (Settings → MCP Catalog):\n");
        for s in installable {
            let badge = if s.official { " [official]" } else { "" };
            out.push_str(&format!(
                "- {}{} — {} (publisher: {})\n",
                s.name,
                badge,
                s.description.chars().take(120).collect::<String>(),
                s.publisher
            ));
            // The full normalized server travels with the card so the connect
            // button can call mcpConnect (params/secrets, stdio vs http) directly.
            if let Ok(server) = serde_json::to_value(s) {
                items.push(serde_json::json!({
                    "kind": "mcp",
                    "name": s.name,
                    "description": s.description.chars().take(160).collect::<String>(),
                    "official": s.official,
                    "server": server,
                }));
            }
        }
    }
    if !skills.is_empty() {
        out.push_str("\nSKILLS (Settings → Skills → marketplace):\n");
        for s in &skills {
            out.push_str(&format!(
                "- {} — {}\n",
                s.name,
                s.description.chars().take(120).collect::<String>()
            ));
            items.push(serde_json::json!({
                "kind": "skill",
                "name": s.name,
                "description": s.description.chars().take(160).collect::<String>(),
                "slug": s.slug,
            }));
        }
    }
    if !composio.is_empty() {
        out.push_str("\nCLOUD SERVICES via Composio (Settings → Connectors → Composio):\n");
        for t in &composio {
            out.push_str(&format!("- {} ({})\n", t.name, t.slug));
            items.push(serde_json::json!({
                "kind": "composio",
                "name": t.name,
                "description": t.description.clone().unwrap_or_default().chars().take(160).collect::<String>(),
                "slug": t.slug,
            }));
        }
    }
    if items.is_empty() {
        out.push_str(
            "\nNo connectors found. Try different keywords, or add an MCP server manually.",
        );
        return CapabilitySuggestions {
            model_text: out,
            card: None,
        };
    }
    out.push_str(
        "\nPresent these options to the user, briefly explaining what each one does and how \
to connect it (the paths in parentheses). Do NOT claim you have already connected them.",
    );
    let card = serde_json::json!({ "need": need, "items": items });
    CapabilitySuggestions {
        model_text: out,
        card: Some(card),
    }
}

/// Executes a Composio tool for the current entity and returns its raw output.
/// Opt-in verbose diagnostics (set `HOMUN_DEBUG`). Off by default because these logs can echo
/// tool arguments, channel context, or Composio error bodies that may include secrets/PII.
fn verbose_debug() -> bool {
    std::env::var("HOMUN_DEBUG").is_ok()
}

fn approval_expires_at_secs() -> i64 {
    OffsetDateTime::now_utc().unix_timestamp() + 600
}

/// Register a durable remote approval. For chat-originated cards
/// `requires_source=true`: the row is not executable until the persisted
/// assistant message binds to the same approval_id marker.
fn create_pending_approval(
    state: &AppState,
    tool: &str,
    args: &serde_json::Value,
    label: &str,
    thread_id: Option<&str>,
    requires_source: bool,
) -> Option<RemoteApprovalRow> {
    let prefs = load_user_prefs();
    let channel = prefs.approval_channel.as_deref().unwrap_or("in_app");
    let target = prefs.approval_target.unwrap_or_default();
    if target.trim().is_empty() || channel == "in_app" {
        return None;
    }
    if requires_source && thread_id.is_none() {
        return None;
    }
    for _ in 0..8 {
        let raw = uuid::Uuid::new_v4().simple().to_string();
        let approval_id = format!("approval_{raw}");
        let code = raw[..6].to_uppercase();
        let expires_at = approval_expires_at_secs();
        let objective_revision = thread_id
            .and_then(|thread_id| objective_contract_for_execution(state, Some(thread_id)))
            .map(|objective| objective.revision);
        let input = RemoteApprovalInput {
            approval_id: &approval_id,
            code: &code,
            tool,
            arguments: args,
            label,
            thread_id,
            objective_revision,
            requires_source,
            expires_at,
        };
        match lock_store(state).and_then(|store| {
            store
                .create_remote_approval(&input)
                .map_err(GatewayError::store)
        }) {
            Ok(()) => {
                return Some(RemoteApprovalRow {
                    approval_id,
                    code,
                    tool: tool.to_string(),
                    arguments: args.clone(),
                    label: label.to_string(),
                    thread_id: thread_id.map(ToString::to_string),
                    objective_revision,
                    source_message_id: None,
                    requires_source,
                    status: "pending".to_string(),
                    expires_at,
                    dispatched_at: None,
                });
            }
            Err(error) => {
                if verbose_debug() {
                    eprintln!("remote approval create failed: {}", error.message);
                }
            }
        }
    }
    None
}

/// Non-consuming check: is there a live pending approval with this code? Lets
/// channel handlers treat `OK/NO <word>` as control replies only for real codes.
fn pending_approval_exists(state: &AppState, code: &str) -> bool {
    lock_store(state)
        .ok()
        .and_then(|store| store.pending_remote_approval(code).ok().flatten())
        .is_some()
}

fn approval_progress_reply(code: &str) -> String {
    format!("⏳ Ricevuto ({code}). Verifico la card salvata e avvio l'azione…")
}

fn approval_action_target(args: &serde_json::Value) -> Option<String> {
    args.get("path")
        .and_then(serde_json::Value::as_str)
        .or_else(|| args.get("to").and_then(serde_json::Value::as_str))
        .map(|value| value.chars().take(180).collect())
}

fn remote_approval_thread_status(
    approval: &RemoteApprovalRow,
    phase: &str,
    detail: Option<&str>,
) -> String {
    let target = approval_action_target(&approval.arguments)
        .map(|target| format!(" su `{target}`"))
        .unwrap_or_default();
    let detail = detail
        .filter(|text| !text.trim().is_empty())
        .map(|text| format!("\n\n{text}"))
        .unwrap_or_default();
    match phase {
        "running" => format!(
            "⏳ Approvazione Telegram ricevuta. Eseguo `{}`{}…{}",
            approval.tool, target, detail
        ),
        "executed" => format!(
            "✅ Azione approvata da Telegram eseguita: `{}`{}. Riprendo il task…{}",
            approval.tool, target, detail
        ),
        "failed" => format!(
            "⚠️ Azione approvata da Telegram fallita: `{}`{}.{}",
            approval.tool, target, detail
        ),
        _ => format!(
            "ℹ️ Stato approvazione Telegram: `{phase}` per `{}`{}.{detail}",
            approval.tool, target
        ),
    }
}

fn append_remote_approval_thread_status(
    state: &AppState,
    approval: &RemoteApprovalRow,
    phase: &str,
    detail: Option<&str>,
) {
    let Some(thread_id) = approval.thread_id.as_deref() else {
        return;
    };
    let text = remote_approval_thread_status(approval, phase, detail);
    if let Ok(store) = lock_store(state) {
        let _ =
            store.append_assistant_message(thread_id, &channel_chat_message("assistant", &text));
    }
    publish_app_event(serde_json::json!({
        "type": "thread.updated",
        "thread_id": thread_id,
        "workspace": base_workspace_id(),
    }));
}

/// Execute a confirmed pending approval (by code) → user-facing reply text. Routes MCP vs
/// Composio/send_message. Shared by the inbound-text path AND the Telegram inline-button callback.
/// 6.1b: after a confirm-gated action is approved AND executed, re-enter the agent loop on the
/// ORIGIN thread (if known) so a multi-step task CONTINUES instead of dead-stopping at the
/// `pending_confirm` break. Spawned so the caller (an HTTP handler / channel callback) returns at
/// once; the continuation streams onto the thread (the UI reattaches via `active_streams`). The
/// snapshot of `result` is taken BEFORE the spawn so no borrow escapes into the task. No-op when
/// the pending action carried no origin thread (e.g. a one-shot channel draft reply).
fn approval_resume_prompt(
    tool: &str,
    result: &str,
    approved_args: Option<&serde_json::Value>,
    source_user_text: Option<&str>,
) -> String {
    let source = source_user_text
        .map(|text| text.chars().take(1200).collect::<String>())
        .unwrap_or_else(|| "(source user request unavailable)".to_string());
    let args = approved_args
        .map(|value| value.to_string().chars().take(1600).collect::<String>())
        .unwrap_or_else(|| "{}".to_string());
    let result_snip: String = result.chars().take(1200).collect();
    format!(
        "A user-approved action has just executed in the CURRENT chat task.\n\n\
         ORIGINAL USER REQUEST:\n{source}\n\n\
         APPROVED TOOL ACTION:\n{tool}\n\n\
         APPROVED ARGUMENTS JSON:\n{args}\n\n\
         EXECUTION RESULT:\n{result_snip}\n\n\
         Continue ONLY this original request. Do not switch to any other file, path, \
         task, memory, or open loop. Do not mention or act on paths that are not in \
         the original request or approved arguments. If the approved action satisfies \
         the request, answer with a concise completion message using the exact \
         approved path/content/result. Continue with another tool only if the original \
         request clearly has unfinished steps."
    )
}

fn approval_source_user_text(
    state: &AppState,
    thread_id: &str,
    source_message_id: Option<&str>,
) -> Option<String> {
    let source_message_id = source_message_id?;
    let snapshot = lock_store(state).ok()?.messages(thread_id).ok()?;
    let source_idx = snapshot
        .messages
        .iter()
        .position(|message| message.id == source_message_id)?;
    snapshot.messages[..source_idx]
        .iter()
        .rev()
        .find(|message| message.role == "user")
        .map(|message| message.text.clone())
}

fn approval_continuation_visible_text(tool: &str) -> String {
    let tool: String = tool.trim().chars().take(80).collect();
    if tool.is_empty() {
        "Continue after the approved action.".to_string()
    } else {
        format!("Continue after approved action `{tool}`.")
    }
}

fn approval_continuation_turn_input(
    thread_id: &str,
    tool: &str,
    prompt: String,
) -> local_first_task_runtime::broker::ChatTurnInput {
    let request_id = format!(
        "approval_{}_{}",
        now_epoch_secs(),
        uuid::Uuid::new_v4().simple()
    );
    local_first_task_runtime::broker::ChatTurnInput {
        thread_id: thread_id.to_string(),
        assistant_message_id: format!("local_assistant_{request_id}"),
        request_id,
        prompt,
        visible_prompt: Some(approval_continuation_visible_text(tool)),
        images: Vec::new(),
        attachments: None,
        mode: None,
        model: None,
        source: local_first_task_runtime::broker::ChatTurnSource::Interactive,
        approval: local_first_task_runtime::broker::TurnApproval::Full,
    }
}

fn resume_thread_after_approval(
    state: &AppState,
    thread_id: Option<String>,
    tool: &str,
    result: &str,
    approved_args: Option<serde_json::Value>,
    source_message_id: Option<String>,
) {
    let Some(thread_id) = thread_id else {
        return;
    };
    let st = state.clone();
    let tool = tool.to_string();
    let result = result.to_string();
    tokio::spawn(async move {
        let source_user_text =
            approval_source_user_text(&st, &thread_id, source_message_id.as_deref());
        let prompt = approval_resume_prompt(
            &tool,
            &result,
            approved_args.as_ref(),
            source_user_text.as_deref(),
        );
        match resume_suspended_approval_turn_core(
            &st,
            &thread_id,
            true,
            &tool,
            &result,
            approved_args.as_ref(),
            &prompt,
        ) {
            Ok(Some(resumed)) => {
                publish_app_event(serde_json::json!({
                    "type": "thread.turn_resumed",
                    "thread_id": thread_id,
                    "turn_id": resumed.execution_id,
                    "revision": resumed.revision,
                }));
                return;
            }
            Ok(None) => {}
            Err(error) => {
                tracing::error!(
                    target: "approval::continuation",
                    %thread_id,
                    %tool,
                    %error,
                    "could not deliver the approved-action wake"
                );
                return;
            }
        }
        let input = approval_continuation_turn_input(&thread_id, &tool, prompt);
        if let Err(error) = enqueue_chat_turn_core(&st, &input) {
            tracing::error!(
                target: "approval::continuation",
                %thread_id,
                %tool,
                %error,
                "could not enqueue the approved-action continuation"
            );
        }
    });
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ActionableSourceResolution {
    Succeeded,
    Cancelled,
    Failed,
}

impl ActionableSourceResolution {
    fn task_status(self) -> TaskStatus {
        match self {
            Self::Succeeded => TaskStatus::Completed,
            Self::Cancelled => TaskStatus::Cancelled,
            Self::Failed => TaskStatus::Failed,
        }
    }

    fn delivery_state(self) -> local_first_desktop_gateway::MessageDeliveryState {
        match self {
            Self::Succeeded => local_first_desktop_gateway::MessageDeliveryState::Delivered,
            Self::Cancelled => local_first_desktop_gateway::MessageDeliveryState::Cancelled,
            Self::Failed => local_first_desktop_gateway::MessageDeliveryState::Failed,
        }
    }
}

fn actionable_source_error(message: impl Into<String>) -> GatewayError {
    GatewayError {
        status: StatusCode::CONFLICT,
        code: "actionable_source_resolution",
        message: message.into(),
    }
}

fn actionable_source_terminal_text(text: &str, note: &str) -> String {
    let visible = strip_display_markers(text).trim().to_string();
    if visible.is_empty() {
        note.to_string()
    } else {
        format!("{visible}\n\n{note}")
    }
}

fn actionable_claim_error(message: impl Into<String>) -> GatewayError {
    GatewayError {
        status: StatusCode::CONFLICT,
        code: "actionable_source_claim",
        message: message.into(),
    }
}

/// One-shot security boundary for every actionable side effect. In production
/// the task runtime and chat transcript share one SQLite file, so the exact
/// linked task and exact message transition together or not at all.
fn claim_actionable_source<F>(
    state: &AppState,
    thread_id: &str,
    message_id: &str,
    provenance_matches: F,
) -> Result<(), GatewayError>
where
    F: FnOnce(&str) -> bool,
{
    #[cfg(not(test))]
    {
        let user = gateway_user_id();
        let store = lock_task_store(state)?;
        store
            .with_transaction(|tx| {
                let row = tx
                    .query_row(
                        "select m.text, m.linked_task_id, c.workspace_id, t.task_json
                         from chat_messages m
                         join chat_threads c on c.thread_id = m.thread_id
                         join tasks t on t.task_id = m.linked_task_id
                           and t.user_id = ?3 and t.workspace_id = c.workspace_id
                         where m.thread_id = ?1 and m.id = ?2 and m.role = 'assistant'
                           and m.delivery_state = 'waiting_user'
                           and t.status = 'waiting_user_approval'",
                        rusqlite::params![thread_id, message_id, user.as_str()],
                        |row| {
                            Ok((
                                row.get::<_, String>(0)?,
                                row.get::<_, String>(1)?,
                                row.get::<_, String>(2)?,
                                row.get::<_, String>(3)?,
                            ))
                        },
                    )
                    .optional()?;
                let Some((text, task_id, workspace_id, task_json)) = row else {
                    return Err(TaskRuntimeError::InvalidTransition(
                        "actionable source is stale, cancelled, or already claimed".to_string(),
                    ));
                };
                if !provenance_matches(&text) {
                    return Err(TaskRuntimeError::InvalidTransition(
                        "persisted actionable card provenance does not match".to_string(),
                    ));
                }
                let mut task: TaskRecord = serde_json::from_str(&task_json)?;
                let supported = task.kind == "chat_turn"
                    || state
                        .task_executor_registry
                        .resolve(task.kind.as_str())
                        .is_some_and(|adapter| adapter.name() == "proactive_prompt");
                let exact_source = task.input_json.get("thread_id").and_then(Value::as_str)
                    == Some(thread_id)
                    && task
                        .input_json
                        .get("assistant_message_id")
                        .and_then(Value::as_str)
                        == Some(message_id);
                if !supported || task.status != TaskStatus::WaitingUserApproval || !exact_source {
                    return Err(TaskRuntimeError::InvalidTransition(
                        "linked task does not own this waiting actionable source".to_string(),
                    ));
                }
                task.status = TaskStatus::Running;
                task.blocked_reason = Some("actionable side effect claimed".to_string());
                task.updated_at = OffsetDateTime::now_utc();
                let changed_task = tx.execute(
                    "update tasks set status = 'running', blocked_reason = ?1,
                        updated_at = ?2, task_json = ?3
                     where task_id = ?4 and user_id = ?5 and workspace_id = ?6
                       and status = 'waiting_user_approval'",
                    rusqlite::params![
                        task.blocked_reason,
                        task.updated_at.unix_timestamp(),
                        serde_json::to_string(&task)?,
                        task_id,
                        user.as_str(),
                        workspace_id,
                    ],
                )?;
                let changed_message = tx.execute(
                    "update chat_messages set delivery_state = 'retrying'
                     where thread_id = ?1 and id = ?2 and linked_task_id = ?3
                       and delivery_state = 'waiting_user'",
                    rusqlite::params![thread_id, message_id, task_id],
                )?;
                if changed_task != 1 || changed_message != 1 {
                    return Err(TaskRuntimeError::InvalidTransition(
                        "actionable source claim lost a concurrent race".to_string(),
                    ));
                }
                Ok(())
            })
            .map_err(|error| actionable_claim_error(error.to_string()))
    }

    #[cfg(test)]
    {
        let user = gateway_user_id();
        let task_store = lock_task_store(state)?;
        let chat_store = lock_store(state)?;
        let message = chat_store
            .message(thread_id, message_id)
            .map_err(GatewayError::store)?
            .ok_or_else(|| actionable_claim_error("actionable source message is missing"))?;
        if message.role != "assistant"
            || message.delivery_state
                != local_first_desktop_gateway::MessageDeliveryState::WaitingUser
            || !provenance_matches(&message.text)
        {
            return Err(actionable_claim_error(
                "actionable source is stale or provenance does not match",
            ));
        }
        let task_id = message
            .linked_task_id
            .as_deref()
            .ok_or_else(|| actionable_claim_error("actionable source has no linked task"))?;
        let workspace = WorkspaceId::new(
            chat_store
                .workspace_for_thread(thread_id)
                .map_err(GatewayError::store)?,
        );
        let mut task = task_store
            .get_task(&TaskId::new(task_id), &user, &workspace)
            .map_err(GatewayError::task)?
            .ok_or_else(|| actionable_claim_error("linked actionable task is missing"))?;
        let supported = task.kind == "chat_turn"
            || state
                .task_executor_registry
                .resolve(task.kind.as_str())
                .is_some_and(|adapter| adapter.name() == "proactive_prompt");
        let exact_source = task.input_json.get("thread_id").and_then(Value::as_str)
            == Some(thread_id)
            && task
                .input_json
                .get("assistant_message_id")
                .and_then(Value::as_str)
                == Some(message_id);
        if !supported || task.status != TaskStatus::WaitingUserApproval || !exact_source {
            return Err(actionable_claim_error(
                "linked task does not own this waiting actionable source",
            ));
        }
        task.status = TaskStatus::Running;
        task.blocked_reason = Some("actionable side effect claimed".to_string());
        task.updated_at = OffsetDateTime::now_utc();
        task_store.insert_task(&task).map_err(GatewayError::task)?;
        if !chat_store
            .set_message_delivery_state(
                thread_id,
                message_id,
                local_first_desktop_gateway::MessageDeliveryState::Retrying,
            )
            .map_err(GatewayError::store)?
        {
            return Err(actionable_claim_error(
                "actionable source claim lost a concurrent race",
            ));
        }
        Ok(())
    }
}

/// Resolves the exact durable chat turn which owns an actionable assistant card.
///
/// Canonical approval sources remain non-terminal until their typed wake is
/// delivered. Legacy cards without a journal retain the old terminalize-then-
/// enqueue behavior during migration. New broker turns carry `linked_task_id`;
/// legacy cards may fall back only to the exact source pair stored in task input.
fn resolve_actionable_source<F>(
    state: &AppState,
    thread_id: &str,
    message_id: &str,
    rewrite: F,
    resolution: ActionableSourceResolution,
) -> Result<(), GatewayError>
where
    F: FnOnce(&str) -> String,
{
    let (message, workspace_id) = {
        let store = lock_store(state)?;
        let message = store
            .message(thread_id, message_id)
            .map_err(GatewayError::store)?
            .ok_or_else(|| actionable_source_error("actionable source message is missing"))?;
        if message.role != "assistant" {
            return Err(actionable_source_error(
                "actionable source message is not an assistant reply",
            ));
        }
        let workspace_id = store
            .workspace_for_thread(thread_id)
            .map_err(GatewayError::store)?;
        (message, workspace_id)
    };
    let user = gateway_user_id();
    let workspace = WorkspaceId::new(workspace_id);
    let task_id = {
        let store = lock_task_store(state)?;
        if let Some(task_id) = message.linked_task_id.as_deref() {
            TaskId::new(task_id)
        } else {
            store
                .list_tasks(&user, &workspace)
                .map_err(GatewayError::task)?
                .into_iter()
                .find(|task| {
                    task.kind == "chat_turn"
                        && task.input_json.get("thread_id").and_then(Value::as_str)
                            == Some(thread_id)
                        && task
                            .input_json
                            .get("assistant_message_id")
                            .and_then(Value::as_str)
                            == Some(message_id)
                })
                .map(|task| task.task_id)
                .ok_or_else(|| {
                    actionable_source_error("no exact legacy chat turn owns this actionable card")
                })?
        }
    };

    let canonical_resume;
    {
        let store = lock_task_store(state)?;
        let mut task = store
            .get_task(&task_id, &user, &workspace)
            .map_err(GatewayError::task)?
            .ok_or_else(|| actionable_source_error("linked actionable source task is missing"))?;
        let supported_persisted_bubble = task.kind == "chat_turn"
            || state
                .task_executor_registry
                .resolve(task.kind.as_str())
                .is_some_and(|adapter| adapter.name() == "proactive_prompt");
        let lifecycle_matches = match resolution {
            ActionableSourceResolution::Cancelled => {
                (task.status == TaskStatus::WaitingUserApproval
                    && message.delivery_state
                        == local_first_desktop_gateway::MessageDeliveryState::WaitingUser)
                    || (task.status == TaskStatus::Running
                        && message.delivery_state
                            == local_first_desktop_gateway::MessageDeliveryState::Retrying)
            }
            ActionableSourceResolution::Succeeded | ActionableSourceResolution::Failed => {
                task.status == TaskStatus::Running
                    && message.delivery_state
                        == local_first_desktop_gateway::MessageDeliveryState::Retrying
            }
        };
        let matches_source = supported_persisted_bubble
            && lifecycle_matches
            && task.input_json.get("thread_id").and_then(Value::as_str) == Some(thread_id)
            && task
                .input_json
                .get("assistant_message_id")
                .and_then(Value::as_str)
                == Some(message_id);
        if !matches_source {
            return Err(actionable_source_error(
                "linked task does not own the actionable source message",
            ));
        }
        canonical_resume = store
            .pending_execution_wakes(user.as_str(), workspace.as_str(), Some(thread_id))
            .map_err(GatewayError::task)?
            .into_iter()
            .any(|wake| {
                wake.execution_id == task.task_id.as_str()
                    && matches!(
                        wake.condition,
                        local_first_execution_protocol::WakeCondition::Approval { .. }
                    )
            });
        if canonical_resume {
            task.status = TaskStatus::Running;
            task.blocked_reason = Some("approval decision committed; wake pending".to_string());
        } else {
            task.status = resolution.task_status();
            task.blocked_reason = match resolution {
                ActionableSourceResolution::Succeeded => None,
                ActionableSourceResolution::Cancelled => {
                    Some("actionable card cancelled".to_string())
                }
                ActionableSourceResolution::Failed => {
                    Some("actionable card execution failed".to_string())
                }
            };
            task.clear_lease();
            store.release_resources(&task).map_err(GatewayError::task)?;
        }
        task.updated_at = OffsetDateTime::now_utc();
        store.insert_task(&task).map_err(GatewayError::task)?;
    }

    let rewritten = rewrite(&message.text);
    let remote_approval_id =
        remote_approval_intent_from_raw_text(&message.text).and_then(|intent| intent.approval_id);
    let store = lock_store(state)?;
    if resolution != ActionableSourceResolution::Cancelled
        && let Some(approval_id) = remote_approval_id.as_deref()
    {
        let _ = store.supersede_remote_approval(approval_id);
    }
    store
        .set_message_text(thread_id, message_id, &rewritten)
        .map_err(GatewayError::store)?;
    let delivery_state = if canonical_resume {
        local_first_desktop_gateway::MessageDeliveryState::Retrying
    } else {
        resolution.delivery_state()
    };
    if !store
        .set_message_delivery_state(thread_id, message_id, delivery_state)
        .map_err(GatewayError::store)?
    {
        return Err(actionable_source_error(
            "actionable source message could not transition delivery state",
        ));
    }
    publish_app_event(serde_json::json!({
        "type": "thread.updated",
        "thread_id": thread_id,
        "workspace": base_workspace_id(),
    }));
    drop(store);
    if canonical_resume && resolution != ActionableSourceResolution::Succeeded {
        let (result, prompt) = match resolution {
            ActionableSourceResolution::Cancelled => (
                "declined",
                "The user declined the requested action. Continue the same objective without executing it and explain the safe next step.",
            ),
            ActionableSourceResolution::Failed => (
                "failed",
                "The approved action failed. Continue the same objective from the durable checkpoint, report the failure accurately, and do not claim it succeeded.",
            ),
            ActionableSourceResolution::Succeeded => unreachable!(),
        };
        resume_suspended_approval_turn_core(
            state, thread_id, false, "approval", result, None, prompt,
        )
        .map_err(|error| actionable_source_error(error.to_string()))?
        .ok_or_else(|| actionable_source_error("canonical approval wake disappeared"))?;
    }
    Ok(())
}

/// Once an endpoint has proved a request came from its exact persisted card,
/// every terminal executor error must release that source before being returned
/// to the caller. This keeps a retryable UI error from becoming a permanent
/// `WaitingUserApproval`/`ThreadBusy` deadlock.
fn terminal_actionable_execution_error(
    state: &AppState,
    thread_id: Option<&str>,
    message_id: Option<&str>,
    code: &'static str,
    message: impl Into<String>,
    source_note: &str,
) -> GatewayError {
    if let (Some(thread_id), Some(message_id)) = (thread_id, message_id) {
        let _ = resolve_actionable_source(
            state,
            thread_id,
            message_id,
            |text| actionable_source_terminal_text(text, source_note),
            ActionableSourceResolution::Failed,
        );
    }
    GatewayError {
        status: StatusCode::INTERNAL_SERVER_ERROR,
        code,
        message: message.into(),
    }
}

fn cancel_pending_remote_approval(state: &AppState, code: &str) -> bool {
    let pending = match lock_store(state)
        .ok()
        .and_then(|store| store.pending_remote_approval(code).ok().flatten())
    {
        Some(pending) => pending,
        None => return false,
    };
    if pending.requires_source {
        let (Some(thread_id), Some(message_id)) = (
            pending.thread_id.as_deref(),
            pending.source_message_id.as_deref(),
        ) else {
            return false;
        };
        if resolve_actionable_source(
            state,
            thread_id,
            message_id,
            |text| actionable_source_terminal_text(text, "Action cancelled."),
            ActionableSourceResolution::Cancelled,
        )
        .is_err()
        {
            return false;
        }
    }
    lock_store(state)
        .ok()
        .and_then(|store| store.cancel_remote_approval_by_code(code).ok())
        .unwrap_or(false)
}

async fn execute_pending_approval(state: &AppState, code: &str) -> String {
    let pending = match lock_store(state)
        .ok()
        .and_then(|store| store.pending_remote_approval(code).ok().flatten())
    {
        Some(row) => row,
        None => return format!("Code {code} not valid or expired."),
    };
    if let (Some(thread_id), Some(approved_revision)) =
        (pending.thread_id.as_deref(), pending.objective_revision)
    {
        let current_revision = objective_contract_for_execution(state, Some(thread_id))
            .map(|objective| objective.revision);
        if current_revision != Some(approved_revision) {
            return format!(
                "Approval {code} belongs to objective revision {approved_revision}, but the task objective has changed. Review and approve the current plan instead."
            );
        }
    }
    match lock_store(state).ok().and_then(|store| {
        store
            .claim_remote_approval(&pending.approval_id)
            .ok()
            .flatten()
    }) {
        Some(claimed) => {
            if claimed.requires_source {
                let (Some(thread_id), Some(message_id)) = (
                    claimed.thread_id.as_deref(),
                    claimed.source_message_id.as_deref(),
                ) else {
                    if let Ok(store) = lock_store(state) {
                        let _ = store.complete_remote_approval(&claimed.approval_id, "failed");
                    }
                    return format!(
                        "Approval {code} is missing its exact source card; no action was executed."
                    );
                };
                let source_claim = claim_actionable_source(state, thread_id, message_id, |text| {
                    if claimed.tool.starts_with("mcp__") {
                        mcp_confirm_matches_approval(
                            text,
                            &claimed.approval_id,
                            &claimed.tool,
                            &claimed.arguments,
                        )
                    } else {
                        confirm_marker_matches_approval(
                            text,
                            COMPOSIO_CONFIRM_OPEN,
                            COMPOSIO_CONFIRM_CLOSE,
                            &claimed.approval_id,
                            &claimed.tool,
                            &claimed.arguments,
                        )
                    }
                });
                if let Err(error) = source_claim {
                    if let Ok(store) = lock_store(state) {
                        let _ = store.complete_remote_approval(&claimed.approval_id, "failed");
                    }
                    append_remote_approval_thread_status(
                        state,
                        &claimed,
                        "failed",
                        Some("Source card was stale, cancelled, or already claimed."),
                    );
                    return format!(
                        "Approval {code} rejected before execution: {}",
                        error.message
                    );
                }
            }
            append_remote_approval_thread_status(state, &claimed, "running", None);
            let tool = claimed.tool.clone();
            let args = claimed.arguments.clone();
            let args_for_resume = claimed.arguments.clone();
            let thread_id = claimed.thread_id.clone();
            let source_message_id = claimed.source_message_id.clone();
            let st = state.clone();
            let tool_for_run = tool.clone();
            let result: Result<serde_json::Value, String> =
                tokio::task::spawn_blocking(move || {
                    if let Some((prov, mtool)) = parse_mcp_chat_name(&tool_for_run) {
                        run_mcp_chat_tool(&st, &prov, &mtool, args.clone())
                            .map_err(|e| e.to_string())
                    } else {
                        composio_execute_tool(&st, &tool_for_run, &args).map_err(|e| e.message)
                    }
                })
                .await
                .unwrap_or_else(|_| Err("execution interrupted".to_string()));
            match result {
                Ok(value) => match composio_execution_error(&value) {
                    None => {
                        let source_resolved = match (
                            claimed.thread_id.as_deref(),
                            claimed.source_message_id.as_deref(),
                        ) {
                            (Some(thread_id), Some(message_id)) => resolve_actionable_source(
                                state,
                                thread_id,
                                message_id,
                                |text| {
                                    if claimed.tool.starts_with("mcp__") {
                                        rewrite_mcp_confirm_to_done(text, &claimed.tool)
                                    } else {
                                        rewrite_confirm_to_done(text, &claimed.tool)
                                    }
                                },
                                ActionableSourceResolution::Succeeded,
                            ),
                            _ => Ok(()),
                        };
                        if let Ok(store) = lock_store(state) {
                            let _ =
                                store.complete_remote_approval(&claimed.approval_id, "executed");
                        }
                        if let Err(error) = source_resolved {
                            append_remote_approval_thread_status(
                                state,
                                &claimed,
                                "executed",
                                Some("Tool completed, but its source turn could not be resolved."),
                            );
                            return format!(
                                "⚠️ Done ({code}), but the source turn needs recovery: {}",
                                error.message
                            );
                        }
                        append_remote_approval_thread_status(
                            state,
                            &claimed,
                            "executed",
                            Some("Tool completato; sto riaprendo il contesto del thread."),
                        );
                        // 6.1b: the action ran out-of-band after the turn died at `pending_confirm`
                        // — resume the origin thread so the multi-step task keeps going.
                        resume_thread_after_approval(
                            state,
                            thread_id,
                            &tool,
                            &value.to_string(),
                            Some(args_for_resume),
                            source_message_id,
                        );
                        format!("✅ Done ({code}).")
                    }
                    Some(err) => {
                        if let (Some(thread_id), Some(message_id)) = (
                            claimed.thread_id.as_deref(),
                            claimed.source_message_id.as_deref(),
                        ) {
                            let _ = resolve_actionable_source(
                                state,
                                thread_id,
                                message_id,
                                |text| actionable_source_terminal_text(text, "Action failed."),
                                ActionableSourceResolution::Failed,
                            );
                        }
                        if let Ok(store) = lock_store(state) {
                            let _ = store.complete_remote_approval(&claimed.approval_id, "failed");
                        }
                        append_remote_approval_thread_status(state, &claimed, "failed", Some(&err));
                        format!("⚠️ Failed ({code}): {err}")
                    }
                },
                Err(e) => {
                    if let (Some(thread_id), Some(message_id)) = (
                        claimed.thread_id.as_deref(),
                        claimed.source_message_id.as_deref(),
                    ) {
                        let _ = resolve_actionable_source(
                            state,
                            thread_id,
                            message_id,
                            |text| actionable_source_terminal_text(text, "Action failed."),
                            ActionableSourceResolution::Failed,
                        );
                    }
                    if let Ok(store) = lock_store(state) {
                        let _ = store.complete_remote_approval(&claimed.approval_id, "failed");
                    }
                    append_remote_approval_thread_status(state, &claimed, "failed", Some(&e));
                    format!("⚠️ Error ({code}): {e}")
                }
            }
        }
        None => format!("Code {code} not valid or expired."),
    }
}

/// POST an outbound message to a channel sidecar WITH an inline keyboard (Telegram only).
/// `buttons` = `[[label, callback_data], …]`.
async fn channel_send_buttons_classified(
    state: &AppState,
    port: u16,
    recipient: &str,
    text: &str,
    buttons: Vec<[String; 2]>,
) -> Result<(), ChannelSendFailure> {
    let url = format!("http://127.0.0.1:{port}/send");
    let response = state
        .http
        .post(&url)
        .timeout(std::time::Duration::from_secs(30))
        .json(&serde_json::json!({ "recipient": recipient, "text": text, "buttons": buttons }))
        .send()
        .await
        .map_err(|error| ChannelSendFailure {
            kind: if error.is_connect() {
                ChannelSendFailureKind::ConnectFailedBeforeDispatch
            } else {
                ChannelSendFailureKind::UnknownRemoteOutcome
            },
            message: format!("sidecar unreachable: {error}"),
        })?;
    if response.status().is_success() {
        Ok(())
    } else {
        Err(ChannelSendFailure {
            kind: channel_send_failure_kind_for_status(response.status()),
            message: format!("sidecar /send responded {}", response.status()),
        })
    }
}

fn remote_approval_effect_request(
    approval: &RemoteApprovalRow,
    thread_id: &str,
) -> crate::effect_host::EffectRequest {
    crate::effect_host::EffectRequest::adapter_output(
        "channel.remote_approval",
        approval.approval_id.clone(),
        local_first_execution_protocol::EffectClass::ExternalWrite,
        serde_json::json!({
            "thread_id": thread_id,
            "approval_id": approval.approval_id,
            "label": approval.label,
        }),
    )
}

async fn dispatch_remote_approval(
    state: &AppState,
    contract: &local_first_execution_protocol::ValidatedExecutionContract,
    projection_claim: &local_first_task_runtime::ProjectionClaim,
    approval: &RemoteApprovalRow,
) -> Result<ChannelProjectionDelivery, String> {
    let prefs = load_user_prefs();
    let channel = prefs
        .approval_channel
        .as_deref()
        .unwrap_or("in_app")
        .to_string();
    let target = prefs.approval_target.unwrap_or_default();
    if target.trim().is_empty() || channel == "in_app" {
        return Ok(ChannelProjectionDelivery::NotApplicable);
    }
    let thread_id = approval
        .thread_id
        .as_deref()
        .ok_or_else(|| "remote approval dispatch has no thread".to_string())?;
    if contract.as_ref().scope.thread_id.as_deref() != Some(thread_id) {
        return Err("remote approval thread does not match execution scope".to_string());
    }
    if !matches!(channel.as_str(), "telegram" | "whatsapp") {
        return Ok(ChannelProjectionDelivery::NotApplicable);
    }
    let effect_host = crate::effect_host::EffectHost::for_projection(
        state.task_store.as_ref(),
        contract,
        projection_claim,
    );
    let lease = match effect_host.begin(remote_approval_effect_request(approval, thread_id))? {
        crate::effect_host::EffectDecision::Replay(receipt) => {
            return Ok(ChannelProjectionDelivery::Delivered(serde_json::json!({
                "receipt_ref": receipt.receipt_ref.as_ref(),
                "channel": channel,
                "status": "completed",
            })));
        }
        crate::effect_host::EffectDecision::Resolve(receipt) => {
            return Ok(ChannelProjectionDelivery::Pending(receipt.receipt_ref));
        }
        crate::effect_host::EffectDecision::Execute(lease) => lease,
    };
    let code = approval.code.as_str();
    let send_result = match channel.as_str() {
        "telegram" => {
            let text = format!(
                "🔐 Homun is asking for your confirmation:\n{}\n\n(or reply: OK {code} / NO {code} — expires in 10 min)",
                approval.label
            );
            let buttons = vec![
                ["✅ Authorize".to_string(), format!("approve:{code}")],
                ["❌ Cancel".to_string(), format!("cancel:{code}")],
            ];
            telegram_send_buttons_with_rebind(state, target.trim(), &text, buttons).await
        }
        "whatsapp" => {
            let text = format!(
                "🔐 Homun is asking for your confirmation:\n{}\n\nAuthorize: OK {code}\nCancel: NO {code}\n(expires in 10 minutes)",
                approval.label
            );
            channel_send_classified(state, WHATSAPP_HTTP_PORT, target.trim(), &text).await
        }
        _ => unreachable!("approval channel was validated before receipt preparation"),
    };
    if let Err(error) = send_result {
        let detail = redact_sensitive_text(&error.message);
        if error.kind == ChannelSendFailureKind::UnknownRemoteOutcome {
            let receipt = effect_host.mark_uncertain_with_evidence(
                &lease,
                &serde_json::json!({
                    "channel": channel,
                    "recipient_fingerprint": recipient_fingerprint(target.trim()),
                    "approval_id": approval.approval_id,
                    "attempted": true,
                }),
            )?;
            return Ok(ChannelProjectionDelivery::Pending(receipt.receipt_ref));
        }
        effect_host.release_not_applied(&lease, error.kind.as_str(), &detail)?;
        return Err(format!(
            "channel/{channel} approval was verified not applied: {detail}"
        ));
    }
    let receipt = effect_host.complete(
        &lease,
        &serde_json::json!({"delivered": true}),
        &serde_json::json!({
            "channel": channel,
            "recipient_fingerprint": recipient_fingerprint(target.trim()),
            "approval_id": approval.approval_id,
        }),
    )?;
    Ok(ChannelProjectionDelivery::Delivered(serde_json::json!({
        "receipt_ref": receipt.receipt_ref.as_ref(),
        "channel": channel,
        "status": "completed",
    })))
}

/// Parse a remote-approval control reply: `OK 7F3` / `SI 7F3` (approve) or `NO 7F3` (cancel).
/// Returns `(approve, code)`. Tolerant of leading emoji/spacing; case-insensitive.
fn parse_approval_reply(text: &str) -> Option<(bool, String)> {
    let t = text.trim();
    let mut it = t.split_whitespace();
    let verb = it.next()?.to_ascii_uppercase();
    let code = it.next()?.trim().to_ascii_uppercase();
    if code.is_empty() {
        return None;
    }
    match verb.as_str() {
        "OK" | "SI" | "SÌ" | "YES" | "APPROVA" => Some((true, code)),
        "NO" | "ANNULLA" | "CANCEL" => Some((false, code)),
        _ => None,
    }
}

fn send_message_tool_schema() -> serde_json::Value {
    serde_json::json!({
        "type": "function",
        "function": {
            "name": "send_message",
            "description": "Send a message on a connected channel of the user (WhatsApp or Telegram). Use it for \"send/write/forward me a message\". The recipient MUST be an explicit number or chat ID (for «to me» ask for the number if you don't know it, do NOT make it up). Sending requires the user's confirmation before it goes out.",
            "parameters": {
                "type": "object",
                "properties": {
                    "channel": { "type": "string", "enum": ["whatsapp", "telegram"], "description": "Channel to send on" },
                    "to": { "type": "string", "description": "Recipient: number (e.g. 39333…) or chat ID. NOT a generic name." },
                    "text": { "type": "string", "description": "Message text" }
                },
                "required": ["channel", "to", "text"]
            }
        }
    })
}

/// Routes the agent's `send_message` tool (confirmed via the standard write-confirm card) to
/// the channel sidecar. The recipient must be an explicit id/number — a bare name that isn't
/// id-like is refused so the agent asks the user instead of guessing. Returns a Composio-shaped
/// `{successful, …}` value so the existing confirm card + result handling work unchanged.
fn execute_send_message(
    state: &AppState,
    args: &serde_json::Value,
) -> Result<serde_json::Value, GatewayError> {
    let channel = args
        .get("channel")
        .and_then(|v| v.as_str())
        .unwrap_or("whatsapp")
        .trim()
        .to_lowercase();
    let to = args
        .get("to")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim()
        .to_string();
    let text = args
        .get("text")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim()
        .to_string();
    if to.is_empty() || text.is_empty() {
        return Ok(serde_json::json!({
            "successful": false,
            "error": "The recipient (to) and the text (text) are required."
        }));
    }
    let looks_like_id =
        to.chars().any(|c| c.is_ascii_digit()) || to.contains('@') || to.starts_with('+');
    if !looks_like_id {
        return Ok(serde_json::json!({
            "successful": false,
            "error": format!("Recipient «{to}» is ambiguous: pass a number or a chat ID, not just the name.")
        }));
    }
    let port = if channel == "telegram" {
        TELEGRAM_HTTP_PORT
    } else {
        WHATSAPP_HTTP_PORT
    };
    let st = state.clone();
    let recipient = to.clone();
    let body = text.clone();
    let sent = tokio::runtime::Handle::current()
        .block_on(async move { channel_send_classified(&st, port, &recipient, &body).await });
    match sent {
        Ok(()) => {
            Ok(serde_json::json!({ "successful": true, "data": { "channel": channel, "to": to } }))
        }
        Err(error) => Ok(serde_json::json!({
            "successful": false,
            "unknown_remote_outcome": error.kind == ChannelSendFailureKind::UnknownRemoteOutcome,
            "error": format!("Send failed: {}", error.message),
        })),
    }
}

fn composio_execute_tool(
    state: &AppState,
    tool: &str,
    arguments: &serde_json::Value,
) -> Result<serde_json::Value, GatewayError> {
    // `send_message` is our own channel-send pseudo-tool (not Composio): route it before
    // touching the Composio transport, so it works even without Composio configured.
    if tool == "send_message" {
        return execute_send_message(state, arguments);
    }
    let transport = composio_transport_for(state)?;
    // Diagnostic (opt-in: HOMUN_DEBUG): surface exactly what we send so date/arg bugs are
    // visible in the log. Off by default — args can carry message bodies / PII.
    if verbose_debug() {
        eprintln!(
            "composio/execute tool={tool} args={}",
            arguments.to_string().chars().take(600).collect::<String>()
        );
    }
    transport
        .request(
            "POST",
            &format!("/tools/execute/{tool}"),
            Some(serde_json::json!({
                "user_id": composio_entity_id(),
                "arguments": arguments,
            })),
        )
        .map_err(GatewayError::capability)
}

/// Composio's `/tools/execute` returns HTTP 200 even when the tool FAILED,
/// signalling via `successful: false` (+ an `error` message). Returns the error on
/// a failed execution so we never report a non-action as "done" (the real bug: a
/// calendar add/delete that silently failed but showed "Azione eseguita").
/// Maps a connector error message to an ACTIONABLE instruction for the model — so a
/// broken integration becomes "reconnect"/"rate-limited", not a vague failure.
/// Actionable category of a connector tool failure, classified from the error
/// text (heuristic — providers don't return a stable machine code). Shared by the
/// Composio and MCP error paths so a broken connector tells the user WHAT TO DO
/// (reconnect / wait / re-grant) instead of dumping a raw error.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ConnectorErrorKind {
    /// 401 / expired token / no connected account → reconnect.
    Auth,
    /// 429 / quota → wait and retry later.
    RateLimit,
    /// 403 / missing scope → reconnect granting more permissions.
    Forbidden,
    /// transport down / unreachable / connection closed → the service/server is offline.
    Unavailable,
}

fn classify_connector_error(error: &str) -> Option<ConnectorErrorKind> {
    let e = error.to_lowercase();
    if e.contains("401")
        || e.contains("unauthorized")
        || e.contains("expired")
        || e.contains("invalid_grant")
        || e.contains("not connected")
        || e.contains("no connected account")
    {
        Some(ConnectorErrorKind::Auth)
    } else if e.contains("429") || e.contains("rate limit") || e.contains("too many requests") {
        Some(ConnectorErrorKind::RateLimit)
    } else if e.contains("403")
        || e.contains("forbidden")
        || e.contains("permission")
        || e.contains("scope")
    {
        Some(ConnectorErrorKind::Forbidden)
    } else if e.contains("connection refused")
        || e.contains("econnrefused")
        || e.contains("unreachable")
        || e.contains("connection closed")
        || e.contains("broken pipe")
        || e.contains("transport")
        || e.contains("server disconnected")
    {
        Some(ConnectorErrorKind::Unavailable)
    } else {
        None
    }
}

/// Composio-flavored actionable hint (reconnect via the OAuth toolkit → emits the
/// in-chat ‹‹COMPOSIO_RECONNECT›› card).
fn connector_error_hint(error: &str) -> Option<&'static str> {
    match classify_connector_error(error)? {
        ConnectorErrorKind::Auth => Some(
            "The connection has EXPIRED or is not authorized: tell the user to RECONNECT the service \
and emit on its own line the marker ‹‹COMPOSIO_RECONNECT››<slug>‹‹/COMPOSIO_RECONNECT›› with the toolkit \
slug. Do NOT retry the call.",
        ),
        ConnectorErrorKind::RateLimit => Some(
            "Rate limit reached: tell the user and suggest trying again in \
a few minutes. Do NOT retry immediately.",
        ),
        ConnectorErrorKind::Forbidden => Some(
            "Permission denied (insufficient scope): the connected account lacks the required permissions; \
suggest reconnecting the service granting the necessary scopes.",
        ),
        ConnectorErrorKind::Unavailable => Some(
            "The service is currently unreachable: tell the user and suggest trying again \
later. Do NOT retry immediately in a loop.",
        ),
    }
}

/// Stable string for the audit log / UI badge.
fn connector_error_kind_str(k: ConnectorErrorKind) -> &'static str {
    match k {
        ConnectorErrorKind::Auth => "auth",
        ConnectorErrorKind::RateLimit => "rate_limit",
        ConnectorErrorKind::Forbidden => "forbidden",
        ConnectorErrorKind::Unavailable => "unavailable",
    }
}

/// Append a connector tool execution to the audit log (roadmap #6). Best-effort —
/// logging must never break a tool call, so a failed lock/insert is swallowed.
fn record_connector_run(
    state: &AppState,
    thread_id: Option<&str>,
    tool: &str,
    kind: &str,
    ok: bool,
    error_kind: Option<&str>,
    dur: std::time::Duration,
) {
    if let Ok(store) = lock_store(state) {
        let _ = store.record_tool_run(&chat_store::ToolRunInput {
            thread_id,
            tool,
            kind,
            ok,
            error_kind,
            duration_ms: Some(dur.as_millis() as i64),
            summary: None,
        });
    }
}

/// MCP-flavored actionable hint. MCP servers don't have an OAuth toolkit slug, so
/// "reconnect" points to Impostazioni → Connettori → MCP instead of the card.
fn mcp_error_hint(error: &str) -> Option<&'static str> {
    match classify_connector_error(error)? {
        ConnectorErrorKind::Auth | ConnectorErrorKind::Forbidden => Some(
            "The MCP server rejected the credentials (expired or without permissions): tell the user to \
RECONNECT the server from Settings → Connectors → MCP (updating token/permissions). Do NOT retry.",
        ),
        ConnectorErrorKind::RateLimit => Some(
            "MCP server rate limit: tell the user and suggest trying again in a few \
minutes. Do NOT retry immediately.",
        ),
        ConnectorErrorKind::Unavailable => Some(
            "The MCP server is unreachable (off or disconnected): tell the user to check it / \
reconnect it from Settings → Connectors → MCP. Do NOT retry in a loop.",
        ),
    }
}

fn composio_execution_error(output: &serde_json::Value) -> Option<String> {
    if output.get("successful").and_then(|v| v.as_bool()) == Some(false) {
        let message = output
            .get("error")
            .and_then(|v| v.as_str())
            .filter(|s| !s.trim().is_empty())
            .map(str::to_string)
            .or_else(|| {
                output
                    .get("error")
                    .filter(|v| !v.is_null())
                    .map(|v| v.to_string())
            })
            .unwrap_or_else(|| "the service rejected the action".to_string());
        return Some(message.chars().take(400).collect());
    }
    None
}

#[derive(Debug, Deserialize)]
struct ComposioExecuteRequest {
    tool: String,
    #[serde(default)]
    arguments: serde_json::Value,
    /// "always" persists an allow-rule for this tool before executing.
    #[serde(default)]
    scope: Option<String>,
    /// When present, the originating chat message is rewritten on success so the
    /// confirmation card never reopens on reload (no risk of double-execution).
    #[serde(default)]
    thread_id: Option<String>,
    #[serde(default)]
    message_id: Option<String>,
}

const COMPOSIO_CONFIRM_OPEN: &str = "‹‹COMPOSIO_CONFIRM››";
const COMPOSIO_CONFIRM_CLOSE: &str = "‹‹/COMPOSIO_CONFIRM››";
const PAYMENT_APPROVAL_OPEN: &str = "‹‹PAYMENT_APPROVAL››";
const PAYMENT_APPROVAL_CLOSE: &str = "‹‹/PAYMENT_APPROVAL››";
const PAYMENT_APPROVAL_TTL_SECONDS: u64 = 300;
// VAULT_REVEAL_OPEN/CLOSE moved to engine::markers (ADR 0024 inc 5e.3); imported below.

#[cfg(test)]
fn payment_approval_marker(snapshot: &PaymentApprovalSnapshot) -> String {
    let marker = serde_json::json!({ "snapshot": snapshot });
    format!("{PAYMENT_APPROVAL_OPEN}{marker}{PAYMENT_APPROVAL_CLOSE}")
}

#[derive(Debug, Deserialize)]
struct VaultProposalActionRequest {
    category: String,
    label: String,
    redacted_preview: String,
    #[serde(default)]
    secret_value: Option<String>,
    #[serde(default)]
    pending_id: Option<String>,
    #[serde(default)]
    pin: Option<String>,
    #[serde(default)]
    thread_id: Option<String>,
    #[serde(default)]
    message_id: Option<String>,
    /// How to resolve a dedup conflict surfaced by a prior accept:
    /// "add" (create anyway), "update" (overwrite `record_id`), "ignore" (discard).
    /// Absent on the first attempt → the server runs dedup and may return a conflict.
    #[serde(default)]
    resolution: Option<String>,
    /// The existing record targeted by an "update"/"ignore" resolution.
    #[serde(default)]
    record_id: Option<String>,
}

/// Outcome of an accept. `status` drives the frontend:
/// - "created": a new record was stored (or overwritten via "update").
/// - "ignored": an identical (key+value) record already existed; nothing created.
/// - "conflict": a partial match needs the user to choose add/update/ignore.
#[derive(Debug, Serialize)]
struct VaultProposalAcceptResponse {
    ok: bool,
    status: String,
    record_id: String,
    category: String,
    label: String,
    redacted_preview: String,
    /// Set only when `status == "conflict"`: "key" (same category+field, different
    /// value) or "value" (same value, different key).
    #[serde(skip_serializing_if = "Option::is_none")]
    match_type: Option<String>,
    /// The pre-existing record involved in an "ignored"/"conflict" outcome.
    #[serde(skip_serializing_if = "Option::is_none")]
    existing: Option<VaultRecordSummary>,
}

